function getDashboardClientCacheKey(scope = "") {
  return String(scope || "default").trim() || "default";
}

function getCachedDashboardForScope(scope = "") {
  return dashboardClientCache.get(getDashboardClientCacheKey(scope)) || null;
}

function setCachedDashboardForScope(scope = "", dashboard = null) {
  if (!dashboard) return;
  const key = getDashboardClientCacheKey(scope);
  dashboardClientCache.delete(key);
  while (dashboardClientCache.size >= DASHBOARD_CLIENT_CACHE_MAX_ENTRIES) {
    const oldestKey = dashboardClientCache.keys().next().value;
    dashboardClientCache.delete(oldestKey);
  }
  dashboardClientCache.set(key, dashboard);
}

function clearCachedDashboardForScope(scope = "") {
  dashboardClientCache.delete(getDashboardClientCacheKey(scope));
}

function clearCachedDashboardForActionData(actionData, scope = "") {
  if (!shouldInvalidateDashboardClientCache(actionData)) return false;
  if (scope) {
    clearCachedDashboardForScope(scope);
  } else {
    dashboardClientCache.clear();
  }
  return true;
}

function shouldInvalidateDashboardClientCache(actionData) {
  if (actionData?.status !== "success") return false;
  if (actionData.invalidateDashboardCache === true) return true;
  if (actionData.queuedCount || actionData.analyzedCount) return true;
  if (actionData.actionRecordStatus) return true;
  const actionId = String(actionData?.action?.id || "");
  return [
    "add-shopify-product-candidate",
    "mark-resolved",
    "mark-unresolved",
    "delete-product-analysis",
    "add-watched-product",
    "add-watched-products",
    "remove-watched-product",
    "pause-watched-product",
    "resume-watched-product",
    "pause-all-watches",
    "resume-all-watches",
    "update-watch-settings",
    "toggle-watch-alerts",
    "run-watch-scan",
    "save-product-pulse-settings",
  ].includes(actionId);
}

function getDashboardDiagnosisJobLabel(job) {
  const status = String(job?.status || "").toLowerCase();
  if (status === "running") return "Product diagnosis is running";
  if (status === "queued") return "Product diagnosis is queued";
  return "Product diagnosis is already in progress";
}

function getProductDiagnosisRunningLabel(job) {
  const status = String(job?.status || "").toLowerCase();
  if (status === "queued") return "Diagnosis queued";
  return "Diagnosis running";
}

