export function ConnectScreen({ data, actionData }) {
  const navigation = useNavigation();
  const [records, setRecords] = useState(() => data?.connect?.records || []);
  const [activeModal, setActiveModal] = useState(null);
  const [localToast, setLocalToast] = useState(null);
  const [localConnecting, setLocalConnecting] = useState(false);
  const [csvPreview, setCsvPreview] = useState(null);
  const [csvGuideReturnModal, setCsvGuideReturnModal] = useState("csv");
  const persistConnectState = Boolean(data?.persistConnectState);
  const connectView = buildConnectViewData(records);
  const isSubmitting = navigation.state === "submitting";
  const pendingAction = isSubmitting ? String(navigation.formData?.get("_action") || "") : "";
  const pendingSourceKey = isSubmitting ? String(navigation.formData?.get("sourceKey") || "") : "";
  const judgeMeSource = connectView.signalCategories
    .flatMap((category) => category.sources)
    .find((source) => source.key === "judgemeReviews");
  const yotpoSource = connectView.signalCategories
    .flatMap((category) => category.sources)
    .find((source) => source.key === "yotpoReviews");
  const looxSource = connectView.signalCategories
    .flatMap((category) => category.sources)
    .find((source) => source.key === "looxReviews");
  const csvSource = connectView.signalCategories
    .flatMap((category) => category.sources)
    .find((source) => source.key === "csvReviews");
  const csvActionData = actionData?.providerKey === "csvReviews" ? actionData : null;

  useEffect(() => {
    setRecords(data?.connect?.records || []);
  }, [data?.connect?.records]);

  useEffect(() => {
    if (actionData?.status === "csv_preview" && actionData?.csvPreview) {
      setCsvPreview(actionData.csvPreview);
      setActiveModal("csv-preview");
      return;
    }
    if (actionData?.status === "success") {
      setCsvPreview(null);
      setActiveModal(null);
      dispatchProductPulseWizardEvent({
        type: "connect-provider-saved",
        provider: actionData.providerKey || "",
      });
    }
  }, [actionData]);

  const handleLocalJudgeMeConnect = (event) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const token = String(formData.get("privateApiToken") || "").trim();
    if (!token) {
      setLocalToast({ status: "validation_error", message: "Enter the Judge.me private API token before connecting." });
      return;
    }

    setLocalConnecting(true);
    window.setTimeout(() => {
      setRecords((current) => upsertLocalConnectionRecord(current, "judgemeReviews", {
        connected: true,
        active: true,
        ignored: false,
        available: true,
        health: "connected",
        config: { tokenLast4: token.slice(-4), provider: "Judge.me Reviews" },
        connectedAt: new Date().toISOString(),
        lastSyncedAt: new Date().toISOString(),
      }));
      setLocalConnecting(false);
      setActiveModal(null);
      setLocalToast({ status: "success", message: "Connected to Judge.me." });
      dispatchProductPulseWizardEvent({ type: "connect-provider-saved", provider: "judgemeReviews" });
    }, 450);
  };

  const handleLocalYotpoConnect = (event) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const storeId = String(formData.get("storeId") || "").trim();
    const apiSecret = String(formData.get("apiSecret") || "").trim();
    if (!storeId || !apiSecret) {
      setLocalToast({ status: "validation_error", message: "Enter the Yotpo Store ID/App Key and API secret before connecting." });
      return;
    }

    setLocalConnecting(true);
    window.setTimeout(() => {
      setRecords((current) => upsertLocalConnectionRecord(current, "yotpoReviews", {
        connected: true,
        active: true,
        ignored: false,
        available: true,
        health: "connected",
        config: {
          storeIdLast4: storeId.slice(-4),
          apiSecretLast4: apiSecret.slice(-4),
          provider: "Yotpo Reviews",
          reviewSampleCount: 1,
          reviewAccessVerified: true,
        },
        connectedAt: new Date().toISOString(),
        lastSyncedAt: new Date().toISOString(),
      }));
      setLocalConnecting(false);
      setActiveModal(null);
      setLocalToast({ status: "success", message: "Connected to Yotpo Reviews. Review API access verified." });
      dispatchProductPulseWizardEvent({ type: "connect-provider-saved", provider: "yotpoReviews" });
    }, 450);
  };

  const handleLocalLooxConnect = (event) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const publicStoreId = String(formData.get("publicStoreId") || "").trim();
    const apiSecret = String(formData.get("apiSecret") || "").trim();
    if (!publicStoreId || !apiSecret) {
      setLocalToast({ status: "validation_error", message: "Enter the Loox publicStoreId and API secret key before connecting." });
      return;
    }

    setLocalConnecting(true);
    window.setTimeout(() => {
      setRecords((current) => upsertLocalConnectionRecord(current, "looxReviews", {
        connected: true,
        active: true,
        ignored: false,
        available: true,
        health: "connected",
        config: {
          publicStoreId,
          publicStoreIdLast4: publicStoreId.slice(-4),
          apiSecretLast4: apiSecret.slice(-4),
          provider: "Loox Reviews",
          reviewSampleCount: 1,
          reviewAccessVerified: true,
        },
        connectedAt: new Date().toISOString(),
        lastSyncedAt: new Date().toISOString(),
      }));
      setLocalConnecting(false);
      setActiveModal(null);
      setLocalToast({ status: "success", message: "Connected to Loox Reviews. Review API access verified." });
      dispatchProductPulseWizardEvent({ type: "connect-provider-saved", provider: "looxReviews" });
    }, 450);
  };

  const handleLocalCsvUpload = (event) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const file = formData.get("csvFile");
    const originalFileName = file?.name || "reviews.csv";
    const fileName = CSV_REVIEW_IMPORT_DISPLAY_NAME;
    setLocalConnecting(true);
    window.setTimeout(() => {
      setCsvPreview({
        fileName: originalFileName,
        displayFileName: fileName,
        totalRows: 5,
        normalizedRowCount: 5,
        rejectedRowCount: 0,
        mapping: {
          product_handle: "product_handle",
          shopify_product_id: null,
          rating: "rating",
          review_title: "review_title",
          review_body: "review_body",
          review_date: "review_date",
          reviewer_name: "reviewer_name",
          review_status: "review_status",
        },
        productRelation: {
          status: "confirmed",
          label: "Shopify product handle confirmed",
          detail: "Matched sample rows to Shopify products.",
        },
        previewRows: [
          { sourceRow: "2", productHandle: "core-linen-trouser", rating: "5", reviewTitle: "Great fit", reviewBody: "Soft fabric and accurate sizing.", reviewDate: "2026-05-01", reviewerName: "Ana", reviewStatus: "published" },
          { sourceRow: "3", productHandle: "trail-run-vest", rating: "4", reviewTitle: "Good vest", reviewBody: "Comfortable and light for short runs.", reviewDate: "2026-05-02", reviewerName: "Leo", reviewStatus: "published" },
        ],
      });
      setLocalConnecting(false);
      setActiveModal("csv-preview");
    }, 450);
  };

  const handleLocalCsvConfirm = (event) => {
    event.preventDefault();
    const fileName = CSV_REVIEW_IMPORT_DISPLAY_NAME;
    setRecords((current) => upsertLocalConnectionRecord(current, "csvReviews", {
      connected: true,
      active: true,
      ignored: false,
      available: true,
      health: "connected",
      config: {
        fileName,
        displayFileName: fileName,
        originalFileName: csvPreview?.fileName || "reviews.csv",
        uploadedAt: new Date().toISOString(),
        normalizedRowCount: Number(csvPreview?.normalizedRowCount || 0),
        totalRowCount: Number(csvPreview?.totalRows || 0),
        rejectedRowCount: Number(csvPreview?.rejectedRowCount || 0),
        mappedColumns: csvPreview?.mapping || {},
      },
      connectedAt: new Date().toISOString(),
      lastSyncedAt: new Date().toISOString(),
    }));
    setActiveModal(null);
    setCsvPreview(null);
    setLocalToast({ status: "success", message: `${fileName} was processed and ${Number(csvPreview?.normalizedRowCount || 0)} review rows were normalized.` });
    dispatchProductPulseWizardEvent({ type: "connect-provider-saved", provider: "csvReviews" });
  };

  const handleOpenCsvGuide = (returnModal = activeModal || "csv") => {
    setCsvGuideReturnModal(returnModal);
    setActiveModal("csv-guide");
  };

  const handleLocalActiveChange = (source, active) => {
    setRecords((current) => upsertLocalConnectionRecord(current, source.key, {
      connected: source.connected,
      available: source.available,
      active,
      health: active ? "connected" : "disabled",
      disabledAt: active ? null : new Date().toISOString(),
    }));
  };

  return (
    <FullWidthPage label="Connect" className="ppConnectPage">
      <ScreenShell className="ppDashboard ppConnectScreen">
        <ProductPulseToast actionData={localToast || (actionData?.status === "csv_preview" ? null : actionData)} />

        <div className="ppConnectHeader">
          <div>
            <h1>Connect your sources</h1>
            <p>Select the customer signals ProductPulse will analyze.</p>
          </div>
        </div>

        <div className="ppConnectLayout">
          <div className="ppConnectMain">
            {connectView.signalCategories.map((category) => (
              <ConnectCategoryCard
                key={category.id}
                category={category}
                onOpenJudgeMe={() => setActiveModal("judgeme")}
                onOpenYotpo={() => setActiveModal("yotpo")}
                onOpenLoox={() => setActiveModal("loox")}
                onOpenCsv={() => setActiveModal("csv")}
                onLocalActiveChange={handleLocalActiveChange}
                persistConnectState={persistConnectState}
                pendingSourceKey={pendingSourceKey}
              />
            ))}
            <ConnectCategoryCard
              category={connectView.productDataCategory}
              locked
              persistConnectState={persistConnectState}
              pendingSourceKey={pendingSourceKey}
            />
          </div>

          <aside className="ppConnectAside">
            <s-section padding="none">
              <ConnectCoverageCard
                categories={connectView.signalCategories}
                coverage={connectView.coverage}
                activeWeight={connectView.activeWeight}
              />
            </s-section>

            <s-section padding="none">
              <div className="ppConnectInfoCard">
                <h2>What better coverage unlocks</h2>
                <div className="ppCoverageUnlockList">
                  {coverageUnlocks.map((item) => (
                    <p key={item.title}>
                      <s-icon type={item.icon} size="small"></s-icon>
                      <span>
                        <strong>{item.title}</strong>
                        {item.detail}
                      </span>
                    </p>
                  ))}
                </div>
              </div>
            </s-section>

          </aside>
        </div>

        {activeModal === "judgeme" && (
          <JudgeMeConnectionModal
            source={judgeMeSource}
            persistConnectState={persistConnectState}
            isConnecting={pendingAction === "connect-judgeme" || localConnecting}
            onCancel={() => setActiveModal(null)}
            onLocalSubmit={handleLocalJudgeMeConnect}
          />
        )}

        {activeModal === "yotpo" && (
          <YotpoConnectionModal
            source={yotpoSource}
            shopDomain={data?.shop}
            persistConnectState={persistConnectState}
            isConnecting={pendingAction === "connect-yotpo" || localConnecting}
            onCancel={() => setActiveModal(null)}
            onLocalSubmit={handleLocalYotpoConnect}
          />
        )}

        {activeModal === "loox" && (
          <LooxConnectionModal
            source={looxSource}
            shopDomain={data?.shop}
            persistConnectState={persistConnectState}
            isConnecting={pendingAction === "connect-loox" || localConnecting}
            onCancel={() => setActiveModal(null)}
            onLocalSubmit={handleLocalLooxConnect}
          />
        )}

        {activeModal === "csv" && (
          <CsvUploadModal
            source={csvSource}
            persistConnectState={persistConnectState}
            isUploading={pendingAction === "preview-csv" || localConnecting}
            actionData={csvActionData}
            onCancel={() => setActiveModal(null)}
            onOpenGuide={() => handleOpenCsvGuide("csv")}
            onLocalSubmit={handleLocalCsvUpload}
          />
        )}

        {activeModal === "csv-preview" && csvPreview && (
          <CsvReviewPreviewModal
            preview={csvPreview}
            persistConnectState={persistConnectState}
            isConfirming={pendingAction === "confirm-csv"}
            actionData={csvActionData}
            onCancel={() => {
              setCsvPreview(null);
              setActiveModal("csv");
            }}
            onClose={() => {
              setCsvPreview(null);
              setActiveModal(null);
            }}
            onOpenGuide={() => handleOpenCsvGuide("csv-preview")}
            onLocalConfirm={handleLocalCsvConfirm}
          />
        )}

        {activeModal === "csv-guide" && (
          <CsvFormatGuideModal
            onClose={() => setActiveModal(csvPreview && csvGuideReturnModal === "csv-preview" ? "csv-preview" : "csv")}
          />
        )}
      </ScreenShell>
    </FullWidthPage>
  );
}

function isQuickScanCsvReviewSourceAvailable(data = {}) {
  if (data.quickScanCsvReviews) return Boolean(data.quickScanCsvReviews.available);
  const sources = Array.isArray(data.sourceGroups)
    ? data.sourceGroups.flatMap((group) => group.sources || [])
    : [];
  const csvSource = sources.find((source) => source.key === "csvReviews" || source.sourceKey === "csvReviews");
  if (!csvSource) return false;
  return Boolean(csvSource.connected && csvSource.active !== false);
}

export function ProductsScreen({ data, filters = {}, actionData }) {
  const revalidator = useRevalidator();
  const navigation = useNavigation();
  const submit = useSubmit();
  const shopifyProductSearchFetcher = useFetcher();
  const productTablesFetcher = useFetcher();
  const location = useLocation();
  const [localFastScan, setLocalFastScan] = useState(false);
  const [localSortConfig, setLocalSortConfig] = useState(null);
  const [openActionProduct, setOpenActionProduct] = useState(null);
  const [selectedProducts, setSelectedProducts] = useState(() => new Set());
  const [searchOpen, setSearchOpen] = useState(Boolean(filters.query));
  const [searchValue, setSearchValue] = useState(filters.query || "");
  const [shopifyProductSearchOpen, setShopifyProductSearchOpen] = useState(false);
  const [shopifyProductSearchQuery, setShopifyProductSearchQuery] = useState("");
  const [addedCandidateProductIds, setAddedCandidateProductIds] = useState(() => new Set());
  const [resolvedProductOverrides, setResolvedProductOverrides] = useState(() => new Map());
  const shopifyProductSearchSubmitRef = useRef(shopifyProductSearchFetcher.submit);
  const productTableSearchInputRef = useRef(null);
  const [quickScanConfirmation, setQuickScanConfirmation] = useState(false);
  const [quickScanCsvWarning, setQuickScanCsvWarning] = useState(false);
  const [analysisConfirmation, setAnalysisConfirmation] = useState(null);
  const [watchlistConfirmation, setWatchlistConfirmation] = useState(null);
  const [deleteAnalysisConfirmation, setDeleteAnalysisConfirmation] = useState(null);
  const [diagnosisQueueOverlayTimedOut, setDiagnosisQueueOverlayTimedOut] = useState(false);
  const [diagnosisQueueOverlayDismissed, setDiagnosisQueueOverlayDismissed] = useState(false);
  const productTablesLoadRef = useRef(productTablesFetcher.load);
  const lastProductTablesRequestKeyRef = useRef("");
  const requestedProductsTab = normalizeProductsTab(filters.activeTab);
  const [activeProductsTab, setActiveProductsTab] = useState(() => {
    if (requestedProductsTab) return requestedProductsTab;
    if (hasActiveProductTableFilters(filters.resolved)) return "resolved";
    if (hasActiveProductTableFilters(filters.candidates)) return "candidates";
    return "full";
  });
  const productTablesDeferred = Boolean(data.productTablesDeferred);
  const productTablesCacheScope = data.shop || data.shopDomain || data.storeDomain || "";
  const productTablesRequestKey = useMemo(() => {
    return buildProductTablesClientRequestKey(filters, activeProductsTab);
  }, [activeProductsTab, filters]);
  const productTablesFetchHref = useMemo(() => {
    const params = new URLSearchParams(location.search);
    params.set("_productTables", "1");
    params.set("tab", activeProductsTab || "full");
    const query = params.toString();
    return `${location.pathname || "/app/products"}${query ? `?${query}` : ""}`;
  }, [activeProductsTab, location.pathname, location.search]);
  const fetchedProductTables = productTablesFetcher.data?.productTables;
  const fetchedProductTablesFresh = productTablesDeferred
    && fetchedProductTables
    && productTablesFetcher.data?.requestKey === productTablesRequestKey;
  if (fetchedProductTablesFresh) {
    setCachedProductTablesForRequest(productTablesCacheScope, productTablesRequestKey, fetchedProductTables);
  }
  const cachedProductTables = productTablesDeferred
    ? getCachedProductTablesForRequest(productTablesCacheScope, productTablesRequestKey)
    : null;
  const fallbackProductTables = productTablesDeferred
    ? getLatestCachedProductTablesForScope(productTablesCacheScope)
    : null;
  const productTablesForRequest = fetchedProductTablesFresh ? fetchedProductTables : cachedProductTables;
  const productTableData = getProductTableDataForRender(productTablesForRequest, fallbackProductTables, data.productTable, "productTable");
  const candidateProductTableData = getProductTableDataForRender(productTablesForRequest, fallbackProductTables, data.candidateProductTable, "candidateProductTable");
  const resolvedProductTableData = getProductTableDataForRender(productTablesForRequest, fallbackProductTables, data.resolvedProductTable, "resolvedProductTable");
  const productTablesLoading = productTablesDeferred && !productTablesForRequest;
  const productTableRows = productTableData?.rows;
  const candidateTableRows = candidateProductTableData?.rows;
  const resolvedTableRows = resolvedProductTableData?.rows;
  const productRows = useMemo(() => productTableRows || [], [productTableRows]);
  const candidateRows = useMemo(() => candidateTableRows || [], [candidateTableRows]);
  const resolvedRows = useMemo(() => resolvedTableRows || [], [resolvedTableRows]);
  const fastScanJobActiveRef = useRef(false);
  const allVisibleRows = useMemo(() => {
    const rowsByKey = new Map();
    [...productRows, ...candidateRows, ...resolvedRows].forEach((product) => {
      const key = getProductActionKey(product);
      if (key && !rowsByKey.has(key)) rowsByKey.set(key, product);
    });
    return Array.from(rowsByKey.values());
  }, [productRows, candidateRows, resolvedRows]);
  const productCount = productTableData?.total ?? productRows.length;
  const candidateCount = candidateProductTableData?.total ?? candidateRows.length;
  const resolvedCount = resolvedProductTableData?.total ?? resolvedRows.length;
  const totalAllProducts = productTableData?.totalAll ?? productCount;
  const candidateTotalAllProducts = candidateProductTableData?.totalAll ?? candidateCount;
  const resolvedTotalAllProducts = resolvedProductTableData?.totalAll ?? resolvedCount;
  const filterOptions = productTableData?.filterOptions || {};
  const candidateFilters = filters.candidates || {};
  const resolvedFilters = filters.resolved || {};
  const candidateFilterOptions = candidateProductTableData?.filterOptions || filterOptions;
  const resolvedFilterOptions = resolvedProductTableData?.filterOptions || filterOptions;
  const page = productTableData?.page || 1;
  const rowsPerPage = normalizeProductTablePageSize(productTableData?.rowsPerPage ?? filters.rows);
  const totalPages = productTableData?.totalPages || 1;
  const candidatePage = candidateProductTableData?.page || 1;
  const candidateRowsPerPage = normalizeProductTablePageSize(candidateProductTableData?.rowsPerPage ?? candidateFilters.rows);
  const candidateTotalPages = candidateProductTableData?.totalPages || 1;
  const resolvedPage = resolvedProductTableData?.page || 1;
  const resolvedRowsPerPage = normalizeProductTablePageSize(resolvedProductTableData?.rowsPerPage ?? resolvedFilters.rows);
  const resolvedTotalPages = resolvedProductTableData?.totalPages || 1;
  const activeScanJob = productTableData?.activeScanJob || null;
  const activeDiagnosisJobs = [
    ...(productTableData?.activeDiagnosisJobs || []),
    ...(candidateProductTableData?.activeDiagnosisJobs || []),
    ...(resolvedProductTableData?.activeDiagnosisJobs || []),
  ];
  const persistProductJobs = Boolean(data.persistProductJobs);
  const pendingFastScan = navigation.state === "submitting" && navigation.formData?.get("_action") === "fast-product-scan";
  const pendingBulkAnalyze = navigation.state !== "idle" && navigation.formData?.get("_action") === "bulk-diagnose";
  const pendingCandidateAdd = navigation.state === "submitting" && navigation.formData?.get("_action") === "add-shopify-product-candidate";
  const pendingWatchlistAction = navigation.state === "submitting" && ["add-to-watchlist", "add-selected-to-watchlist", "remove-from-watchlist"].includes(String(navigation.formData?.get("_action") || ""));
  const pendingBulkWatchlistAdd = navigation.state === "submitting" && navigation.formData?.get("_action") === "add-selected-to-watchlist";
  const pendingDeleteAnalysis = navigation.state === "submitting" && navigation.formData?.get("_action") === "delete-product-analysis";
  const pendingAnalyzeIds = pendingBulkAnalyze ? Array.from(navigation.formData?.getAll("productId") || []).map(String) : [];
  const showDiagnosisQueueOverlay = pendingBulkAnalyze && !diagnosisQueueOverlayDismissed;
  const fastScanRunning = Boolean(activeScanJob) || pendingFastScan || localFastScan;
  const fastScanJobActive = Boolean(activeScanJob) || localFastScan;
  const quickScanCsvAvailable = isQuickScanCsvReviewSourceAvailable(data);
  const sortConfig = localSortConfig || (filters.sort ? { key: filters.sort, direction: filters.direction || "desc" } : null);
  const [localCandidateSortConfig, setLocalCandidateSortConfig] = useState(null);
  const [localResolvedSortConfig, setLocalResolvedSortConfig] = useState(null);
  const candidateSortConfig = localCandidateSortConfig || (candidateFilters.sort ? { key: candidateFilters.sort, direction: candidateFilters.direction || "desc" } : null);
  const resolvedSortConfig = localResolvedSortConfig || (resolvedFilters.sort ? { key: resolvedFilters.sort, direction: resolvedFilters.direction || "desc" } : null);
  const selectedProductRows = useMemo(
    () => allVisibleRows.filter((product) => selectedProducts.has(getProductActionKey(product))),
    [allVisibleRows, selectedProducts],
  );
  const selectedCount = selectedProducts.size;
  const selectedWatchlistEligibleCount = selectedProductRows.filter((product) => (
    getWatchlistProductGid(product) && canAddProductToWatchlist(product)
  )).length;
  const currentSearchQuery = filters.query || "";
  const currentCandidateSearchQuery = candidateFilters.query || "";
  const currentResolvedSearchQuery = resolvedFilters.query || "";
  const [candidateSearchOpen, setCandidateSearchOpen] = useState(Boolean(currentCandidateSearchQuery));
  const [candidateSearchValue, setCandidateSearchValue] = useState(currentCandidateSearchQuery);
  const [resolvedSearchOpen, setResolvedSearchOpen] = useState(Boolean(currentResolvedSearchQuery));
  const [resolvedSearchValue, setResolvedSearchValue] = useState(currentResolvedSearchQuery);
  const candidateTableSearchInputRef = useRef(null);
  const resolvedTableSearchInputRef = useRef(null);
  const normalizedShopifyProductSearchQuery = shopifyProductSearchQuery.trim();
  const shopifyProductSearchData = shopifyProductSearchFetcher.data || {};
  const shopifyProductSearchResponseQuery = String(shopifyProductSearchData.query || "");
  const shopifyProductSearchHasQuery = normalizedShopifyProductSearchQuery.length >= 2;
  const shopifyProductSearchHasFreshResponse = shopifyProductSearchHasQuery
    && shopifyProductSearchResponseQuery === normalizedShopifyProductSearchQuery;
  const shopifyProductSearchResults = shopifyProductSearchHasFreshResponse
    ? shopifyProductSearchData.products || []
    : [];
  const shopifyProductSearchPending = shopifyProductSearchHasQuery
    && (shopifyProductSearchFetcher.state !== "idle" || !shopifyProductSearchHasFreshResponse);
  const shopifyProductSearchError = shopifyProductSearchHasFreshResponse && shopifyProductSearchData.status === "validation_error"
    ? shopifyProductSearchData.message
    : "";
  const submitProductFilters = (overrides = {}, table = "main") => {
    const rowCount = table === "candidates" ? candidateRowsPerPage : table === "resolved" ? resolvedRowsPerPage : rowsPerPage;
    submit(buildProductFilterFormData(filters, { rows: String(rowCount), ...overrides }, table), { method: "get", replace: true });
  };

  const handleProductsTabChange = (tabId) => {
    const nextTab = normalizeProductsTab(tabId) || "full";
    if (nextTab === activeProductsTab) return;
    setActiveProductsTab(nextTab);
    setSelectedProducts(new Set());
    submit(buildProductFilterFormData(filters, {}, getProductTableScopeForTab(nextTab)), { method: "get", replace: true });
  };

  useEffect(() => {
    productTablesLoadRef.current = productTablesFetcher.load;
  }, [productTablesFetcher.load]);

  useEffect(() => {
    if (!productTablesDeferred) return;
    const requestKey = productTablesFetcher.data?.requestKey;
    const productTables = productTablesFetcher.data?.productTables;
    if (!requestKey || !productTables) return;

    setCachedProductTablesForRequest(productTablesCacheScope, requestKey, productTables);
    if (lastProductTablesRequestKeyRef.current === requestKey) {
      lastProductTablesRequestKeyRef.current = "";
    }
  }, [productTablesCacheScope, productTablesDeferred, productTablesFetcher.data]);

  useEffect(() => {
    if (!productTablesDeferred) return;
    if (getCachedProductTablesForRequest(productTablesCacheScope, productTablesRequestKey)) return;
    if (lastProductTablesRequestKeyRef.current === productTablesRequestKey) return;
    lastProductTablesRequestKeyRef.current = productTablesRequestKey;
    productTablesLoadRef.current(productTablesFetchHref);
  }, [productTablesCacheScope, productTablesDeferred, productTablesFetchHref, productTablesRequestKey]);

  useEffect(() => {
    const hasProductDiagnosisJobs = activeDiagnosisJobs.length > 0 || allVisibleRows.some((product) => product.diagnosisJob);
    if ((!activeScanJob && !hasProductDiagnosisJobs) || !persistProductJobs) return undefined;
    const interval = window.setInterval(() => {
      if (document.hidden) return;
      if (productTablesDeferred) {
        lastProductTablesRequestKeyRef.current = productTablesRequestKey;
        productTablesLoadRef.current(productTablesFetchHref);
      } else {
        revalidator.revalidate();
      }
    }, PRODUCT_TABLE_ACTIVE_JOB_REFRESH_MS);
    return () => window.clearInterval(interval);
  }, [activeDiagnosisJobs.length, activeScanJob, persistProductJobs, allVisibleRows, productTablesDeferred, productTablesFetchHref, productTablesRequestKey, revalidator]);

  useEffect(() => {
    const handleFinishedJobs = (event) => {
      if (!clearCachedProductTablesForFinishedJobs(event?.detail?.jobs || [])) return;
      if (productTablesDeferred) {
        lastProductTablesRequestKeyRef.current = productTablesRequestKey;
        productTablesLoadRef.current(productTablesFetchHref);
      } else {
        revalidator.revalidate();
      }
    };
    window.addEventListener("productpulse:jobs-finished", handleFinishedJobs);
    return () => window.removeEventListener("productpulse:jobs-finished", handleFinishedJobs);
  }, [productTablesDeferred, productTablesFetchHref, productTablesRequestKey, revalidator]);

  useEffect(() => {
    if (!pendingBulkAnalyze) {
      setDiagnosisQueueOverlayTimedOut(false);
      setDiagnosisQueueOverlayDismissed(false);
      return undefined;
    }

    setDiagnosisQueueOverlayTimedOut(false);
    setDiagnosisQueueOverlayDismissed(false);
    const timeout = window.setTimeout(() => setDiagnosisQueueOverlayTimedOut(true), 60_000);
    return () => window.clearTimeout(timeout);
  }, [pendingBulkAnalyze, pendingAnalyzeIds.length]);

  useEffect(() => {
    const wasActive = fastScanJobActiveRef.current;
    if (fastScanJobActive && !wasActive) {
      dispatchProductPulseWizardEvent({ type: "quick-scan-job-started" });
    }
    if (!fastScanJobActive && wasActive) {
      dispatchProductPulseWizardEvent({ type: "quick-scan-job-finished" });
    }
    fastScanJobActiveRef.current = fastScanJobActive;
  }, [fastScanJobActive]);

  useEffect(() => {
    setLocalSortConfig(null);
  }, [filters.sort, filters.direction]);

  useEffect(() => {
    setLocalCandidateSortConfig(null);
  }, [candidateFilters.sort, candidateFilters.direction]);

  useEffect(() => {
    setLocalResolvedSortConfig(null);
  }, [resolvedFilters.sort, resolvedFilters.direction]);

  useEffect(() => {
    if (requestedProductsTab) setActiveProductsTab(requestedProductsTab);
  }, [requestedProductsTab]);

  useEffect(() => {
    setSearchValue(currentSearchQuery);
    setSearchOpen(Boolean(currentSearchQuery));
  }, [currentSearchQuery]);

  useEffect(() => {
    setCandidateSearchValue(currentCandidateSearchQuery);
    setCandidateSearchOpen(Boolean(currentCandidateSearchQuery));
  }, [currentCandidateSearchQuery]);

  useEffect(() => {
    setResolvedSearchValue(currentResolvedSearchQuery);
    setResolvedSearchOpen(Boolean(currentResolvedSearchQuery));
  }, [currentResolvedSearchQuery]);

  useEffect(() => {
    if (!searchOpen) return;
    productTableSearchInputRef.current?.focus();
    productTableSearchInputRef.current?.select();
  }, [searchOpen]);

  useEffect(() => {
    if (!candidateSearchOpen) return;
    candidateTableSearchInputRef.current?.focus();
    candidateTableSearchInputRef.current?.select();
  }, [candidateSearchOpen]);

  useEffect(() => {
    if (!resolvedSearchOpen) return;
    resolvedTableSearchInputRef.current?.focus();
    resolvedTableSearchInputRef.current?.select();
  }, [resolvedSearchOpen]);

  useEffect(() => {
    if (searchValue === currentSearchQuery) return undefined;
    const timeout = window.setTimeout(() => {
      submit(
        buildProductFilterFormData(filters, { rows: String(rowsPerPage), query: searchValue, page: "1" }),
        { method: "get", replace: true },
      );
    }, 260);
    return () => window.clearTimeout(timeout);
  }, [
    searchValue,
    currentSearchQuery,
    filters.risk,
    filters.status,
    filters.issue,
    filters.vendor,
    filters.collection,
    filters.rows,
    filters.sort,
    filters.direction,
    filters,
    rowsPerPage,
    submit,
  ]);

  useEffect(() => {
    if (candidateSearchValue === currentCandidateSearchQuery) return undefined;
    const timeout = window.setTimeout(() => {
      submit(
        buildProductFilterFormData(filters, { rows: String(candidateRowsPerPage), query: candidateSearchValue, page: "1" }, "candidates"),
        { method: "get", replace: true },
      );
    }, 260);
    return () => window.clearTimeout(timeout);
  }, [
    candidateSearchValue,
    currentCandidateSearchQuery,
    candidateFilters.risk,
    candidateFilters.status,
    candidateFilters.issue,
    candidateFilters.vendor,
    candidateFilters.collection,
    candidateFilters.rows,
    candidateFilters.sort,
    candidateFilters.direction,
    filters,
    candidateRowsPerPage,
    submit,
  ]);

  useEffect(() => {
    if (resolvedSearchValue === currentResolvedSearchQuery) return undefined;
    const timeout = window.setTimeout(() => {
      submit(
        buildProductFilterFormData(filters, { rows: String(resolvedRowsPerPage), query: resolvedSearchValue, page: "1" }, "resolved"),
        { method: "get", replace: true },
      );
    }, 260);
    return () => window.clearTimeout(timeout);
  }, [
    resolvedSearchValue,
    currentResolvedSearchQuery,
    resolvedFilters.risk,
    resolvedFilters.status,
    resolvedFilters.issue,
    resolvedFilters.vendor,
    resolvedFilters.collection,
    resolvedFilters.rows,
    resolvedFilters.sort,
    resolvedFilters.direction,
    filters,
    resolvedRowsPerPage,
    submit,
  ]);

  useEffect(() => {
    shopifyProductSearchSubmitRef.current = shopifyProductSearchFetcher.submit;
  }, [shopifyProductSearchFetcher.submit]);

  useEffect(() => {
    if (!shopifyProductSearchOpen) return undefined;
    const query = shopifyProductSearchQuery.trim();
    if (query.length < 2) return undefined;

    const timeout = window.setTimeout(() => {
      const formData = new FormData();
      formData.set("_action", "search-shopify-products");
      formData.set("query", query);
      shopifyProductSearchSubmitRef.current(formData, { method: "post" });
    }, 300);

    return () => window.clearTimeout(timeout);
  }, [shopifyProductSearchOpen, shopifyProductSearchQuery]);

  useEffect(() => {
    clearCachedDashboardForActionData(actionData, productTablesCacheScope);
    announceProductPulseJobs(actionData);
    if (actionData?.status === "success" && (actionData?.analyzedCount || actionData?.queuedCount)) {
      setSelectedProducts(new Set());
      setAnalysisConfirmation(null);
      setShopifyProductSearchOpen(false);
    }
    if (actionData?.status === "success" && actionData?.action?.id === "add-shopify-product-candidate" && actionData.action.productGid) {
      setAddedCandidateProductIds((current) => {
        const next = new Set(current);
        next.add(actionData.action.productGid);
        return next;
      });
    }
    if (["add-watched-product", "add-watched-products", "remove-watched-product"].includes(String(actionData?.action?.id || ""))) {
      setWatchlistConfirmation(null);
      setOpenActionProduct(null);
    }
    if (actionData?.status === "success" && ["mark-resolved", "mark-unresolved"].includes(String(actionData?.action?.id || ""))) {
      const actionId = String(actionData.action.id || "");
      const payload = actionData.action.payload || {};
      const productKeys = [payload.productGid, actionData.action.productGid, payload.handle, actionData.action.handle]
        .filter(Boolean)
        .map(String);

      setOpenActionProduct(null);
      if (productKeys.length) {
        setResolvedProductOverrides((current) => {
          const next = new Map(current);
          productKeys.forEach((productKey) => {
            next.set(productKey, actionId === "mark-resolved"
              ? {
                  resolvedAt: payload.resolvedAt || new Date().toISOString(),
                  resolvedLabel: "Resolved just now",
                }
              : {
                  resolvedAt: null,
                  resolvedLabel: null,
                });
          });
          return next;
        });
      }
    }
    if (actionData?.status === "success" && actionData?.action?.id === "delete-product-analysis") {
      setDeleteAnalysisConfirmation(null);
      setOpenActionProduct(null);
      const deletedKey = String(actionData.action.productGid || actionData.action.handle || "");
      if (deletedKey) {
        setSelectedProducts((current) => {
          const next = new Set(current);
          next.delete(deletedKey);
          return next;
        });
      }
    }
    if (actionData?.status === "success" && actionData?.action?.id === "add-watched-products") {
      setSelectedProducts(new Set());
    }
  }, [actionData, productTablesCacheScope]);

  useEffect(() => {
    if (!productTablesDeferred || actionData?.status !== "success") return;
    const actionId = String(actionData?.action?.id || "");
    const shouldRefreshTables = Boolean(actionData?.analyzedCount || actionData?.queuedCount)
      || [
        "add-shopify-product-candidate",
        "add-watched-product",
        "add-watched-products",
        "remove-watched-product",
        "mark-resolved",
        "mark-unresolved",
        "delete-product-analysis",
      ].includes(actionId);
    if (shouldRefreshTables) {
      clearCachedProductTablesForScope(productTablesCacheScope);
      lastProductTablesRequestKeyRef.current = productTablesRequestKey;
      productTablesLoadRef.current(productTablesFetchHref);
    }
  }, [actionData, productTablesCacheScope, productTablesDeferred, productTablesFetchHref, productTablesRequestKey]);

  const handleLocalFastScan = () => {
    setLocalFastScan(true);
    window.setTimeout(() => setLocalFastScan(false), 15_000);
  };

  const handleStartFastScan = () => {
    if (fastScanRunning) return;
    if (!quickScanCsvAvailable) {
      setQuickScanCsvWarning(true);
      return;
    }
    setQuickScanConfirmation(true);
  };

  const handleContinueQuickScanWithoutCsv = () => {
    setQuickScanCsvWarning(false);
    setQuickScanConfirmation(true);
  };

  const handleUploadCsvBeforeQuickScan = () => {
    setQuickScanCsvWarning(false);
    dispatchProductPulseWizardEvent({ type: "quick-scan-upload-csv-first" });
  };

  const handleConfirmFastScan = () => {
    if (fastScanRunning) return;
    setQuickScanConfirmation(false);
    dispatchProductPulseWizardEvent({ type: "quick-scan-started" });
    if (!persistProductJobs) {
      handleLocalFastScan();
      return;
    }

    const formData = new FormData();
    formData.set("_action", "fast-product-scan");
    submit(formData, { method: "post" });
  };

  const handleSort = (key, table = "main") => {
    const currentSortConfig = table === "candidates" ? candidateSortConfig : table === "resolved" ? resolvedSortConfig : sortConfig;
    const nextDirection = currentSortConfig?.key === key && currentSortConfig.direction === "desc" ? "asc" : "desc";
    if (table === "candidates") {
      setLocalCandidateSortConfig({ key, direction: nextDirection });
    } else if (table === "resolved") {
      setLocalResolvedSortConfig({ key, direction: nextDirection });
    } else {
      setLocalSortConfig({ key, direction: nextDirection });
    }
    submitProductFilters({ sort: key, direction: nextDirection, page: "1" }, table);
  };

  const handleFilterChange = (event, table = "main") => {
    const target = event.target;
    if (!target?.name) return;
    submitProductFilters({ [target.name]: target.value, page: "1" }, table);
  };

  const getRowsSelectionState = (rows) => {
    const keys = rows.map(getProductActionKey);
    return {
      keys,
      selectedCount: rows.filter((product) => selectedProducts.has(getProductActionKey(product))).length,
      allSelected: keys.length > 0 && keys.every((key) => selectedProducts.has(key)),
      hasSelection: keys.some((key) => selectedProducts.has(key)),
    };
  };

  const handleToggleRows = (rows) => {
    const selectionState = getRowsSelectionState(rows);
    setSelectedProducts((current) => {
      const next = new Set(current);
      if (selectionState.allSelected) {
        selectionState.keys.forEach((key) => next.delete(key));
      } else {
        selectionState.keys.forEach((key) => next.add(key));
      }
      return next;
    });
  };

  const handleToggleProduct = (product) => {
    const key = getProductActionKey(product);
    setSelectedProducts((current) => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  const handleAnalyzeSelected = () => {
    if (!selectedCount || pendingBulkAnalyze) return;
    const selectedIds = Array.from(selectedProducts);
    setAnalysisConfirmation({
      mode: "bulk",
      title: "Confirm selected Product Diagnosis",
      products: selectedIds,
      productTitles: selectedProductRows.map((product) => product.title),
      count: selectedIds.length,
      credits: selectedIds.length,
    });
  };

  const handleAddSelectedToWatchlist = () => {
    if (!selectedCount || pendingBulkWatchlistAdd) return;
    const products = selectedProductRows
      .filter((product) => getWatchlistProductGid(product) && canAddProductToWatchlist(product))
      .map((product) => ({
        productGid: getWatchlistProductGid(product),
        title: product.title,
        handle: product.handle,
        sku: product.sku,
        imageUrl: product.imageUrl,
        imageAlt: product.imageAlt || product.title,
      }));
    if (!products.length) return;

    const formData = new FormData();
    formData.set("_action", "add-selected-to-watchlist");
    formData.set("products", JSON.stringify(products));
    submit(formData, { method: "post" });
  };

  const handleAnalyzeProduct = (product) => {
    if (pendingBulkAnalyze) return;
    const productId = getProductActionKey(product);
    setOpenActionProduct(null);
    setAnalysisConfirmation({
      mode: "single",
      title: "Confirm Product Diagnosis",
      products: [productId],
      productTitles: [product.title],
      count: 1,
      credits: product.credits || 1,
    });
  };

  const handleRequestWatchlistToggle = (product) => {
    const productGid = getWatchlistProductGid(product);
    if (!productGid || pendingWatchlistAction) return;
    if (!product.isWatched && !canAddProductToWatchlist(product)) return;
    setOpenActionProduct(null);
    setWatchlistConfirmation({
      mode: product.isWatched ? "remove" : "add",
      product: { ...product, productGid },
    });
  };

  const handleRequestDeleteAnalysis = (product) => {
    if (!product) return;
    setOpenActionProduct(null);
    setDeleteAnalysisConfirmation({ product });
  };

  const handleAnalyzeShopifyProduct = (product) => {
    if (pendingBulkAnalyze || !product?.id) return;
    setShopifyProductSearchOpen(false);
    setAnalysisConfirmation({
      mode: "shopify-product",
      title: "Confirm Product Diagnosis",
      products: [product.id],
      productTitles: [product.title],
      count: 1,
      credits: 1,
    });
  };

  const handleAddShopifyProductCandidate = (product) => {
    if (pendingCandidateAdd || !product?.id) return;
    setAddedCandidateProductIds((current) => {
      const next = new Set(current);
      next.add(product.id);
      return next;
    });
    const formData = new FormData();
    formData.set("_action", "add-shopify-product-candidate");
    formData.set("productId", product.id);
    submit(formData, { method: "post" });
  };

  const handleConfirmAnalysis = () => {
    if (!analysisConfirmation?.products?.length || pendingBulkAnalyze) return;
    dispatchProductPulseWizardEvent({ type: "deep-scan-started" });
    setAnalysisConfirmation(null);
    const formData = new FormData();
    formData.set("_action", "bulk-diagnose");
    analysisConfirmation.products.forEach((productId) => formData.append("productId", productId));
    submit(formData, { method: "post" });
  };

  const renderProductFilters = ({ table = "main", tableFilters = {}, tableFilterOptions = {}, includeActions = false }) => (
    <s-section padding="none">
      <div className={`ppProductsToolbar ${table === "candidates" ? "ppProductsCandidatesToolbar" : table === "resolved" ? "ppProductsResolvedToolbar" : ""}`.trim()}>
        <div className="ppProductsFilters" aria-label={`${getProductTableLabel(table)} filters`}>
          <div className="ppProductsFilterPills">
            <ProductFilterPillGroup
              name="risk"
              label="Risk"
              value={tableFilters.risk || "all"}
              options={tableFilterOptions.risks}
              onChange={(value) => submitProductFilters({ risk: value, page: "1" }, table)}
            />
            <ProductFilterPillGroup
              name="status"
              label="Status"
              value={tableFilters.status || "all"}
              options={tableFilterOptions.statuses}
              onChange={(value) => submitProductFilters({ status: value, page: "1" }, table)}
            />
          </div>
          <div className="ppProductsSelectFilters" onChange={(event) => handleFilterChange(event, table)}>
            <ProductFilterSelect name="issue" label="Issue type" value={tableFilters.issue || "all"} options={tableFilterOptions.issues} />
            <ProductFilterSearchInput name="vendor" label="Vendor" value={tableFilters.vendor || ""} options={tableFilterOptions.vendors} scope={table} />
            <ProductFilterSearchInput name="collection" label="Collection" value={tableFilters.collection || ""} options={tableFilterOptions.collections} scope={table} />
          </div>
        </div>
        {includeActions && (
          <div className="ppProductsSecondaryActions">
            <button
              className="ppAnalyzeLinkButton ppAnalyzeLinkButton-primary ppProductsToolbarIconButton ppProductsAnalyzeSelectedButton"
              data-pp-products-run-deep-scan-selected={table === "candidates" ? "true" : undefined}
              type="button"
              aria-label={`Analyze selected (${selectedCount})`}
              title="Analyze Selected"
              disabled={selectedCount === 0 || pendingBulkAnalyze}
              onClick={handleAnalyzeSelected}
            >
              <s-icon type="wand" size="small"></s-icon>
            </button>
            <button
              className="ppSecondaryActionButton ppProductsToolbarIconButton ppProductsWatchlistBulkButton"
              type="button"
              aria-label={`Add selected products to Watchlist (${selectedCount})`}
              title={table === "main" && selectedWatchlistEligibleCount > 0
                ? "Add to Watchlist"
                : "Run Product Diagnosis before adding candidates to Watchlist"}
              disabled={selectedCount === 0 || selectedWatchlistEligibleCount === 0 || pendingBulkWatchlistAdd || table !== "main"}
              onClick={handleAddSelectedToWatchlist}
            >
              <ProductPulseGlyph type="binoculars" />
            </button>
            {hasActiveProductTableFilters(tableFilters) && (
              <Link className="ppSecondaryActionButton" to="/app/products">
                <s-icon type="x" size="small"></s-icon>
                Clear filters
              </Link>
            )}
          </div>
        )}
      </div>
    </s-section>
  );

  const renderProductTable = ({
    table = "main",
    title,
    description,
    rows,
    count,
    totalAll,
    currentPage,
    pageSize,
    pages,
    tableSortConfig,
    searchState,
    emptyTitle,
    emptyDescription,
    tableTestId,
    showFindProduct = false,
    isLoading = false,
  }) => {
    const selectionState = getRowsSelectionState(rows);
    const productLabel = getProductTableLabel(table);
    const tableFilters = table === "candidates" ? candidateFilters : table === "resolved" ? resolvedFilters : filters;
    const panel = buildBetaFeedbackPanel(getBetaFeedbackPanelId("products", table), `${title} product table`, {
      productList: {
        table,
        activeTab: activeProductsTab,
        title,
        rowCount: rows.length,
        totalCount: count,
        totalStoredCount: totalAll,
        currentPage,
        pageSize,
        totalPages: pages,
        selectedCount: selectionState.selectedCount,
        filters: summarizeProductTableFilters(tableFilters),
        sort: tableSortConfig,
        visibleRows: rows.slice(0, 8).map(summarizeProductTableRow),
      },
    });

    return (
      <BetaFeedbackPanelFrame panel={panel}>
        <s-section
          className={`ppProductsTableSection ${table === "candidates" ? "ppProductsCandidatesSection" : table === "resolved" ? "ppProductsResolvedSection" : ""}`.trim()}
          data-pp-products-table={table}
          padding="none"
        >
          <div className="ppProductsTableHeading">
            <div>
              <h2>{title}</h2>
              <p>{description}</p>
            </div>
            <BetaFeedbackPanelControls panel={panel} allowHide={false} />
          </div>
          <div className="ppProductsTableStatus">
            {selectionState.selectedCount > 0 && rows.length > 0 && (
              <div className="ppSelectionPill">
                <span>{selectionState.selectedCount}</span>
                selected
                <button type="button" aria-label={`Clear selected ${productLabel}`} onClick={() => setSelectedProducts(new Set())}>
                  <s-icon type="x" size="small"></s-icon>
                </button>
              </div>
            )}
            <span className="ppProductsTableCount">
              {isLoading
                ? `Loading ${productLabel}...`
                : rows.length > 0
                ? `${rows.length} of ${count} ${productLabel}${totalAll !== count ? ` (${totalAll} stored)` : ""}`
                : table === "candidates" ? "No candidates in this view" : "No Product Diagnosis results in this view"}
            </span>
            <div className="ppProductsTableTools">
              {showFindProduct && (
                <button
                  className="ppTableFindProductButton"
                  type="button"
                  onClick={() => setShopifyProductSearchOpen(true)}
                >
                  <svg className="ppShopifyTinyIcon" viewBox="0 0 108.44 122.88" aria-hidden="true" focusable="false">
                    <path fill="#95BF47" fillRule="evenodd" clipRule="evenodd" d="M94.98 23.66c-.09-.62-.63-.96-1.08-1-.45-.04-9.19-.17-9.19-.17s-7.32-7.1-8.04-7.83c-.72-.72-2.13-.5-2.68-.34-.01 0-1.37.43-3.68 1.14-.38-1.25-.95-2.78-1.76-4.32-2.6-4.97-6.42-7.6-11.03-7.61h-.02c-.32 0-.64.03-.96.06-.14-.16-.27-.32-.42-.48C54.11.96 51.54-.08 48.45.01c-5.95.17-11.88 4.47-16.69 12.11-3.38 5.37-5.96 12.12-6.69 17.35-6.83 2.12-11.61 3.6-11.72 3.63-3.45 1.08-3.56 1.19-4.01 4.44C9.03 39.99 0 109.8 0 109.8l75.65 13.08 32.79-8.15S95.06 24.28 94.98 23.66ZM66.52 16.63c-1.74.54-3.72 1.15-5.87 1.82-.04-3.01-.4-7.21-1.81-10.83 4.52.85 6.74 5.96 7.68 9.01ZM56.69 19.68c-3.96 1.23-8.29 2.57-12.63 3.91 1.22-4.67 3.54-9.33 6.38-12.38 1.06-1.14 2.54-2.4 4.29-3.12 1.65 3.43 2 8.3 1.96 11.59ZM48.58 3.97c1.4-.03 2.57.28 3.58.94-1.61.83-3.16 2.03-4.62 3.59-3.78 4.06-6.68 10.35-7.83 16.43-3.6 1.11-7.13 2.21-10.37 3.21 2.04-9.56 10.06-23.91 19.24-24.17Z" />
                    <path fill="#5E8E3E" fillRule="evenodd" clipRule="evenodd" d="M93.9 22.66c-.45-.04-9.19-.17-9.19-.17s-7.32-7.1-8.04-7.83c-.27-.27-.63-.41-1.02-.47v108.68l32.78-8.15s-13.38-90.44-13.46-91.06c-.07-.62-.62-.96-1.07-1Z" />
                    <path fill="#FFFFFF" fillRule="evenodd" clipRule="evenodd" d="m57.48 39.52-3.81 14.25s-4.25-1.93-9.28-1.62c-7.38.47-7.46 5.12-7.39 6.29.4 6.37 17.16 7.76 18.11 22.69.74 11.74-6.23 19.77-16.27 20.41-12.05.76-18.69-6.35-18.69-6.35l2.55-10.86s6.68 5.04 12.02 4.7c3.49-.22 4.74-3.06 4.61-5.07-.52-8.31-14.18-7.82-15.04-21.48-.73-11.49 6.82-23.14 23.48-24.19 6.43-.41 9.71 1.23 9.71 1.23Z" />
                  </svg>
                  Find Shopify product
                </button>
              )}
              {!searchState.open && (
                <button
                  className="ppTableSearchButton"
                  type="button"
                  aria-label={`Search ${productLabel}`}
                  aria-expanded={searchState.open}
                  onClick={() => searchState.setOpen(true)}
                >
                  <s-icon type="search" size="small"></s-icon>
                </button>
              )}
              {searchState.open && (
                <div className="ppTableSearchControl">
                  <s-icon type="search" size="small"></s-icon>
                  <input
                    ref={searchState.inputRef}
                    aria-label={`Search ${productLabel}`}
                    value={searchState.value}
                    onChange={(event) => searchState.setValue(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Escape") searchState.setOpen(false);
                    }}
                    placeholder={`Search ${productLabel}`}
                    type="search"
                  />
                  <button type="button" aria-label={`Close ${productLabel} search`} onClick={() => searchState.setOpen(false)}>
                    <s-icon type="x" size="small"></s-icon>
                  </button>
                </div>
              )}
            </div>
          </div>
          <div className="ppProductsTableWrap">
            <table className="ppProductsTable" data-pp-products-candidates-table={table === "candidates" ? "true" : undefined} data-testid={tableTestId}>
            <thead>
              <tr>
                <th aria-label={`Select ${productLabel}`}>
                  <input
                    type="checkbox"
                    checked={selectionState.allSelected}
                    aria-checked={selectionState.hasSelection && !selectionState.allSelected ? "mixed" : selectionState.allSelected}
                    aria-label={`Select all visible ${productLabel}`}
                    disabled={isLoading}
                    onChange={() => handleToggleRows(rows)}
                  />
                </th>
                <th>Product</th>
                <th>
                  <SortableHeader
                    active={tableSortConfig?.key === "riskScore"}
                    direction={tableSortConfig?.direction}
                    label="Product risk"
                    onSort={() => handleSort("riskScore", table)}
                  />
                </th>
                <th>Trend</th>
                <th>Sales Momentum</th>
                <th>Evidence</th>
                <th>Main suspected issue</th>
                <th>Sources</th>
                <th>
                  <SortableHeader
                    active={tableSortConfig?.key === "lastAnalysis"}
                    direction={tableSortConfig?.direction}
                    label="Last analysis"
                    onSort={() => handleSort("lastAnalysis", table)}
                  />
                </th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {isLoading && (
                <tr className="ppProductsEmptyRow">
                  <td colSpan="10">
                    <div className="ppProductsEmptyState" role="status" aria-live="polite">
                      <span className="ppMiniSpinner" aria-hidden="true" />
                      <div>
                        <h2>Loading products</h2>
                        <p>Fetching the latest product rows for this table page.</p>
                      </div>
                    </div>
                  </td>
                </tr>
              )}
              {!isLoading && rows.length === 0 && (
                <tr className="ppProductsEmptyRow">
                  <td colSpan="10">
                    <div className="ppProductsEmptyState">
                      <ProductsTableEmptyIcon />
                      <div>
                        <h2>{emptyTitle}</h2>
                        <p>{emptyDescription}</p>
                      </div>
                      <FastScanButton
                        pending={fastScanRunning}
                        onStart={handleStartFastScan}
                      />
                    </div>
                  </td>
                </tr>
              )}
              {rows.map((product) => {
                const resolutionOverride = getProductResolutionOverride(product, resolvedProductOverrides);
                const displayProduct = resolutionOverride ? { ...product, ...resolutionOverride } : product;
                const actionKey = getProductActionKey(displayProduct);
                const selected = selectedProducts.has(actionKey);
                const diagnosisState = getProductDiagnosisState(displayProduct, pendingAnalyzeIds);
                const rowClassName = [
                  diagnosisState ? "isDiagnosing" : "",
                  displayProduct.resolvedAt ? "isResolved" : "",
                ].filter(Boolean).join(" ");

                return (
                  <tr
                    className={rowClassName}
                    data-pp-products-candidate-row={table === "candidates" ? actionKey : undefined}
                    key={actionKey}
                  >
                    <td>
                      <input
                        data-pp-products-candidate-select={table === "candidates" ? actionKey : undefined}
                        type="checkbox"
                        checked={selected}
                        aria-label={`Select ${displayProduct.title}`}
                        onChange={() => handleToggleProduct(displayProduct)}
                      />
                    </td>
                    <td>
                      <Link className="ppProductsProductCell" to={displayProduct.href}>
                        <span className="ppProductImageWrap">
                          <ProductArt
                            variant={displayProduct.variant}
                            label={displayProduct.title}
                            imageUrl={displayProduct.imageUrl}
                            imageAlt={displayProduct.imageAlt}
                          />
                          {diagnosisState && (
                            <span className="ppProductDiagnosisLoader" aria-label={`${diagnosisState.label} for ${displayProduct.title}`}>
                              <span aria-hidden="true" />
                            </span>
                          )}
                        </span>
                        <span className="ppProductsProductText">
                          <span>{displayProduct.title}</span>
                          {diagnosisState && <small>{diagnosisState.label}</small>}
                          {displayProduct.resolvedAt && (
                            <small className="ppResolvedProductMarker">
                              <s-icon type="check" size="small"></s-icon>
                              {displayProduct.resolvedLabel || "Resolved"}
                            </small>
                          )}
                        </span>
                      </Link>
                    </td>
                    <td>
                      <div className="ppRiskScoreCell">
                        <ImpactLevelIndicator value={displayProduct.risk} ariaLabel={`${displayProduct.risk} product risk`} />
                        <span className="ppRiskScoreValue">{displayProduct.riskScore}</span>
                      </div>
                    </td>
                    <td><ProductRiskTrendCell product={displayProduct} /></td>
                    <td><ProductMomentumCell product={displayProduct} onWatchlistToggle={handleRequestWatchlistToggle} /></td>
                    <td>
                      <ProductSignalCell product={displayProduct} />
                    </td>
                    <td>{displayProduct.issue}</td>
                    <td><ProductSourceIconGroup product={displayProduct} sources={displayProduct.sources} overflow={displayProduct.sourceOverflow} /></td>
                    <td>{displayProduct.lastAnalysis}</td>
                    <td>
                      <div className="ppTableAction">
                        <button
                          className="ppAnalyzeLinkButton ppAnalyzeLinkButton-primary ppAnalyzeIconOnly"
                          data-pp-products-candidate-run-deep-scan={table === "candidates" ? actionKey : undefined}
                          type="button"
                          aria-label={`Analyze ${displayProduct.title}`}
                          disabled={pendingBulkAnalyze}
                          onClick={() => handleAnalyzeProduct(displayProduct)}
                        >
                          <s-icon type="wand" size="small"></s-icon>
                        </button>
                        <ProductActionMenu
                          product={displayProduct}
                          open={openActionProduct === actionKey}
                          onToggle={() => setOpenActionProduct((current) => (current === actionKey ? null : actionKey))}
                          onClose={() => setOpenActionProduct(null)}
                          onWatchlistToggle={handleRequestWatchlistToggle}
                          onDeleteAnalysis={handleRequestDeleteAnalysis}
                        />
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
            </table>
          </div>
          {!isLoading && rows.length > 0 && (
            <div className="ppProductsPagination">
              <label className="ppRowsSelect">
                Rows per page
                <select value={pageSize} onChange={(event) => submitProductFilters({ rows: event.target.value, page: "1" }, table)}>
                  <option value="5">5</option>
                  <option value="10">10</option>
                </select>
              </label>
              <div className="ppPageControls" aria-label={`${title} pagination`}>
                {currentPage > 1 ? (
                  <Link to={buildProductFilterHref(filters, { rows: pageSize, page: currentPage - 1 }, table)} aria-label="Previous page">
                    <s-icon type="chevron-left" size="small"></s-icon>
                  </Link>
                ) : (
                  <button type="button" aria-label="Previous page" disabled>
                    <s-icon type="chevron-left" size="small"></s-icon>
                  </button>
                )}
                {getVisiblePages(currentPage, pages).map((pageNumber) => (
                  <Link
                    className={pageNumber === currentPage ? "isActive" : ""}
                    to={buildProductFilterHref(filters, { rows: pageSize, page: pageNumber }, table)}
                    key={pageNumber}
                  >
                    {pageNumber}
                  </Link>
                ))}
                {currentPage < pages ? (
                  <Link to={buildProductFilterHref(filters, { rows: pageSize, page: currentPage + 1 }, table)} aria-label="Next page">
                    <s-icon type="chevron-right" size="small"></s-icon>
                  </Link>
                ) : (
                  <button type="button" aria-label="Next page" disabled>
                    <s-icon type="chevron-right" size="small"></s-icon>
                  </button>
                )}
              </div>
            </div>
          )}
        </s-section>
      </BetaFeedbackPanelFrame>
    );
  };

  const productsTableTabs = [
    { id: "full", label: "Product Diagnosis", count: productCount, icon: "chart-line" },
    { id: "candidates", label: "Candidates", count: candidateCount, icon: "star" },
    { id: "resolved", label: "Resolved", count: resolvedCount, icon: "check" },
  ];

  const renderActiveProductsFilters = () => {
    if (activeProductsTab === "candidates") {
      return renderProductFilters({ table: "candidates", tableFilters: candidateFilters, tableFilterOptions: candidateFilterOptions, includeActions: true });
    }
    if (activeProductsTab === "resolved") {
      return renderProductFilters({ table: "resolved", tableFilters: resolvedFilters, tableFilterOptions: resolvedFilterOptions });
    }
    return renderProductFilters({ table: "main", tableFilters: filters, tableFilterOptions: filterOptions, includeActions: true });
  };

  const renderProductsTableTabs = () => (
    <div className="ppProductsTableTabsCard">
      <div className="ppProductsTableTabs" role="tablist" aria-label="Product table views">
        {productsTableTabs.map((tab) => {
          const active = activeProductsTab === tab.id;
          return (
            <button
              className={`ppProductsTableTab ${active ? "isActive" : ""}`.trim()}
              data-pp-products-tab={tab.id}
              type="button"
              role="tab"
              aria-selected={active}
              key={tab.id}
              onClick={() => handleProductsTabChange(tab.id)}
            >
              <span className="ppProductsTableTabIcon" aria-hidden="true"><s-icon type={tab.icon} size="small"></s-icon></span>
              <span>{tab.label}</span>
              <strong>({tab.count})</strong>
            </button>
          );
        })}
      </div>
    </div>
  );

  const renderActiveProductsTable = () => {
    if (activeProductsTab === "candidates") {
      return renderProductTable({ table: "candidates", title: "Candidates", description: "Products captured by Catalog Scan or added manually, without a completed Product Diagnosis yet.", rows: candidateRows, count: candidateCount, totalAll: candidateTotalAllProducts, currentPage: candidatePage, pageSize: candidateRowsPerPage, pages: candidateTotalPages, tableSortConfig: candidateSortConfig, tableTestId: "products-candidates-table", showFindProduct: true, searchState: { open: candidateSearchOpen, value: candidateSearchValue, inputRef: candidateTableSearchInputRef, setOpen: setCandidateSearchOpen, setValue: setCandidateSearchValue }, emptyTitle: "No candidates yet", emptyDescription: "Run Catalog Scan or add a Shopify product as a candidate without starting Product Diagnosis.", isLoading: productTablesLoading });
    }
    if (activeProductsTab === "resolved") {
      return renderProductTable({ table: "resolved", title: "Resolved", description: "Products marked resolved after review or remediation.", rows: resolvedRows, count: resolvedCount, totalAll: resolvedTotalAllProducts, currentPage: resolvedPage, pageSize: resolvedRowsPerPage, pages: resolvedTotalPages, tableSortConfig: resolvedSortConfig, tableTestId: "products-resolved-table", searchState: { open: resolvedSearchOpen, value: resolvedSearchValue, inputRef: resolvedTableSearchInputRef, setOpen: setResolvedSearchOpen, setValue: setResolvedSearchValue }, emptyTitle: "No resolved products yet", emptyDescription: "Resolved products will appear here after you mark a diagnosis as resolved.", isLoading: productTablesLoading });
    }
    return renderProductTable({ table: "main", title: "Product Diagnosis", description: "Products with completed or running Product Diagnosis.", rows: productRows, count: productCount, totalAll: totalAllProducts, currentPage: page, pageSize: rowsPerPage, pages: totalPages, tableSortConfig: sortConfig, tableTestId: "products-table", showFindProduct: true, searchState: { open: searchOpen, value: searchValue, inputRef: productTableSearchInputRef, setOpen: setSearchOpen, setValue: setSearchValue }, emptyTitle: "No Product Diagnosis results yet", emptyDescription: "Run Product Diagnosis from Candidates or find a Shopify product to start Product Diagnosis.", isLoading: productTablesLoading });
  };

  return (
    <FullWidthPage heading="Products">
      <ScreenShell className={`ppDashboard ppProductsScreen ${fastScanRunning ? "isScanning" : ""}`.trim()}>
        <div className="ppProductsContent">
          <div className="ppProductsHeader">
            <p className="ppDashboardSubtitle">
              Browse products, review risk signals and run Product Diagnosis.
            </p>
            <div className="ppProductsHeaderActions">
              <FastScanButton
                pending={fastScanRunning}
                onStart={handleStartFastScan}
              />
            </div>
          </div>
          <ProductPulseToast actionData={actionData} />

          {renderActiveProductsFilters()}
          <div className="ppProductsTabbedTableGroup">
            {renderProductsTableTabs()}
            {renderActiveProductsTable()}
          </div>

        </div>
      </ScreenShell>
      {fastScanRunning && (
        <div className="ppProductsScanOverlay" role="status">
          <div>
            <span className="ppScanSpinner" aria-hidden="true" />
            <h2>Catalog Scan running</h2>
            <p>
              ProductPulse is checking the catalog for potential quality signals. The backend job will keep running.
            </p>
            <small>{activeScanJob ? activeScanJob.source : "Starting scan..."}</small>
          </div>
        </div>
      )}
      {shopifyProductSearchOpen && (
        <ShopifyProductSearchModal
          query={shopifyProductSearchQuery}
          results={shopifyProductSearchResults}
          pending={shopifyProductSearchPending}
          error={shopifyProductSearchError}
          onAnalyze={handleAnalyzeShopifyProduct}
          onAddCandidate={handleAddShopifyProductCandidate}
          onCancel={() => setShopifyProductSearchOpen(false)}
          onQueryChange={setShopifyProductSearchQuery}
          actionLabel="Run Product Diagnosis"
          addedProductIds={addedCandidateProductIds}
          addedActionLabel="Added to Candidates"
          addedStatusKind="candidate"
        />
      )}
      {analysisConfirmation && (
        <ProductAnalysisConfirmModal
          confirmation={analysisConfirmation}
          pending={pendingBulkAnalyze}
          pendingIds={pendingAnalyzeIds}
          onCancel={() => setAnalysisConfirmation(null)}
          onConfirm={handleConfirmAnalysis}
        />
      )}
      {showDiagnosisQueueOverlay && (
        <ProductDiagnosisQueueOverlay
          count={pendingAnalyzeIds.length}
          timedOut={diagnosisQueueOverlayTimedOut}
          onDismiss={() => setDiagnosisQueueOverlayDismissed(true)}
        />
      )}
      {watchlistConfirmation && (
        <WatchlistConfirmModal
          confirmation={watchlistConfirmation}
          pending={pendingWatchlistAction}
          onCancel={() => setWatchlistConfirmation(null)}
        />
      )}
      {deleteAnalysisConfirmation && (
        <DeleteProductAnalysisConfirmModal
          confirmation={deleteAnalysisConfirmation}
          pending={pendingDeleteAnalysis}
          onCancel={() => setDeleteAnalysisConfirmation(null)}
        />
      )}
      {quickScanConfirmation && (
        <QuickScanConfirmModal
          pending={pendingFastScan}
          onCancel={() => setQuickScanConfirmation(false)}
          onConfirm={handleConfirmFastScan}
        />
      )}
      {quickScanCsvWarning && (
        <QuickScanCsvReviewsModal
          onCancel={() => setQuickScanCsvWarning(false)}
          onContinue={handleContinueQuickScanWithoutCsv}
          onUploadCsvFirst={handleUploadCsvBeforeQuickScan}
        />
      )}
    </FullWidthPage>
  );
}

export function WatchlistScreen({ data = {}, actionData }) {
  const revalidator = useRevalidator();
  const navigation = useNavigation();
  const submit = useSubmit();
  const shopifyProductSearchFetcher = useFetcher();
  const [shopifyProductSearchOpen, setShopifyProductSearchOpen] = useState(false);
  const [shopifyProductSearchQuery, setShopifyProductSearchQuery] = useState("");
  const [watchlistActionConfirmation, setWatchlistActionConfirmation] = useState(null);
  const [watchOverviewSort, setWatchOverviewSort] = useState("urgency");
  const shopifyProductSearchSubmitRef = useRef(shopifyProductSearchFetcher.submit);
  const watchlist = data.watchlist || {};
  const rows = useMemo(() => (Array.isArray(watchlist.rows) ? watchlist.rows : []), [watchlist.rows]);
  const activities = Array.isArray(watchlist.activities) ? watchlist.activities : [];
  const runActivities = Array.isArray(watchlist.runActivities) ? watchlist.runActivities : activities;
  const trend = watchlist.trend || {};
  const selectedRunId = String(watchlist.selectedRunId || "");
  const settings = watchlist.settings || {};
  const mock = watchlist.mock || {};
  const maxProducts = Number(watchlist.maxProducts || WATCHLIST_MAX_PRODUCTS_DEFAULT);
  const watchedCount = Number(watchlist.watchedCount ?? rows.length);
  const activeWatchedCount = rows.filter((row) => row.status !== "Paused").length;
  const slotsAvailable = Math.max(0, Number(watchlist.slotsAvailable ?? maxProducts - watchedCount));
  const watchedProductIds = useMemo(() => new Set(rows.map((row) => row.productGid).filter(Boolean)), [rows]);
  const pendingAdd = navigation.state === "submitting" && navigation.formData?.get("_action") === "add-watched-product";
  const pendingWatchlistRowAction = navigation.state === "submitting" && ["pause-watched-product", "resume-watched-product", "remove-watched-product"].includes(String(navigation.formData?.get("_action") || ""));
  const normalizedShopifyProductSearchQuery = shopifyProductSearchQuery.trim();
  const shopifyProductSearchData = shopifyProductSearchFetcher.data || {};
  const shopifyProductSearchHasResponse = Object.prototype.hasOwnProperty.call(shopifyProductSearchData, "query");
  const shopifyProductSearchResponseQuery = String(shopifyProductSearchData.query || "");
  const shopifyProductSearchHasQuery = shopifyProductSearchOpen;
  const shopifyProductSearchHasFreshResponse = shopifyProductSearchHasQuery
    && shopifyProductSearchHasResponse
    && shopifyProductSearchResponseQuery === normalizedShopifyProductSearchQuery;
  const shopifyProductSearchResults = shopifyProductSearchHasFreshResponse
    ? shopifyProductSearchData.products || []
    : [];
  const shopifyProductSearchPending = shopifyProductSearchHasQuery
    && (shopifyProductSearchFetcher.state !== "idle" || !shopifyProductSearchHasFreshResponse);
  const shopifyProductSearchError = shopifyProductSearchHasFreshResponse && shopifyProductSearchData.status === "validation_error"
    ? shopifyProductSearchData.message
    : "";
  const atCapacity = watchedCount >= maxProducts;
  const hasActiveWatchlistDiagnosisJobs = rows.some((row) => getProductDiagnosisState(row));
  const overviewDashboard = useMemo(() => buildWatchlistOverviewDashboard(rows, runActivities, watchOverviewSort, selectedRunId), [rows, runActivities, watchOverviewSort, selectedRunId]);
  const firstReportReadyProduct = useMemo(
    () => rows.find((row) => row?.latestChangeReport && (row.watchlistHref || row.handle || row.productGid)) || null,
    [rows],
  );

  useEffect(() => {
    shopifyProductSearchSubmitRef.current = shopifyProductSearchFetcher.submit;
  }, [shopifyProductSearchFetcher.submit]);

  useEffect(() => {
    if (!hasActiveWatchlistDiagnosisJobs) return undefined;
    const interval = window.setInterval(() => {
      if (!document.hidden) revalidator.revalidate();
    }, PRODUCT_TABLE_ACTIVE_JOB_REFRESH_MS);
    return () => window.clearInterval(interval);
  }, [hasActiveWatchlistDiagnosisJobs, revalidator]);

  useEffect(() => {
    if (!shopifyProductSearchOpen) return undefined;
    const query = shopifyProductSearchQuery.trim();

    const timeout = window.setTimeout(() => {
      const formData = new FormData();
      formData.set("_action", "search-watchlist-eligible-products");
      formData.set("query", query);
      shopifyProductSearchSubmitRef.current(formData, { method: "post" });
    }, 300);

    return () => window.clearTimeout(timeout);
  }, [shopifyProductSearchOpen, shopifyProductSearchQuery]);

  useEffect(() => {
    clearCachedDashboardForActionData(actionData, data?.watchlist?.shop || data?.shop || "");
    announceProductPulseJobs(actionData);
    if (actionData?.status === "success" && actionData?.action?.id === "add-watched-product") {
      setShopifyProductSearchOpen(false);
      setShopifyProductSearchQuery("");
      dispatchProductPulseWatchlistWizardEvent({ type: "product-added" });
    }
    if (actionData?.status === "success" && actionData?.action?.id === "run-watch-scan") {
      dispatchProductPulseWatchlistWizardEvent({
        type: "scan-started",
        jobs: Array.isArray(actionData.jobs) ? actionData.jobs : [],
      });
    }
    if (actionData?.status === "success" && ["pause-watched-product", "resume-watched-product", "remove-watched-product"].includes(String(actionData?.action?.id || ""))) {
      setWatchlistActionConfirmation(null);
    }
  }, [actionData, data?.shop, data?.watchlist?.shop]);

  useEffect(() => {
    if (!firstReportReadyProduct) return;
    dispatchProductPulseWatchlistWizardEvent({
      type: "report-ready",
      productTitle: firstReportReadyProduct.title || "",
      productHref: firstReportReadyProduct.watchlistHref || getWatchlistProductPageHref(firstReportReadyProduct),
    });
  }, [firstReportReadyProduct]);

  const handleOpenWatchlistProductSearch = () => {
    setShopifyProductSearchQuery("");
    setShopifyProductSearchOpen(true);
    dispatchProductPulseWatchlistWizardEvent({ type: "add-product-modal-opened" });
  };

  const handleAddWatchedProduct = (product) => {
    if (pendingAdd || !product?.id || watchedProductIds.has(product.id)) return;
    if (!isProductSearchFullDiagnosis(product)) return;
    const formData = new FormData();
    formData.set("_action", "add-watched-product");
    formData.set("productGid", product.id);
    formData.set("title", product.title || "");
    formData.set("handle", product.handle || "");
    formData.set("sku", product.sku || "");
    formData.set("imageUrl", product.imageUrl || "");
    formData.set("imageAlt", product.imageAlt || product.title || "");
    submit(formData, { method: "post" });
  };

  return (
    <FullWidthPage heading="Watchlist">
      <ScreenShell className="ppDashboard ppWatchlistScreen">
        <div className="ppWatchlistHeader">
          <div>
            <p className="ppDashboardSubtitle">Monitor up to {maxProducts} products with automatic rescans and email alerts.</p>
          </div>
          <div className="ppWatchlistHeaderActions">
            <button
              className="ppPrimaryButton ppWatchlistAddButton"
              type="button"
              disabled={atCapacity || pendingAdd}
              onClick={handleOpenWatchlistProductSearch}
              data-pp-watchlist-add-button="header"
            >
              <ProductPulseGlyph type="binoculars" />
              {pendingAdd ? "Adding..." : "Add watched product"}
            </button>
          </div>
        </div>

        <ProductPulseToast actionData={actionData} />

        <div className="ppWatchlistStats" aria-label="Watchlist overview">
          <WatchlistStatCard icon="binoculars" tone="watch" label="Watched products" value={`${watchedCount} / ${maxProducts}`} detail={`${slotsAvailable} slot${slotsAvailable === 1 ? "" : "s"} available`} iconIndex={1} />
          <WatchlistStatCard icon="calendar" tone="blue" label="Scan cadence" value={mock.scanCadence || "Every 3 days"} detail={mock.scanCadenceDetail || "Automatic rescans"} iconIndex={2} />
          <WatchlistStatCard icon="refresh" tone="green" label="Last watch run" value={mock.lastRun || "6h ago"} detail={mock.lastRunDetail || "All active products scanned"} iconIndex={3} />
          <WatchlistStatCard icon="clock" tone="blue" label="Next watch run" value={mock.nextRun || "In 2d 18h"} detail={mock.nextRunDetail || "May 21, 9:00 AM"} iconIndex={4} />
          <WatchlistStatCard icon="alert-triangle" tone="orange" label="New issues detected" value={mock.newIssues || "2 this week"} detail={mock.newIssuesDetail || "2 vs last week"} trend="up" iconIndex={5} />
          <WatchlistStatCard icon="email" tone="green" label="Alert status" value={mock.alertStatus || "Email alerts on"} detail={mock.alertStatusDetail || "2 recipients"} iconIndex={6} />
        </div>

        <WatchlistOverviewDashboard
          overview={overviewDashboard}
          trend={trend}
          sort={watchOverviewSort}
          onSortChange={setWatchOverviewSort}
        />

        <s-section padding="none">
          <div className="ppWatchlistTableWrap" data-pp-watchlist-table>
            <table className="ppWatchlistTable">
              <thead>
                <tr>
                  <th>Product</th>
                  <th>Status</th>
                  <th>Latest risk score</th>
                  <th>Latest change / new issue</th>
                  <th>Last issue / last update</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {rows.length === 0 && (
                  <tr>
                    <td colSpan="6">
                      <div className="ppWatchlistEmptyState">
                        <DashboardIcon type="binoculars" tone="watch" />
                        <div>
                          <h2>No watched products yet</h2>
                          <p>Add up to {maxProducts} Shopify products to monitor on the watch cadence.</p>
                        </div>
                        <button className="ppPrimaryButton ppWatchlistAddButton" type="button" disabled={pendingAdd} onClick={handleOpenWatchlistProductSearch}>
                          <ProductPulseGlyph type="binoculars" />
                          Add watched product
                        </button>
                      </div>
                    </td>
                  </tr>
                )}
                {rows.map((product) => (
                  <WatchlistProductRow product={product} key={product.productGid || product.id} onRequestAction={setWatchlistActionConfirmation} pending={pendingWatchlistRowAction} />
                ))}
              </tbody>
            </table>
            <div className="ppWatchlistTableFooter">
              {rows.length ? `1-${rows.length} of ${rows.length} products` : `0 of ${maxProducts} products`}
            </div>
          </div>
        </s-section>

        <div className="ppWatchlistBottomGrid">
          <WatchlistActivityPanel activities={activities} />
          <WatchlistSettingsPanel settings={settings} watchedCount={watchedCount} activeWatchedCount={activeWatchedCount} pausedWatchedCount={Math.max(0, watchedCount - activeWatchedCount)} actionData={actionData} />
        </div>
      </ScreenShell>

      {shopifyProductSearchOpen && (
        <ShopifyProductSearchModal
          query={shopifyProductSearchQuery}
          results={shopifyProductSearchResults}
          pending={shopifyProductSearchPending}
          error={shopifyProductSearchError}
          onAnalyze={handleAddWatchedProduct}
          onCancel={() => setShopifyProductSearchOpen(false)}
          onQueryChange={setShopifyProductSearchQuery}
          title="Add watched product"
          eyebrow="Watchlist"
          description={`Only products with a completed Product Diagnosis are shown here. You can watch up to ${maxProducts} products.`}
          eligibilityNotice="Watchlist only accepts products that already have a completed Product Diagnosis. Candidates and Catalog Scan-only products must be diagnosed first."
          minimumQueryLength={0}
          searchLabel="Search diagnosed products"
          emptyPrompt="Loading eligible products with completed Product Diagnosis..."
          noResultsText={normalizedShopifyProductSearchQuery ? "No diagnosed products matched this search." : "No products with completed Product Diagnosis are available yet."}
          pendingText="Loading eligible products..."
          actionLabel="Add to watchlist"
          actionIcon="binoculars"
          addedProductIds={watchedProductIds}
          addedActionLabel="Watching"
        />
      )}
      {watchlistActionConfirmation && (
        <WatchlistRowActionConfirmModal
          confirmation={watchlistActionConfirmation}
          pending={pendingWatchlistRowAction}
          onCancel={() => setWatchlistActionConfirmation(null)}
        />
      )}
    </FullWidthPage>
  );
}

function WatchlistStatCard({ icon, tone, label, value, detail, trend = "", iconIndex = 0 }) {
  const indexedClass = iconIndex ? ` ppWatchlistStatCard-${iconIndex}` : "";
  return (
    <article className={`ppWatchlistStatCard${indexedClass}`}>
      <DashboardIcon type={icon} tone={tone} className={iconIndex ? `ppWatchlistStatIcon ppWatchlistStatIcon-${iconIndex}` : "ppWatchlistStatIcon"} />
      <div>
        <span>{label}</span>
        <strong>{value}</strong>
        <small className={trend ? `ppWatchlistStatTrend ppWatchlistStatTrend-${trend}` : ""}>{detail}</small>
      </div>
    </article>
  );
}

function WatchlistOverviewDashboard({ overview = {}, trend = {}, sort = "urgency", onSortChange }) {
  const hasRuns = Array.isArray(overview.runRows) && overview.runRows.length > 0;
  const hasProducts = Array.isArray(overview.productRows) && overview.productRows.length > 0;
  const hasCategories = Array.isArray(overview.categoryRows) && overview.categoryRows.length > 0;
  const hasEvents = Array.isArray(overview.eventRows) && overview.eventRows.length > 0;
  if (!hasRuns && !hasProducts && !hasCategories && !hasEvents) return null;

  return (
    <section className="ppWatchOverviewDashboard" aria-label="Watchlist run overview">
      {hasRuns ? <WatchRecentRunsTimeline rows={overview.runRows} /> : null}
      <div className="ppWatchOverviewDashboardGrid">
        <div className="ppWatchOverviewMain">
          <WatchlistOverviewProductChanges
            rows={overview.productRows || []}
            windowLabel={overview.windowLabel}
            sort={sort}
            onSortChange={onSortChange}
          />
          <WatchlistTrendPanel trend={trend} />
        </div>
        <div className="ppWatchOverviewSide">
          <WatchlistOverviewWhatChanged rows={overview.categoryRows || []} total={overview.totalChangeCount || 0} />
          <WatchlistOverviewEvents rows={overview.eventRows || []} />
        </div>
      </div>
    </section>
  );
}

function WatchlistOverviewProductChanges({ rows = [], windowLabel = "", sort = "urgency", onSortChange }) {
  const panel = buildBetaFeedbackPanel("watchlist.productChanges", "Watchlist product changes", {
    watchlist: {
      rowCount: rows.length,
      windowLabel,
      sort,
      visibleProducts: rows.slice(0, 6).map((row) => ({
        title: row.title,
        riskLabel: row.riskLabel,
        changeTitle: row.changeTitle,
        recommendationLabel: row.recommendationLabel,
      })),
    },
  });
  return (
    <BetaFeedbackPanelFrame panel={panel}>
      <section className="ppWatchOverviewPanel ppWatchOverviewChangesPanel" aria-label="Watchlist changes since previous run">
        <header className="ppWatchOverviewPanelHeader">
          <h3>Changes since previous run {windowLabel ? <span>{windowLabel}</span> : null}</h3>
          <div className="ppBetaFeedbackHeaderActions">
            <BetaFeedbackPanelControls panel={panel} />
            <label className="ppWatchOverviewSort">
              <span>Sort by</span>
              <select value={sort} onChange={(event) => onSortChange?.(event.target.value)}>
                <option value="urgency">Urgency</option>
                <option value="risk">Risk</option>
                <option value="latest">Latest run</option>
                <option value="product">Product</option>
              </select>
            </label>
          </div>
        </header>
        {rows.length ? (
          <div className="ppWatchOverviewProductList">
            {rows.map((row, index) => <WatchlistOverviewProductChangeRow row={row} rank={index + 1} key={row.id || row.productGid || row.title} />)}
          </div>
        ) : (
          <div className="ppWatchOverviewEmpty">
            <s-icon type="check-circle" size="small"></s-icon>
            <span>No changed products were found in the latest Watchlist run.</span>
          </div>
        )}
        {rows.length ? (
          <footer className="ppWatchOverviewPanelFooter">
            <span>Showing 1-{rows.length} of {rows.length} changed products</span>
          </footer>
        ) : null}
      </section>
    </BetaFeedbackPanelFrame>
  );
}

function WatchlistOverviewProductChangeRow({ row = {}, rank = 1 }) {
  const sourceMetric = getWatchOverviewPrimaryMetric(row);
  const metrics = [
    { id: "risk", label: "Risk", value: row.riskDeltaLabel, tone: row.riskDeltaTone },
    { id: "momentum", label: "Momentum", value: row.momentumDeltaLabel, tone: row.momentumDeltaTone },
    { id: "margin", label: "Margin", value: row.marginDeltaLabel, tone: row.marginDeltaTone },
    sourceMetric,
  ].filter(Boolean);

  return (
    <article className={`ppWatchOverviewProductRow ppWatchOverviewProductRow-${row.tone || "neutral"}`}>
      <span className={`ppWatchOverviewRank ppWatchOverviewRank-${row.tone || "neutral"}`}>{rank}</span>
      <Link className="ppWatchOverviewProductIdentity" to={row.watchlistHref || row.href || "/app/watchlist"}>
        <span className="ppWatchOverviewProductImage">
          <ProductArt
            variant={row.variant || "shirt"}
            label={row.title}
            imageUrl={row.imageUrl}
            imageAlt={row.imageAlt || row.title}
          />
        </span>
        <span className="ppWatchOverviewProductCopy">
          <span className="ppWatchOverviewProductTitleRow">
            <strong>{row.title}</strong>
            <span className="ppWatchOverviewProductButton ppWatchOverviewProductButtonMobile" aria-hidden="true">
              <s-icon type="external" size="small"></s-icon>
            </span>
          </span>
          <small>{row.variantLabel || row.sku || row.handle || "Shopify product"}</small>
          <em className={`ppWatchOverviewRiskPill ppWatchOverviewRiskPill-${row.tone || "neutral"}`}>{row.riskLabel || "Tracked"}</em>
        </span>
      </Link>
      <div className="ppWatchOverviewPrimaryChange">
        <span className={`ppWatchOverviewChangeIcon ppWatchOverviewChangeIcon-${row.tone || "neutral"}`} aria-hidden="true">
          <ProductPulseGlyph type={getWatchOverviewEventIcon(row)} />
        </span>
        <span className="ppWatchOverviewPrimaryChangeText">
          <strong>{row.changeTitle}</strong>
          <span>{row.changeDetail}</span>
        </span>
      </div>
      <div className="ppWatchOverviewMetricPack">
        {metrics.map((metric) => (
          <WatchOverviewTinyMetric label={metric.label} value={metric.value} tone={metric.tone} key={metric.id || metric.label} />
        ))}
      </div>
      <div className="ppWatchOverviewRecommendation">
        <Link className="ppWatchOverviewProductButton" to={row.watchlistHref || row.href || "/app/watchlist"} aria-label={`Open ${row.title || "product"} Watchlist details`}>
          <s-icon type="external" size="small"></s-icon>
        </Link>
      </div>
    </article>
  );
}

function getWatchOverviewPrimaryMetric(row = {}) {
  const sourceDeltas = Array.isArray(row.sourceDeltas) ? row.sourceDeltas : [];
  const changedSource = sourceDeltas.find((item) => Number(item.delta || 0) !== 0)
    || sourceDeltas.find((item) => item.value && item.value !== "-");
  if (changedSource) {
    return {
      id: changedSource.id,
      label: changedSource.label,
      value: changedSource.value,
      tone: changedSource.tone,
    };
  }
  const label = Number(row.sourceChangeCount || 0) > 0 ? "Signals" : "Changes";
  return {
    id: "signals",
    label,
    value: formatInteger(row.sourceChangeCount || row.changeCount || 0),
    tone: row.tone === "high" || row.tone === "medium" ? "bad" : "neutral",
  };
}

function WatchOverviewTinyMetric({ label, value, tone = "neutral" }) {
  return (
    <span className={`ppWatchOverviewTinyMetric ppWatchOverviewTinyMetric-${tone}`}>
      <b>{label}</b>
      <strong>{value}</strong>
    </span>
  );
}

function WatchlistOverviewWhatChanged({ rows = [], total = 0 }) {
  const panel = buildBetaFeedbackPanel("watchlist.whatChanged", "Watchlist change categories", {
    watchlist: {
      total,
      categories: rows.slice(0, 8).map((row) => ({
        label: row.label,
        count: row.count,
        worsened: row.worsened,
        improved: row.improved,
        changed: row.changed,
      })),
    },
  });
  return (
    <BetaFeedbackPanelFrame panel={panel}>
      <section className="ppWatchOverviewPanel ppWatchOverviewWhatChanged" aria-label="What changed in latest Watchlist run">
        <header className="ppWatchOverviewPanelHeader">
          <h3>What changed <span>({formatInteger(total)})</span></h3>
          <BetaFeedbackPanelControls panel={panel} />
        </header>
        <div className="ppWatchOverviewCategoryRows">
          {rows.map((row) => (
            <details className={`ppWatchOverviewCategoryRow ppWatchOverviewCategoryRow-${row.id || "change"}`} key={row.id}>
              <summary>
                <span>
                  <DashboardIcon type={row.icon} tone={row.tone || "blue"} size="small" />
                  <strong>{row.label}</strong>
                </span>
                <b>{formatInteger(row.count)}</b>
                <em className="isBad">{row.worsened ? `${formatInteger(row.worsened)} worsened` : "-"}</em>
                <em className="isGood">{row.improved ? `${formatInteger(row.improved)} improved` : "-"}</em>
                <em className="isNeutral">{row.changed ? `${formatInteger(row.changed)} changed` : "-"}</em>
                <s-icon type="chevron-down" size="small"></s-icon>
              </summary>
              <p>{row.detail}</p>
            </details>
          ))}
        </div>
      </section>
    </BetaFeedbackPanelFrame>
  );
}

function WatchlistOverviewEvents({ rows = [] }) {
  const panel = buildBetaFeedbackPanel("watchlist.events", "Watchlist run events", {
    watchlist: {
      eventCount: rows.length,
      events: rows.slice(0, 8).map((row) => ({
        title: row.title,
        detail: row.detail,
        severityLabel: row.severityLabel,
      })),
    },
  });
  return (
    <BetaFeedbackPanelFrame panel={panel}>
      <section className="ppWatchOverviewPanel ppWatchOverviewEvents" aria-label="Events from this Watchlist run">
        <header className="ppWatchOverviewPanelHeader">
          <h3>Events from this run</h3>
          <BetaFeedbackPanelControls panel={panel} />
        </header>
        {rows.length ? (
          <div className="ppWatchOverviewEventRows">
            {rows.map((row) => (
              <Link className="ppWatchOverviewEventRow" to={row.href || "/app/watchlist/activity"} key={row.id}>
                <DashboardIcon type={row.icon} tone={row.tone || "blue"} size="small" />
                <span>
                  <strong>{row.title}</strong>
                  <small>{row.detail}</small>
                </span>
                <time>{row.timeLabel}</time>
                <em className={`ppWatchOverviewSeverity ppWatchOverviewSeverity-${row.severityTone || "neutral"}`}>{row.severityLabel}</em>
              </Link>
            ))}
          </div>
        ) : (
          <div className="ppWatchOverviewEmpty">
            <s-icon type="check-circle" size="small"></s-icon>
            <span>No events were isolated for the latest Watchlist run.</span>
          </div>
        )}
      </section>
    </BetaFeedbackPanelFrame>
  );
}

function buildWatchlistOverviewDashboard(rows = [], activities = [], sort = "urgency", selectedRunId = "") {
  const runContext = buildWatchOverviewRunContext(rows, activities, selectedRunId);
  const runRows = runContext.runRows;
  const effectiveRunId = runContext.selectedRunId;
  const productRows = getWatchlistOverviewProductRows(rows, sort, { selectedRunId: effectiveRunId, runContext });
  const allChangedRows = getWatchlistOverviewProductRows(rows, "urgency", { limit: 99, selectedRunId: effectiveRunId, runContext });
  const eventRows = getWatchlistOverviewEventRows(allChangedRows, effectiveRunId ? [] : activities);
  return {
    runRows,
    selectedRunId: effectiveRunId,
    productRows,
    categoryRows: getWatchlistOverviewCategoryRows(allChangedRows),
    eventRows,
    totalChangeCount: allChangedRows.reduce((sum, row) => sum + Number(row.changeCount || 0), 0),
    windowLabel: getWatchlistOverviewWindowLabel(allChangedRows),
  };
}

function getWatchlistOverviewProductRows(rows = [], sort = "urgency", { limit = 5, selectedRunId = "", runContext = null } = {}) {
  const mapped = (Array.isArray(rows) ? rows : [])
    .map((product) => buildWatchlistOverviewProductRow(product, { selectedRunId, runContext }))
    .filter(Boolean);
  const sorted = sortWatchlistOverviewRows(mapped, sort);
  return sorted.slice(0, limit);
}

function getWatchOverviewReportForRun(product = {}, selectedRunId = "", runContext = null) {
  const latestReport = product.latestChangeReport || null;
  if (!latestReport) return null;
  const reports = getWatchOverviewRunReports(latestReport);
  const requestedRunId = String(selectedRunId || "");
  if (requestedRunId) {
    const matchedReport = reports.find((report) => getWatchOverviewReportRunMatches(report, requestedRunId, runContext));
    if (matchedReport) return withWatchOverviewReportHistory(matchedReport, latestReport);
    const fallbackReport = getWatchOverviewFallbackReportForRun(latestReport, requestedRunId);
    if (fallbackReport) return fallbackReport;
  }
  return withWatchOverviewReportHistory(latestReport, latestReport);
}

function getWatchOverviewRunReports(report = {}) {
  const reports = Array.isArray(report?.runReports) ? report.runReports.filter(Boolean) : [];
  return reports.length ? reports : [report].filter(Boolean);
}

function getWatchOverviewReportRunMatches(report = {}, selectedRunId = "", runContext = null) {
  const requestedRunId = String(selectedRunId || "");
  if (!requestedRunId) return false;
  if (String(report?.id || "") === requestedRunId) return true;
  const reportGroupId = getWatchOverviewReportGroupId(report, runContext);
  if (reportGroupId && reportGroupId === requestedRunId) return true;
  const timestamp = getWatchOverviewReportTimestamp(report);
  return timestamp ? getWatchOverviewRunKey(timestamp) === requestedRunId : false;
}

function getWatchOverviewReportTimestamp(report = {}) {
  return report?.currentRunAt || report?.createdAt || report?.current?.capturedAt || report?.capturedAt || "";
}

function withWatchOverviewReportHistory(report = {}, latestReport = {}) {
  return {
    ...report,
    history: Array.isArray(latestReport?.history) ? latestReport.history : Array.isArray(report?.history) ? report.history : [],
    runReports: Array.isArray(latestReport?.runReports) ? latestReport.runReports : Array.isArray(report?.runReports) ? report.runReports : [],
  };
}

function getWatchOverviewFallbackReportForRun(latestReport = {}, selectedRunId = "") {
  const historyPoints = getWatchRunHistoryPoints(latestReport);
  const pointIndex = historyPoints.findIndex((point) => {
    if (String(point?.id || "") === String(selectedRunId || "")) return true;
    const timestamp = point?.currentRunAt || point?.capturedAt;
    return timestamp ? getWatchOverviewRunKey(timestamp) === String(selectedRunId || "") : false;
  });
  if (pointIndex < 0) return null;
  const point = historyPoints[pointIndex];
  const previous = pointIndex > 0 ? historyPoints[pointIndex - 1] : null;
  return {
    ...latestReport,
    id: point.id || latestReport.id,
    status: Number(point.changeCount || 0) > 0 ? "changed" : "unchanged",
    changeCount: Number(point.changeCount || 0),
    sourceChangeCount: 0,
    previousRunAt: previous?.currentRunAt || previous?.capturedAt || null,
    currentRunAt: point.currentRunAt || point.capturedAt || null,
    previous,
    current: point,
    headline: latestReport.headline || "Watchlist run selected",
    summary: latestReport.summary || "Stored Watchlist run metrics selected from history.",
    sourceChanges: [],
    sourceInsights: [],
    sections: [],
    changes: [],
    history: historyPoints,
  };
}

function buildWatchlistOverviewProductRow(product = {}, { selectedRunId = "", runContext = null } = {}) {
  const report = getWatchOverviewReportForRun(product, selectedRunId, runContext);
  if (!report || !watchOverviewReportHasChanges(report)) return null;
  const previous = report.previous || {};
  const current = report.current || {};
  const sections = getVisibleWatchReportSections(report.sections || []);
  const biggestChange = getWatchReportBiggestChanges(report, getWatchSourceChangeCards(report), sections)[0]
    || getFallbackWatchOverviewChange(report);
  const riskDelta = watchNumberDeltaValue(current.riskScore, previous.riskScore);
  const momentumDelta = watchNumberDeltaValue(current.productMomentumScore, previous.productMomentumScore);
  const marginDelta = watchNumberDeltaValue(current.marginAtRisk, previous.marginAtRisk);
  const riskTone = getWatchDeltaTone(riskDelta, { lowerIsGood: true });
  const momentumTone = getWatchDeltaTone(momentumDelta, { higherIsGood: true });
  const marginTone = getWatchDeltaTone(marginDelta, { lowerIsGood: true });
  const sourceDeltas = getWatchOverviewSourceDeltas(previous, current);
  const urgencyScore = getWatchOverviewUrgencyScore({ report, current, riskDelta, marginDelta, sourceDeltas });
  const tone = getWatchOverviewProductTone({ urgencyScore, current, riskDelta, sourceDeltas });
  const baseWatchlistHref = getWatchlistProductPageHref(product);
  const watchlistHref = report.id ? `${baseWatchlistHref}?runId=${encodeURIComponent(report.id)}` : baseWatchlistHref;
  return {
    id: product.id || product.productGid || product.title,
    productGid: product.productGid || "",
    title: product.title || report.productTitle || "Watched product",
    handle: product.handle || "",
    sku: product.sku || "",
    imageUrl: product.imageUrl,
    imageAlt: product.imageAlt || product.title,
    href: product.href || baseWatchlistHref,
    watchlistHref,
    riskLabel: current.riskLabel || product.riskLabel || "Tracked",
    variantLabel: product.sku ? `SKU ${product.sku}` : product.handle ? `/${product.handle}` : "",
    changeTitle: biggestChange?.label || report.headline || "Watchlist signal changed",
    changeDetail: biggestChange?.value || biggestChange?.delta || report.summary || "Latest Watchlist run changed stored product signals.",
    changeCount: Number(report.changeCount || 0),
    sourceChangeCount: Number(report.sourceChangeCount || 0),
    signalCount: Number(current.signalCount || 0),
    actionCount: Number(current.actionCount || current.openActionCount || current.recommendedActionCount || 0),
    timestamp: report.currentRunAt || report.createdAt || "",
    urgencyScore,
    tone,
    sourceDeltas,
    riskDeltaLabel: formatWatchOverviewDelta(riskDelta),
    riskDeltaTone: riskTone,
    momentumDeltaLabel: formatWatchOverviewDelta(momentumDelta),
    momentumDeltaTone: momentumTone,
    marginDeltaLabel: formatWatchOverviewDelta(marginDelta, { formatter: formatMoney }),
    marginDeltaTone: marginTone,
    recommendationLabel: getWatchOverviewRecommendationLabel({ tone, report }),
    recommendationDetail: getWatchOverviewRecommendationDetail({ report, biggestChange, tone }),
    report,
  };
}

function getFallbackWatchOverviewChange(report = {}) {
  const source = (report.sourceChanges || [])[0];
  if (source) {
    return {
      label: source.label || "Source signal changed",
      value: [source.value, source.delta].filter(Boolean).join(" · ") || source.detail || "New source change",
    };
  }
  const change = (report.changes || [])[0];
  if (change) {
    return {
      label: change.label || "Calculated metric changed",
      value: `${change.from ?? "-"} → ${change.to ?? "-"}${change.delta ? ` · ${change.delta}` : ""}`,
    };
  }
  return null;
}

function sortWatchlistOverviewRows(rows = [], sort = "urgency") {
  return rows.slice().sort((left, right) => {
    if (sort === "product") return String(left.title || "").localeCompare(String(right.title || ""));
    if (sort === "risk") return Number(right.report?.current?.riskScore || 0) - Number(left.report?.current?.riskScore || 0);
    if (sort === "latest") return new Date(right.timestamp || 0).getTime() - new Date(left.timestamp || 0).getTime();
    return Number(right.urgencyScore || 0) - Number(left.urgencyScore || 0);
  });
}

function buildWatchOverviewRunContext(rows = [], activities = [], selectedRunId = "") {
  const queuedRuns = getWatchOverviewQueuedRunLookup(activities);
  const reportEntries = getWatchOverviewReportEntries(rows);
  const groups = [];
  const groupById = new Map();
  const reportGroupIdByReportId = new Map();

  reportEntries
    .sort((left, right) => left.time - right.time)
    .forEach((entry) => {
      const queuedRun = entry.jobId ? queuedRuns.byJobId.get(entry.jobId) : null;
      const group = queuedRun
        ? getOrCreateWatchOverviewRunGroup(groupById, groups, {
          id: queuedRun.id,
          timestamp: queuedRun.timestamp || entry.timestamp,
          source: "activity",
        })
        : getOrCreateFallbackWatchOverviewRunGroup(groupById, groups, entry);
      addWatchOverviewReportEntryToGroup(group, entry);
      if (entry.reportId) reportGroupIdByReportId.set(entry.reportId, group.id);
    });

  const sortedGroups = groups.sort((left, right) => right.time - left.time);
  const latestKey = sortedGroups[0]?.id || "";
  const requestedKey = String(selectedRunId || "");
  const selectedKey = resolveWatchOverviewSelectedRunId(requestedKey, {
    latestKey,
    groupById,
    reportGroupIdByReportId,
  });

  return {
    selectedRunId: selectedKey,
    runRows: sortedGroups.map((group) => ({
      id: group.id,
      timestamp: group.timestamp,
      label: formatWatchRunHistoryTimestamp(group.timestamp),
      timestampLabel: formatWatchRunHistoryTimestamp(group.timestamp),
      href: `/app/watchlist?runId=${encodeURIComponent(group.id)}`,
      changeCount: group.changeCount,
      signalCount: group.signalCount,
      actionCount: group.actionCount,
      productCount: group.productIds.size,
      isCurrent: group.id === latestKey,
      isSelected: group.id === selectedKey,
    })),
    reportGroupIdByReportId,
  };
}

function getWatchOverviewQueuedRunLookup(activities = []) {
  const byJobId = new Map();
  (Array.isArray(activities) ? activities : []).forEach((activity) => {
    if (!["watch_scan_queued", "watch_manual_scan_queued"].includes(String(activity?.eventType || ""))) return;
    const jobIds = Array.isArray(activity?.metadata?.jobIds) ? activity.metadata.jobIds.map(String).filter(Boolean) : [];
    if (!jobIds.length) return;
    const timestamp = activity.createdAt || activity.timestamp || activity.time || "";
    const run = {
      id: String(activity.id || getWatchOverviewRunKey(timestamp || new Date().toISOString())),
      timestamp,
    };
    jobIds.forEach((jobId) => byJobId.set(jobId, run));
  });
  return { byJobId };
}

function getWatchOverviewReportEntries(rows = []) {
  const entries = [];
  (Array.isArray(rows) ? rows : []).forEach((product) => {
    const latestReport = product.latestChangeReport || null;
    const reports = getWatchOverviewRunReports(latestReport);
    reports.forEach((report) => {
      const timestamp = getWatchOverviewReportTimestamp(report);
      const time = getWatchOverviewTimestampMs(timestamp);
      if (!timestamp || !Number.isFinite(time)) return;
      entries.push({
        productId: String(product?.productGid || product?.id || product?.title || ""),
        reportId: String(report?.id || ""),
        jobId: String(report?.jobId || ""),
        timestamp,
        time,
        changeCount: Number(report?.changeCount || 0),
        signalCount: firstFiniteWatchOverviewNumber(report?.current?.signalCount, report?.signalCount),
        actionCount: firstFiniteWatchOverviewNumber(report?.current?.actionCount, report?.current?.openActionCount, report?.current?.recommendedActionCount, report?.actionCount),
      });
    });
  });
  return entries;
}

function getOrCreateWatchOverviewRunGroup(groupById, groups, { id, timestamp, source = "time" } = {}) {
  const safeTimestamp = timestamp || new Date().toISOString();
  const safeId = String(id || getWatchOverviewRunKey(safeTimestamp));
  if (groupById.has(safeId)) return groupById.get(safeId);
  const group = {
    id: safeId,
    timestamp: safeTimestamp,
    time: getWatchOverviewTimestampMs(safeTimestamp),
    source,
    productIds: new Set(),
    reportIds: new Set(),
    changeCount: 0,
    signalCount: 0,
    actionCount: 0,
  };
  groups.push(group);
  groupById.set(safeId, group);
  return group;
}

function getOrCreateFallbackWatchOverviewRunGroup(groupById, groups, entry = {}) {
  const matched = groups
    .filter((group) => group.source !== "activity")
    .find((group) => Math.abs(Number(group.time || 0) - Number(entry.time || 0)) <= PRODUCT_WATCH_OVERVIEW_RUN_GROUP_WINDOW_MS);
  if (matched) return matched;
  return getOrCreateWatchOverviewRunGroup(groupById, groups, {
    id: getWatchOverviewRunKey(entry.timestamp),
    timestamp: entry.timestamp,
    source: "time",
  });
}

function addWatchOverviewReportEntryToGroup(group, entry = {}) {
  if (!group) return;
  const reportKey = entry.reportId || `${entry.productId}:${entry.timestamp}`;
  if (group.reportIds.has(reportKey)) return;
  group.reportIds.add(reportKey);
  if (entry.productId) group.productIds.add(entry.productId);
  group.changeCount += Number(entry.changeCount || 0);
  group.signalCount += Number(entry.signalCount || 0);
  group.actionCount += Number(entry.actionCount || 0);
}

function resolveWatchOverviewSelectedRunId(requestedKey = "", { latestKey = "", groupById = new Map(), reportGroupIdByReportId = new Map() } = {}) {
  if (!requestedKey) return latestKey;
  if (groupById.has(requestedKey)) return requestedKey;
  if (reportGroupIdByReportId.has(requestedKey)) return reportGroupIdByReportId.get(requestedKey);
  return latestKey;
}

function getWatchOverviewReportGroupId(report = {}, runContext = null) {
  if (!runContext) return "";
  const reportId = String(report?.id || "");
  if (reportId && runContext.reportGroupIdByReportId?.has(reportId)) {
    return runContext.reportGroupIdByReportId.get(reportId);
  }
  return "";
}

function getWatchOverviewTimestampMs(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? NaN : date.getTime();
}

function firstFiniteWatchOverviewNumber(...values) {
  for (const value of values) {
    const number = Number(value);
    if (Number.isFinite(number)) return number;
  }
  return 0;
}

function getWatchOverviewRunKey(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value || "run");
  date.setSeconds(0, 0);
  return date.toISOString();
}

function getWatchlistOverviewWindowLabel(rows = []) {
  const latest = rows
    .map((row) => row.report)
    .filter(Boolean)
    .sort((left, right) => new Date(right.currentRunAt || right.createdAt || 0).getTime() - new Date(left.currentRunAt || left.createdAt || 0).getTime())[0];
  const previous = formatWatchReportTimestamp(latest?.previousRunAt);
  const current = formatWatchReportTimestamp(latest?.currentRunAt || latest?.createdAt);
  return previous && current ? `(${previous} → ${current})` : "";
}

function getWatchlistOverviewCategoryRows(productRows = []) {
  const definitions = [
    { id: "commercial", label: "Commercial activity", icon: "shopify-orders", tone: "blue", matcher: (change) => /order|sold|sales|revenue|momentum|margin/.test(change.key) },
    { id: "friction", label: "Customer friction", icon: "customer-language-analysis", tone: "orange", matcher: (change) => /return|refund|review|negative|rating/.test(change.key) },
    { id: "quality", label: "Product quality risk", icon: "alert-triangle", tone: "red", matcher: (change) => /risk|issue|diagnosis|evidence|signal|confidence/.test(change.key) },
    { id: "catalog", label: "Product / catalog changes", icon: "shopify-product", tone: "purple", matcher: (change) => /content|description|pdp|catalog|product-content|quality score|missing/.test(change.key) },
    { id: "actions", label: "Actions & resolution", icon: "next-best-action", tone: "green", matcher: (change) => /action|resolution|recommend/.test(change.key) },
  ];
  const changes = productRows.flatMap((row) => getWatchOverviewClassifiableChanges(row));
  return definitions.map((definition) => {
    const matched = changes.filter(definition.matcher);
    const fallbackActionCount = definition.id === "actions" ? productRows.filter((row) => row.recommendationLabel).length : 0;
    const count = matched.length || fallbackActionCount;
    return {
      ...definition,
      count,
      worsened: matched.filter((item) => item.tone === "bad").length,
      improved: matched.filter((item) => item.tone === "good").length,
      changed: matched.filter((item) => item.tone === "neutral").length || (definition.id === "actions" ? fallbackActionCount : 0),
      detail: getWatchOverviewCategoryDetail(definition, matched, fallbackActionCount),
    };
  }).filter((row) => row.count > 0);
}

function getWatchOverviewClassifiableChanges(row = {}) {
  const report = row.report || {};
  const sourceChanges = (report.sourceChanges || []).map((change) => ({
    key: `${change.id || ""} ${change.source || ""} ${change.label || ""}`.toLowerCase(),
    tone: getWatchSourceChangeDeltaTone(change),
  }));
  const calculatedChanges = (report.changes || []).map((change) => ({
    key: `${change.id || ""} ${change.label || ""} ${change.sectionTitle || ""}`.toLowerCase(),
    tone: getWatchChangeDeltaTone(change),
  }));
  if (row.actionCount > 0) {
    calculatedChanges.push({ key: "recommended action resolution", tone: "neutral" });
  }
  return [...sourceChanges, ...calculatedChanges];
}

function getWatchOverviewCategoryDetail(definition = {}, matched = [], fallbackActionCount = 0) {
  if (definition.id === "actions" && fallbackActionCount && !matched.length) {
    return `${fallbackActionCount} product${fallbackActionCount === 1 ? "" : "s"} have recommended next steps from this run.`;
  }
  const worsened = matched.filter((item) => item.tone === "bad").length;
  const improved = matched.filter((item) => item.tone === "good").length;
  const neutral = matched.filter((item) => item.tone === "neutral").length;
  return [
    worsened ? `${worsened} worsened` : "",
    improved ? `${improved} improved` : "",
    neutral ? `${neutral} changed` : "",
  ].filter(Boolean).join(" · ") || "Signals changed in the latest Watchlist run.";
}

function getWatchlistOverviewEventRows(productRows = [], activities = []) {
  const productEvents = productRows.slice(0, 5).map((row, index) => ({
    id: `product-event-${row.id || index}`,
    title: `${row.changeTitle} for ${row.title}`,
    detail: row.changeDetail,
    href: row.watchlistHref,
    icon: getWatchOverviewEventIcon(row),
    tone: row.tone === "high" ? "red" : row.tone === "medium" ? "orange" : "green",
    severityTone: row.tone || "low",
    severityLabel: row.tone === "high" ? "High" : row.tone === "medium" ? "Medium" : "Low",
    timeLabel: formatWatchOverviewRelativeTime(row.timestamp),
  }));
  if (productEvents.length) return productEvents.slice(0, 4);
  return (Array.isArray(activities) ? activities : []).slice(0, 4).map((activity) => ({
    id: activity.id || `${activity.title}-${activity.createdAt}`,
    title: activity.title || "Watchlist event",
    detail: activity.detail || "Stored Watchlist activity",
    href: "/app/watchlist/activity",
    icon: activity.icon || "refresh",
    tone: activity.tone || "blue",
    severityTone: activity.tone === "red" || activity.tone === "orange" ? "medium" : "low",
    severityLabel: activity.tone === "red" || activity.tone === "orange" ? "Medium" : "Low",
    timeLabel: activity.time || formatWatchOverviewRelativeTime(activity.createdAt),
  }));
}

function getWatchOverviewEventIcon(row = {}) {
  const text = `${row.changeTitle || ""} ${row.changeDetail || ""}`.toLowerCase();
  if (text.includes("return")) return "shopify-returns";
  if (text.includes("refund")) return "shopify-refunds";
  if (text.includes("review")) return "star";
  if (text.includes("order") || text.includes("revenue")) return "shopify-orders";
  if (text.includes("content") || text.includes("description")) return "shopify-product";
  return "alert-triangle";
}

function getWatchOverviewSourceDeltas(previous = {}, current = {}) {
  return [
    watchOverviewDeltaItem({ id: "orders", label: "Orders", previous, current, field: "orderCount", higherIsGood: true }),
    watchOverviewDeltaItem({ id: "returns", label: "Returns", previous, current, field: "returnUnits", lowerIsGood: true }),
    watchOverviewDeltaItem({ id: "refunds", label: "Refunds", previous, current, field: "refundAmount", formatter: formatMoney, lowerIsGood: true }),
    watchOverviewDeltaItem({ id: "reviews", label: "Reviews", previous, current, field: "negativeReviewCount", lowerIsGood: true }),
  ];
}

function watchOverviewDeltaItem({ id, label, previous = {}, current = {}, field, formatter = null, lowerIsGood = false, higherIsGood = false }) {
  const delta = watchNumberDeltaValue(current?.[field], previous?.[field]);
  const tone = getWatchDeltaTone(delta, { lowerIsGood, higherIsGood });
  const value = Number.isFinite(delta)
    ? formatWatchOverviewDelta(delta, { formatter })
    : "-";
  return { id, label, value, delta, tone };
}

function getWatchOverviewUrgencyScore({ report = {}, current = {}, riskDelta = 0, marginDelta = 0, sourceDeltas = [] } = {}) {
  const badSourceScore = sourceDeltas.filter((item) => item.tone === "bad").reduce((sum, item) => sum + Math.abs(Number(item.delta || 0)), 0);
  return Number(current.riskScore || 0)
    + Math.max(0, Number(riskDelta || 0)) * 3
    + Math.max(0, Number(marginDelta || 0)) / 15
    + badSourceScore * 2
    + Number(report.changeCount || 0);
}

function getWatchOverviewProductTone({ urgencyScore = 0, current = {}, riskDelta = 0, sourceDeltas = [] } = {}) {
  if (Number(current.riskScore || 0) >= 70 || riskDelta >= 8 || urgencyScore >= 90) return "high";
  if (Number(current.riskScore || 0) >= 50 || riskDelta > 0 || sourceDeltas.some((item) => item.tone === "bad")) return "medium";
  return "low";
}

function getWatchOverviewRecommendationLabel({ tone = "low" } = {}) {
  if (tone === "high") return "Recommended action";
  if (tone === "medium") return "Recommended action";
  return "Recommended action";
}

function getWatchOverviewRecommendationDetail({ report = {}, biggestChange = {}, tone = "low" } = {}) {
  if (tone === "low") return "Continue monitoring; no urgent action needed.";
  const issue = report.current?.primaryIssue && report.current.primaryIssue !== "No primary issue"
    ? report.current.primaryIssue
    : biggestChange?.label || "the changed signal";
  if (tone === "high") return `Review evidence and prioritize ${issue}.`;
  return `Check whether ${issue} needs a product or workflow update.`;
}

function watchOverviewReportHasChanges(report = {}) {
  return Number(report.changeCount || 0) > 0
    || Number(report.sourceChangeCount || 0) > 0
    || (Array.isArray(report.sourceChanges) && report.sourceChanges.length > 0)
    || (Array.isArray(report.changes) && report.changes.length > 0);
}

function watchNumberDeltaValue(current, previous) {
  const currentNumber = Number(current);
  const previousNumber = Number(previous);
  if (!Number.isFinite(currentNumber) || !Number.isFinite(previousNumber)) return NaN;
  return currentNumber - previousNumber;
}

function getWatchDeltaTone(delta, { lowerIsGood = false, higherIsGood = false } = {}) {
  if (!Number.isFinite(Number(delta)) || Math.abs(Number(delta)) < 0.0001) return "neutral";
  if (lowerIsGood) return Number(delta) > 0 ? "bad" : "good";
  if (higherIsGood) return Number(delta) > 0 ? "good" : "bad";
  return Number(delta) > 0 ? "good" : "bad";
}

function formatWatchOverviewDelta(delta, { formatter = null } = {}) {
  const number = Number(delta);
  if (!Number.isFinite(number)) return "-";
  const sign = number > 0 ? "+" : number < 0 ? "-" : "";
  const absolute = Math.abs(number);
  const value = formatter ? formatter(absolute) : formatInteger(absolute);
  return `${sign}${value}`;
}

function formatWatchOverviewRelativeTime(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const minutes = Math.max(0, Math.round((Date.now() - date.getTime()) / 60000));
  if (minutes < 60) return `${minutes || 1}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 48) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

function WatchlistProductRow({ product, onRequestAction, pending = false }) {
  const latestTone = product.latestChangeTone || "slate";
  const hasScore = Number.isFinite(Number(product.riskScore));
  const paused = product.status === "Paused";
  const diagnosisState = getProductDiagnosisState(product);
  const watchlistProductHref = getWatchlistProductPageHref(product);
  const issueDisplay = getWatchlistIssueCellDisplay(product);
  const hasWatchlistReport = Boolean(product.latestChangeReport);

  return (
    <tr
      className={diagnosisState ? "isDiagnosing" : ""}
      data-pp-watchlist-product-row={product.productGid || product.id || product.handle || product.title || "product"}
      data-pp-watchlist-ready-row={hasWatchlistReport ? "true" : undefined}
    >
      <td>
        <Link className="ppWatchlistProductCell" to={product.href || "/app/products"}>
          <span className="ppWatchlistProductImageWrap">
            <ProductArt
              variant={product.variant || "shirt"}
              label={product.title}
              imageUrl={product.imageUrl}
              imageAlt={product.imageAlt}
            />
            {diagnosisState && (
              <span className="ppProductDiagnosisLoader" aria-label={`${diagnosisState.label} for ${product.title}`}>
                <span aria-hidden="true" />
              </span>
            )}
          </span>
          <span>
            <strong>{product.title}</strong>
            {diagnosisState && <small className="ppWatchlistDiagnosisLabel">{diagnosisState.label}</small>}
            <small>{product.sku ? `SKU: ${product.sku}` : product.handle ? `/${product.handle}` : "Shopify product"}</small>
          </span>
        </Link>
      </td>
      <td>
        <span className={`ppWatchStatus ppWatchStatus-${product.statusTone || "success"}`}>
          <span aria-hidden="true" />
          {product.status || "Watching"}
        </span>
      </td>
      <td>
        <div className="ppWatchRiskCell">
          <span className={`ppWatchRiskDial ppWatchRiskDial-${product.riskTone || "subdued"}`}>{hasScore ? product.riskScore : "-"}</span>
          <strong className={`ppWatchRiskLabel ppWatchRiskLabel-${product.riskTone || "subdued"}`}>{product.riskLabel || "Pending"}</strong>
        </div>
      </td>
      <td>
        <div className="ppWatchIssueCell">
          <span className={`ppWatchIssueDot ppWatchIssueDot-${latestTone}`} aria-hidden="true" />
          <span>
            <strong>{issueDisplay.title}</strong>
            {issueDisplay.detail ? <small>{issueDisplay.detail}</small> : null}
          </span>
        </div>
      </td>
      <td>
        <div className="ppWatchUpdateCell">
          <strong>{product.lastIssue || "Not scanned yet"}</strong>
          <small>{product.lastIssueDetail || "Waiting for automatic watch cadence"}</small>
        </div>
      </td>
      <td>
        <div className="ppWatchRowActions" aria-label={`Watchlist actions for ${product.title}`}>
          <Link
            className="ppWatchActionsButton ppWatchActionsButton-report"
            to={watchlistProductHref}
            aria-label={`View Watchlist report for ${product.title}`}
            data-pp-watchlist-view-report={hasWatchlistReport ? "true" : undefined}
            onClick={() => dispatchProductPulseWatchlistWizardEvent({
              type: "report-opened",
              productTitle: product.title || "",
              href: watchlistProductHref,
            })}
          >
            <s-icon type="chart-line" size="small"></s-icon>
            <span>View report</span>
          </Link>
          <button
            className={`ppWatchActionsButton ppWatchActionsButton-toggle ${paused ? "ppWatchActionsButton-resume" : "ppWatchActionsButton-pause"}`}
            type="button"
            aria-label={`${paused ? "Resume" : "Pause"} ${product.title}`}
            disabled={pending || !product.productGid}
            onClick={() => onRequestAction?.({ kind: paused ? "resume" : "pause", product })}
          >
            {paused ? (
              <s-icon type="play" size="small"></s-icon>
            ) : (
              <span className="ppPauseGlyph" aria-hidden="true"><span /><span /></span>
            )}
          </button>
          <button
            className="ppWatchActionsButton ppWatchActionsButton-danger"
            type="button"
            aria-label={`Remove ${product.title} from watchlist`}
            disabled={pending || !product.productGid}
            onClick={() => onRequestAction?.({ kind: "remove", product })}
          >
            <s-icon type="x" size="small"></s-icon>
          </button>
        </div>
      </td>
    </tr>
  );
}

function getWatchlistIssueCellDisplay(product = {}) {
  const title = String(product.latestChange || "").trim();
  const detail = String(product.latestChangeDetail || "").trim();
  const normalizedTitle = title.toLowerCase();
  const normalizedDetail = detail.toLowerCase();
  const fallbackDetail = getWatchlistIssueFallbackDetail(product);
  if (normalizedTitle === "watch signal captured" || normalizedTitle === "watchlist signal captured") {
    return {
      title: detail && !normalizedDetail.includes("next watch run") ? detail : "New issue",
      detail: fallbackDetail,
    };
  }
  if (normalizedDetail.includes("next watch run") || normalizedDetail === "waiting for automatic watch cadence") {
    return {
      title: title || "Awaiting first scan",
      detail: fallbackDetail,
    };
  }
  return {
    title: title || "Awaiting first scan",
    detail: detail || fallbackDetail,
  };
}

function getWatchlistIssueFallbackDetail(product = {}) {
  const status = String(product.status || "").trim();
  if (status === "Paused") return "Paused · automatic scans disabled";
  if (product.riskScore != null && product.riskLabel) return `Risk ${product.riskScore} · ${product.riskLabel}`;
  if (product.addedAt) return `Added ${product.addedAt}${status ? ` · ${status}` : ""}`;
  if (product.sku) return `SKU ${product.sku}${status ? ` · ${status}` : ""}`;
  if (product.handle) return `/${product.handle}${status ? ` · ${status}` : ""}`;
  if (status) return `Status: ${status}`;
  return "";
}

export function WatchlistProductScreen({ product }) {
  if (!product) {
    return (
      <FullWidthPage heading="Watchlist product not found">
        <ScreenShell className="ppDashboard ppWatchlistProductPage">
          <Link className="ppProductBackButton ppProductBackButtonStandalone" to="/app/watchlist"><s-icon type="arrow-left" size="small"></s-icon> Back to Watchlist</Link>
          <p className="ppDashboardSubtitle">This product is not currently tracked on the Watchlist.</p>
        </ScreenShell>
      </FullWidthPage>
    );
  }

  const report = product.latestChangeReport || getWatchlistFallbackReport(product);
  const effectiveStatus = report.status === "baseline"
    ? "baseline"
    : Number(report.changeCount || 0) > 0
      ? report.status || "changed"
      : "unchanged";
  const statusTone = getWatchReportStatusTone(effectiveStatus);
  const statusLabel = getWatchReportStatusLabel(effectiveStatus);
  const changeCount = Number(report.changeCount || 0);
  const changeCountLabel = effectiveStatus === "baseline"
    ? "Baseline captured"
    : changeCount > 0
      ? `${formatInteger(changeCount)} ${changeCount === 1 ? "change" : "changes"} tracked`
      : "No product changes";
  const currentRunLabel = formatWatchReportTimestamp(report.currentRunAt || report.current?.capturedAt || report.createdAt);
  const watchlistMetaItems = [
    ["Status", product.status || "Watching"],
    ["Latest run", currentRunLabel || "Latest scan"],
    ["Changes", changeCountLabel],
  ];
  const productDetailHref = getProductDetailHref(product);

  return (
    <FullWidthPage heading="Product Watchlist">
      <ScreenShell className="ppDashboard ppWatchlistProductPage">
        <Link className="ppProductBackButton ppProductBackButtonStandalone" to="/app/watchlist"><s-icon type="arrow-left" size="small"></s-icon> Back to Watchlist</Link>

        <section
          className="ppProductDetailHeroPanel ppWatchlistProductHeroPanel"
          aria-labelledby="watchlist-product-title"
          data-pp-watchlist-product-hero
        >
          <span className="ppProductHeroImageWrap ppWatchlistProductHeroImageWrap">
            <ProductArt
              variant={product.variant || "shirt"}
              label={product.title}
              size="hero"
              imageUrl={product.imageUrl}
              imageAlt={product.imageAlt}
            />
          </span>
          <div className="ppProductDetailHeroCopy">
            <span className="ppWatchChangeReportEyebrow">Watchlist</span>
            <div className="ppProductTitleHeading">
              <h1 id="watchlist-product-title">{product.title || "Watched product"}</h1>
            </div>
            <div className="ppProductDetailStatusRow">
              <span className="ppProductStatusPill ppProductStatusPill-analysis">Watchlist run</span>
              <span className={`ppProductStatusPill ${effectiveStatus === "unchanged" ? "ppProductStatusPill-success" : effectiveStatus === "baseline" ? "ppProductStatusPill-info" : "ppProductStatusPill-warning"}`}>
                {changeCountLabel}
              </span>
            </div>
            <dl className="ppProductMetaLine">
              {watchlistMetaItems.map(([label, value]) => (
                <div key={label}>
                  <dt>{label}:</dt>
                  <dd>{value}</dd>
                </div>
              ))}
            </dl>
          </div>
          <div className="ppProductHeaderActions ppWatchlistProductHeroActions">
            <strong className={`ppWatchChangeReportHeaderStatus ppWatchChangeReportHeaderStatus-${statusTone}`}>
              <span aria-hidden="true" />
              {statusLabel}
            </strong>
            <Link className="ppSecondaryButton ppWatchlistProductDetailButton" to={productDetailHref}>
              <s-icon type="external" size="small"></s-icon>
              Open product detail
            </Link>
          </div>
        </section>

        <WatchChangeReportContent product={product} report={report} />
      </ScreenShell>
    </FullWidthPage>
  );
}

function WatchChangeReportContent({ product, report }) {
  report = report || getWatchlistFallbackReport(product);
  const isBaselineReport = report?.status === "baseline";
  const sections = isBaselineReport ? [] : (Array.isArray(report?.sections) ? report.sections : []);
  const visibleSections = isBaselineReport ? [] : getVisibleWatchReportSections(sections);
  const sourceChanges = isBaselineReport ? [] : getWatchSourceChangeCards(report);
  const biggestChanges = isBaselineReport ? [] : getWatchReportBiggestChanges(report, sourceChanges, visibleSections);
  const customerLanguageCards = isBaselineReport ? [] : getWatchCustomerLanguageChangeCards(report);
  const showCustomerLanguagePanel = !isBaselineReport && customerLanguageCards.length > 0;
  const snapshotRows = isBaselineReport ? [] : getWatchSnapshotComparisonRows(report);
  const categoryCards = isBaselineReport ? [] : getWatchCategoryChangeCards(report, sourceChanges);
  const trendCharts = isBaselineReport ? [] : getWatchRunTrendCharts(report);
  const recentRunRows = getWatchRecentRunRows(report, product);
  const hasVisibleChanges = sourceChanges.length > 0 || visibleSections.length > 0 || categoryCards.length > 0 || trendCharts.length > 0 || recentRunRows.length > 0;
  const effectiveStatus = isBaselineReport ? "baseline" : (!hasVisibleChanges ? "unchanged" : report?.status);
  const statusTone = getWatchReportStatusTone(effectiveStatus);
  const hasReportContent = biggestChanges.length > 0 || showCustomerLanguagePanel || categoryCards.length > 0 || snapshotRows.length > 0 || trendCharts.length > 0 || recentRunRows.length > 0;

  if (!hasReportContent) {
    return <WatchlistProductEmptyState product={product} report={report} />;
  }

  return (
    <>
      <WatchlistInsightReport report={report} statusTone={statusTone} biggestChanges={biggestChanges} />
      {recentRunRows.length ? <WatchRecentRunsTimeline rows={recentRunRows} /> : null}
      {showCustomerLanguagePanel ? <WatchCustomerLanguageChangePanel cards={customerLanguageCards} report={report} /> : null}
      {categoryCards.length ? <WatchCategoryChangeCards cards={categoryCards} report={report} /> : null}
      {snapshotRows.length ? <WatchSnapshotComparisonTable report={report} rows={snapshotRows} /> : null}
      {trendCharts.length ? <WatchRunTrendCharts charts={trendCharts} /> : null}
    </>
  );
}

function WatchlistProductEmptyState({ product }) {
  return (
    <section className="ppWatchlistProductEmpty" aria-label="Empty Watchlist report">
      <span className="ppWatchlistProductEmptyIcon" aria-hidden="true">
        <s-icon type="chart-line" size="large"></s-icon>
      </span>
      <div>
        <strong>Empty</strong>
        <h3>No Watchlist report data yet</h3>
        <p>
          Run a Watchlist scan or wait for the next scheduled scan to compare orders, returns, refunds, reviews,
          risk, Sales Momentum and evidence for {product?.title || "this product"}.
        </p>
      </div>
    </section>
  );
}

function WatchCategoryChangeCards({ cards = [], report = {} }) {
  const updatedLabel = formatWatchReportTimestamp(report?.currentRunAt || report?.current?.capturedAt || report?.createdAt);
  return (
    <section className="ppWatchCategoryChanges" aria-label="Watchlist changes by category">
      <div className="ppWatchCategoryChangesHeader">
        <DashboardIcon type="chart-line" tone="purple" size="small" />
        <h3>Changes by category</h3>
        <span>Compared to previous run</span>
      </div>
      <div className="ppWatchCategoryChangesList">
        {cards.map((card) => <WatchCategoryChangeCard card={card} key={card.id} updatedLabel={updatedLabel} />)}
      </div>
    </section>
  );
}

function WatchCategoryChangeCard({ card, updatedLabel = "" }) {
  const badgeIcon = card.badgeIcon || (card.badgeDirection === "down" ? "arrow-down" : card.badgeDirection === "up" ? "arrow-up" : "info");
  const focus = getWatchCategoryCardFocus(card);
  const secondaryBadge = getWatchCategorySecondaryBadge(card, focus);
  return (
    <article className={`ppWatchCategoryCard ppWatchCategoryCard-${card.tone || "blue"}`}>
      <div className="ppWatchCategoryCardSummary">
        <DashboardIcon type={card.icon || "info"} tone={card.iconTone || card.tone || "blue"} size="small" />
        <span>
          <h4>{card.title}</h4>
          <p>{getWatchCategoryCardSubtitle(card, focus)}</p>
        </span>
      </div>
      <div className="ppWatchCategoryCardFocus">
        <span>{focus.label}</span>
        <strong>{focus.value}</strong>
        <p>{focus.detail}</p>
      </div>
      <div className="ppWatchCategoryCardBadges">
        <span className={`ppWatchCategoryBadge ppWatchCategoryBadge-${card.badgeTone || "neutral"}`}>
          <s-icon type={badgeIcon} size="small"></s-icon>
          {card.badgeLabel || "Updated"}
        </span>
        {secondaryBadge ? (
          <span className={`ppWatchCategoryBadge ppWatchCategoryBadge-${secondaryBadge.tone || "neutral"}`}>
            <s-icon type={secondaryBadge.icon} size="small"></s-icon>
            {secondaryBadge.label}
          </span>
        ) : null}
      </div>
      <div className="ppWatchCategoryCardUpdated">
        <span>Last updated</span>
        <strong>{updatedLabel || "Latest run"}</strong>
      </div>
    </article>
  );
}

function getWatchCategoryCardFocus(card = {}) {
  const rows = Array.isArray(card.rows) ? card.rows.filter(Boolean) : [];
  const changedRows = rows.filter((row) => row.hasChanged);
  const preferredRow = rows.find((row) => /diagnosis|issue|reason|theme|sentiment|negative|content|missing/i.test(`${row.id || ""} ${row.label || ""}`))
    || changedRows[0]
    || rows[0]
    || {};
  return {
    id: preferredRow.id || "",
    label: preferredRow.label || "Latest change",
    value: preferredRow.value || card.title || "Updated",
    detail: getWatchCategoryFocusDetail(preferredRow, rows),
    direction: preferredRow.direction || "neutral",
    tone: preferredRow.tone || "neutral",
    deltaLabel: preferredRow.deltaLabel || "",
  };
}

function getWatchCategoryCardSubtitle(card = {}, focus = {}) {
  const rows = Array.isArray(card.rows) ? card.rows.filter(Boolean) : [];
  const changedCount = rows.filter((row) => row.hasChanged).length;
  if (focus.id === "top-diagnosis" || /diagnosis/i.test(card.title || "")) return "Primary category updated";
  if (focus.id === "product-content") return "Product content updated";
  if (changedCount > 1) return `${changedCount} signals updated`;
  if (focus.label) return `${focus.label} updated`;
  return "Category updated";
}

function getWatchCategoryFocusDetail(row = {}, rows = []) {
  if (row.id === "top-diagnosis") return "Evidence interpretation changed";
  if (row.id === "product-content") return "Product content changed";
  if (!row.deltaLabel) return "Context carried from the latest run";
  const label = String(row.label || "Metric").toLowerCase();
  if (row.deltaLabel === "Changed") return `${row.label || "Value"} changed`;
  if (row.direction === "up") return `${label} increased by ${row.deltaLabel}`;
  if (row.direction === "down") return `${label} decreased by ${row.deltaLabel}`;
  const related = rows.find((candidate) => candidate !== row && candidate?.hasChanged);
  if (related?.label) return `${related.label} also changed`;
  return `${row.label || "Value"} updated`;
}

function getWatchCategorySecondaryBadge(card = {}, focus = {}) {
  const rows = Array.isArray(card.rows) ? card.rows.filter(Boolean) : [];
  const changedRows = rows.filter((row) => row.hasChanged);
  const row = changedRows.find((candidate) => candidate.id !== focus.id) || changedRows[0] || null;
  if (!row?.deltaLabel) return null;
  return {
    label: row.deltaLabel === "Changed" ? "Changed" : row.deltaLabel,
    tone: row.tone === "good" ? "good" : row.tone === "bad" ? "bad" : "blue",
    icon: row.direction === "down" ? "arrow-down" : row.direction === "up" ? "arrow-up" : "info",
  };
}

function WatchRecentRunsTimeline({ rows = [] }) {
  const orderedRows = useMemo(() => rows.slice().reverse(), [rows]);
  const rowsSignature = useMemo(() => getWatchRecentRunsSignature(orderedRows), [orderedRows]);
  const listRef = useRef(null);
  const maxVisibleRuns = 5;
  const [windowSize, setWindowSize] = useState(Math.min(maxVisibleRuns, Math.max(1, orderedRows.length || 1)));
  const maxStart = Math.max(0, orderedRows.length - windowSize);
  const selectedIndex = orderedRows.findIndex((row) => row?.isSelected);
  const defaultStart = selectedIndex >= 0
    ? Math.min(maxStart, Math.max(0, selectedIndex - windowSize + 1))
    : maxStart;
  const [windowStart, setWindowStart] = useState(() => readWatchRecentRunsWindowStart(rowsSignature, defaultStart, maxStart));
  const clampedWindowStart = Math.round(clampNumber(windowStart, 0, maxStart));

  useLayoutEffect(() => {
    const node = listRef.current;
    if (!node || typeof window === "undefined") return undefined;

    const measureVisibleRuns = () => {
      const width = node.getBoundingClientRect().width;
      if (!Number.isFinite(width) || width <= 0) return;
      const style = window.getComputedStyle(node);
      const gap = Number.parseFloat(style.columnGap || style.gap || "20") || 20;
      const minCardWidth = Number.parseFloat(style.getPropertyValue("--pp-watch-run-min-card-width")) || 200;
      const nextWindowSize = Math.max(1, Math.min(maxVisibleRuns, orderedRows.length || 1, Math.floor((width + gap) / (minCardWidth + gap))));
      setWindowSize((current) => (current === nextWindowSize ? current : nextWindowSize));
    };

    measureVisibleRuns();

    let observer = null;
    if (typeof ResizeObserver !== "undefined") {
      observer = new ResizeObserver(measureVisibleRuns);
      observer.observe(node);
    }
    window.addEventListener("resize", measureVisibleRuns);
    return () => {
      observer?.disconnect();
      window.removeEventListener("resize", measureVisibleRuns);
    };
  }, [orderedRows.length]);

  useEffect(() => {
    setWindowStart(readWatchRecentRunsWindowStart(rowsSignature, defaultStart, maxStart));
  }, [defaultStart, maxStart, rowsSignature]);

  useEffect(() => {
    if (windowStart !== clampedWindowStart) {
      setWindowStart(clampedWindowStart);
      return;
    }
    saveWatchRecentRunsWindowStart(rowsSignature, clampedWindowStart);
  }, [clampedWindowStart, rowsSignature, windowStart]);

  const visibleRows = orderedRows.slice(clampedWindowStart, clampedWindowStart + windowSize);
  const canGoOlder = clampedWindowStart > 0;
  const canGoNewer = clampedWindowStart < maxStart;

  return (
    <section className="ppWatchRecentRuns" aria-label="Recent Watchlist runs" data-pp-watchlist-recent-runs>
      <h3>Recent runs</h3>
      <div className="ppWatchRecentRunsTrack">
        <button
          className="ppWatchRecentRunsArrow"
          type="button"
          disabled={!canGoOlder}
          aria-label="Show older Watchlist runs"
          onClick={() => setWindowStart((current) => Math.max(0, current - 1))}
        >
          <s-icon type="chevron-left" size="small"></s-icon>
        </button>
        <ol
          className="ppWatchRecentRunsList"
          ref={listRef}
          style={{ "--pp-watch-run-count": String(Math.max(1, visibleRows.length)) }}
        >
          {visibleRows.map((row) => (
            <li className="ppWatchRecentRunsItem" key={row.id || row.label}>
              <WatchRecentRunCard row={row} />
            </li>
          ))}
        </ol>
        <button
          className="ppWatchRecentRunsArrow"
          type="button"
          disabled={!canGoNewer}
          aria-label="Show newer Watchlist runs"
          onClick={() => setWindowStart((current) => Math.min(maxStart, current + 1))}
        >
          <s-icon type="chevron-right" size="small"></s-icon>
        </button>
      </div>
    </section>
  );
}

function getWatchRecentRunsSignature(rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => String(row?.id || row?.href || row?.label || "run"))
    .join("|");
}

function readWatchRecentRunsWindowStart(signature = "", fallback = 0, maxStart = 0) {
  const fallbackStart = Math.round(clampNumber(Number(fallback) || 0, 0, Math.max(0, maxStart)));
  if (typeof window === "undefined" || !window.localStorage || !signature) return fallbackStart;
  try {
    const stored = JSON.parse(window.localStorage.getItem(PRODUCT_WATCH_RECENT_RUNS_WINDOW_STORAGE_KEY) || "{}");
    if (!stored || stored.signature !== signature) return fallbackStart;
    return Math.round(clampNumber(Number(stored.windowStart) || 0, 0, Math.max(0, maxStart)));
  } catch {
    return fallbackStart;
  }
}

function saveWatchRecentRunsWindowStart(signature = "", windowStart = 0) {
  if (typeof window === "undefined" || !window.localStorage || !signature) return;
  try {
    window.localStorage.setItem(PRODUCT_WATCH_RECENT_RUNS_WINDOW_STORAGE_KEY, JSON.stringify({
      signature,
      windowStart: Math.max(0, Math.round(Number(windowStart) || 0)),
    }));
  } catch {
    // Local storage can be unavailable in private or embedded contexts.
  }
}

function WatchRecentRunCard({ row = {} }) {
  const className = [
    "ppWatchRecentRunCard",
    row.isSelected ? "isSelected" : "",
    row.isCurrent ? "isLatest" : "",
  ].filter(Boolean).join(" ");
  const content = (
    <>
      <span className="ppWatchRecentRunDate">
        {row.timestampLabel || row.label}
        {row.isCurrent ? <em>Latest</em> : null}
      </span>
      <span className="ppWatchRecentRunMetrics">
        <strong>{formatCompactRunCount(row.changeCount, "changed")}</strong>
        <strong>{formatCompactRunCount(row.signalCount, "signal")}</strong>
        <strong>{formatCompactRunCount(row.actionCount, "action")}</strong>
      </span>
    </>
  );
  return row.href ? (
    <Link className={className} to={row.href} aria-label={`View Watchlist run ${row.timestampLabel || row.label}`}>
      {content}
    </Link>
  ) : (
    <span className={`${className} isDisabled`}>
      {content}
    </span>
  );
}

function formatCompactRunCount(value, label) {
  const number = Number(value || 0);
  const safeNumber = Number.isFinite(number) ? number : 0;
  return `${formatInteger(safeNumber)} ${label}${safeNumber === 1 || label === "changed" ? "" : "s"}`;
}

function WatchRunTrendCharts({ charts = [] }) {
  return (
    <section className="ppWatchRunTrends" aria-label="Watchlist run trends">
      {charts.map((chart) => <WatchRunTrendChart chart={chart} key={chart.id} />)}
    </section>
  );
}

function WatchRunTrendChart({ chart }) {
  const width = 760;
  const height = 272;
  const plot = { left: 54, right: 676, top: 28, bottom: 204 };
  const plotWidth = plot.right - plot.left;
  const plotHeight = plot.bottom - plot.top;
  const pointCount = chart.points.length;
  const lastX = getWatchTrendX(pointCount - 1, pointCount, plot);
  const bandWidth = Math.min(96, Math.max(54, plotWidth / Math.max(pointCount - 1, 1) * 0.78));
  const endpointLabels = getWatchTrendEndpointLabels(chart, plot);

  return (
    <article className="ppWatchRunTrendCard">
      <header>
        <h3>{chart.title}</h3>
        <p>{chart.subtitle}</p>
      </header>
      <div className="ppWatchRunTrendLegend">
        {chart.series.map((series) => (
          <span key={series.id}>
            <i style={{ backgroundColor: series.color }} />
            {series.label}
          </span>
        ))}
      </div>
      <svg className="ppWatchRunTrendSvg" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${chart.title}. ${chart.subtitle}.`}>
        <rect className="ppWatchTrendCurrentBand" x={lastX - bandWidth / 2} y={plot.top} width={bandWidth} height={plotHeight + 52} rx="3" />
        {chart.ticks.map((tick) => {
          const y = getWatchTrendY(tick.value, chart.axisMax, plot);
          return (
            <g key={tick.value}>
              <line className="ppWatchTrendGridLine" x1={plot.left} x2={plot.right} y1={y} y2={y} />
              <text className="ppWatchTrendAxisLabel" x={plot.left - 14} y={y + 4} textAnchor="end">{tick.label}</text>
            </g>
          );
        })}
        {chart.points.map((point, index) => {
          const x = getWatchTrendX(index, pointCount, plot);
          return (
            <g className="ppWatchTrendXTick" key={point.id || `${point.currentRunAt}-${index}`}>
              <text x={x} y={plot.bottom + 28} textAnchor="middle">{point.dateLabel}</text>
              <text x={x} y={plot.bottom + 50} textAnchor="middle">{point.timeLabel}</text>
            </g>
          );
        })}
        {chart.series.map((series) => {
          const coordinates = getWatchTrendSeriesCoordinates(series, chart.points, chart.axisMax, plot);
          if (!coordinates.length) return null;
          return (
            <g key={series.id}>
              <polyline
                className="ppWatchTrendLine"
                fill="none"
                points={coordinates.map((point) => `${point.x},${point.y}`).join(" ")}
                stroke={series.color}
              />
              {coordinates.map((point) => (
                <circle className="ppWatchTrendDot" cx={point.x} cy={point.y} fill={series.color} key={`${series.id}-${point.index}`} r="4.2" />
              ))}
            </g>
          );
        })}
        {endpointLabels.map((label) => (
          <g className="ppWatchTrendEndpoint" key={label.id} transform={`translate(${plot.right + 16} ${label.y - 13})`}>
            <rect width={label.width} height="26" rx="8" fill={label.color} />
            <text x={label.width / 2} y="17" textAnchor="middle">{label.value}</text>
          </g>
        ))}
      </svg>
    </article>
  );
}

