function getPlansCreditCurrentPlanKey(data = {}) {
  return data?.billing?.planKey || data?.billing?.currentPlanKey || data?.subscription?.planKey || PLANS_CREDIT_CURRENT_PLAN_KEY;
}

function isPlansCreditBillingEnabled(data = {}) {
  return Boolean(data?.billing?.shopifyBillingEnabled || data?.billing?.billingEnabled);
}

function getPlansCreditPlanCta(plan, currentPlanKey, billingEnabled) {
  if (plan.key === currentPlanKey) return plan.key === "starter" ? "Current starter plan" : "Current free plan";
  if (!billingEnabled) return "Billing disabled";
  if (plan.unavailable) return "Coming soon";
  return `Choose ${plan.name}`;
}

function getPlansCreditCancellationState(data = {}) {
  const billing = data?.billing || {};
  const active = Boolean(billing.cancellationKeepsAccess && (billing.planKey || billing.currentPlanKey) === "starter");
  const endsAt = billing.accessEndsAt || billing.currentPeriodEnd || "";
  const endsAtLabel = formatPlansDate(endsAt);
  return {
    active,
    planName: billing.planName || "Starter",
    endsAt,
    endsAtLabel,
    cancelledAtLabel: formatPlansDate(billing.cancelledAt),
  };
}

function getPlansCreditPointSummary(data = {}) {
  return data?.billing?.pointSummary || data?.pointSummary || null;
}

function getPlansCreditActivityRows(pointSummary) {
  const entries = Array.isArray(pointSummary?.activity) ? pointSummary.activity : [];
  return entries.slice(0, 10).map((entry) => {
    const direction = entry?.direction === "debit" ? "debit" : "credit";
    return {
      id: entry?.id || `${entry?.title || "diagnosis-credit"}-${entry?.createdAtIso || entry?.timeLabel || ""}`,
      title: entry?.title || (direction === "debit" ? "Credit usage" : "Credit added"),
      detail: entry?.detail || entry?.reason || "",
      direction,
      typeLabel: direction === "debit" ? "Spent" : "Earned",
      amountLabel: entry?.amountLabel || formatPlansCreditSignedAmount(entry?.amount || 0),
      balanceLabel: entry?.balanceAfterLabel ? `${entry.balanceAfterLabel} left` : "-",
      timeLabel: entry?.timeLabel || "",
    };
  });
}

function getPlansCreditPackViews(data = {}) {
  const configuredPacks = Array.isArray(data?.billing?.creditPacks) ? data.billing.creditPacks : [];
  return (configuredPacks.length ? configuredPacks : EXTRA_CREDIT_PACKS).map((pack) => ({
    id: pack.id || `pack_${pack.credits}`,
    credits: Number(pack.credits || 0),
    amountCents: Number(pack.amountCents || 0),
    compareAtPriceCents: Number(pack.compareAtPriceCents || 0),
    priceLabel: pack.priceLabel || formatPlansCurrency(pack.amountCents || 0, pack.currencyCode || "USD"),
    compareAtPriceLabel: pack.compareAtPriceLabel || (
      Number(pack.compareAtPriceCents || 0) > Number(pack.amountCents || 0)
        ? formatPlansCurrency(pack.compareAtPriceCents || 0, pack.currencyCode || "USD")
        : ""
    ),
    description: pack.description || "Extra credits",
  }));
}

function getPlansCreditPlanPricing(plan, data = {}) {
  if (plan.key === "free") {
    return { priceLabel: "$0", compareAtPriceLabel: "" };
  }
  const configuredPlan = Array.isArray(data?.billing?.plans)
    ? data.billing.plans.find((candidate) => candidate.key === plan.key)
    : null;
  const priceCents = configuredPlan?.priceCents ?? plan.basePriceCents ?? 0;
  const compareAtPriceCents = configuredPlan?.compareAtPriceCents ?? plan.compareAtPriceCents ?? 0;
  return {
    priceLabel: configuredPlan?.priceLabel || formatPlansCurrency(priceCents, configuredPlan?.currencyCode || "USD"),
    compareAtPriceLabel: configuredPlan?.compareAtPriceLabel || (
      compareAtPriceCents > priceCents
        ? formatPlansCurrency(compareAtPriceCents, configuredPlan?.currencyCode || "USD")
        : ""
    ),
  };
}

function formatPlansCurrency(amountCents, currencyCode = "USD") {
  const cents = Number(amountCents || 0);
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: currencyCode,
    maximumFractionDigits: Number.isInteger(cents / 100) ? 0 : 2,
  }).format(cents / 100);
}

function formatPlansDate(value) {
  const date = new Date(value || "");
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(date);
}

function formatPlansCreditSignedAmount(value = 0) {
  const number = Number(value || 0);
  const sign = number < 0 ? "-" : "+";
  return `${sign}${formatInteger(Math.abs(number))}`;
}

export function PlansCreditsScreen({ data = {} }) {
  const planFetcher = useFetcher();
  const creditPurchaseFetcher = useFetcher();
  const currentPlanKey = getPlansCreditCurrentPlanKey(data);
  const currentPlan = PLANS_CREDIT_PLANS.find((plan) => plan.key === currentPlanKey) || PLANS_CREDIT_PLANS[0];
  const visiblePlans = PLANS_CREDIT_PLANS.filter((plan) => !plan.unavailable || plan.key === currentPlanKey);
  const billingEnabled = isPlansCreditBillingEnabled(data);
  const cancellationState = getPlansCreditCancellationState(data);
  const pointSummary = getPlansCreditPointSummary(data);
  const creditPacks = getPlansCreditPackViews(data);
  const routeBillingMessage = data?.billing?.creditPurchaseResult?.message || data?.billing?.message || "";
  const routeBillingOk = data?.billing?.creditPurchaseResult?.ok;
  const planAction = planFetcher.data || null;
  const creditAction = creditPurchaseFetcher.data || null;
  const actionMessage = creditAction?.message || planAction?.message || routeBillingMessage;
  const actionOk = creditAction?.ok ?? planAction?.ok ?? routeBillingOk;
  const confirmationUrl = creditAction?.confirmationUrl || planAction?.confirmationUrl || "";
  const isPlanSubmitting = planFetcher.state !== "idle";
  const isCreditSubmitting = creditPurchaseFetcher.state !== "idle";
  const usedCredits = Number(pointSummary?.usage?.used ?? data?.billing?.usedCredits ?? data?.billing?.creditsUsed ?? data?.credits?.used ?? 0);
  const remainingCredits = Math.max(
    0,
    Number(pointSummary?.balance?.available ?? Number(currentPlan.monthlyCredits || 0) - usedCredits),
  );
  const pointActivityRows = getPlansCreditActivityRows(pointSummary);
  const plansFeedbackContext = {
    plansAndCredits: {
      currentPlanKey,
      currentPlanName: currentPlan.name,
      monthlyCredits: currentPlan.monthlyCredits,
      usedCredits,
      remainingCredits,
      billingEnabled,
      subscriptionCancelled: cancellationState.active,
      subscriptionEndsAt: cancellationState.endsAtLabel,
    },
  };
  const planComparisonFeedbackPanel = buildBetaFeedbackPanel("plans.planComparison", "Plan comparison", {
    ...plansFeedbackContext,
    planComparison: {
      planCount: visiblePlans.length,
      currentPlanKey,
      plans: visiblePlans.map((plan) => ({
        key: plan.key,
        name: plan.name,
        monthlyCredits: plan.monthlyCredits,
        unavailable: Boolean(plan.unavailable),
        billingEnabled,
      })),
    },
  });
  const creditPacksFeedbackPanel = buildBetaFeedbackPanel("plans.extraCreditPacks", "Extra credit packs", {
    ...plansFeedbackContext,
    extraCreditPacks: EXTRA_CREDIT_PACKS.map((pack) => ({
      credits: pack.credits,
      billingEnabled,
    })),
  });
  const billingFeedbackPanel = buildBetaFeedbackPanel("plans.billingInformation", "Billing information", plansFeedbackContext);
  const creditActivityFeedbackPanel = buildBetaFeedbackPanel("plans.creditActivity", "Credit activity", {
    ...plansFeedbackContext,
    creditActivity: {
      rowCount: pointActivityRows.length,
      visibleRows: pointActivityRows.slice(0, 8).map((entry) => ({
        title: entry.title,
        direction: entry.direction,
        amountLabel: entry.amountLabel,
        balanceLabel: entry.balanceLabel,
        timeLabel: entry.timeLabel,
      })),
    },
  });

  useEffect(() => {
    if (!confirmationUrl) return;
    try {
      window.top.location.href = confirmationUrl;
    } catch {
      window.location.href = confirmationUrl;
    }
  }, [confirmationUrl]);

  return (
    <FullWidthPage label="Plan & Credits" className="ppPlansPage">
      <ScreenShell className="ppDashboard ppPlansScreen">
        <div className="ppPlansTopbar">
          <div>
            <h1>Plan &amp; Credits</h1>
            <p>Track credits for Product Diagnosis usage. Plans and extra credit packs are billed through Shopify.</p>
          </div>
        </div>

        {actionMessage ? (
          <section className={`ppPlansNotice ${actionOk === false ? "isError" : "isSuccess"}`} role="status">
            <strong>{actionOk === false ? "Billing action needs attention" : "Billing update"}</strong>
            <p>{actionMessage}</p>
          </section>
        ) : null}

        <section className="ppPlansStatusGrid">
          <aside className="ppPlansBetaBanner" aria-label="Billing status">
            <span>{currentPlan.name}</span>
            <div>
              <strong>{billingEnabled ? "Shopify Billing is active for ProductPulse." : "ProductPulse is running without paid billing in this build."}</strong>
              <p>
                {billingEnabled
                  ? "Starter subscriptions and extra credit packs are approved through Shopify Billing. ProductPulse never collects payment details directly."
                  : "Plan changes and credit-pack purchases remain unavailable until they are implemented through Shopify Billing."}
              </p>
            </div>
          </aside>

          <aside className="ppPlansUsageCard" aria-label="Current usage">
            <strong>Current usage</strong>
            <div>
              <span>
                <small>Current plan</small>
                <b>{currentPlan.name}</b>
              </span>
              <span>
                <small>Monthly credits</small>
                <b>{formatInteger(currentPlan.monthlyCredits)}</b>
              </span>
              <span>
                <small>Used</small>
                <b>{formatInteger(usedCredits)}</b>
              </span>
              <span>
                <small>Left</small>
                <b className="ppPlansUsageLeft">{formatInteger(remainingCredits)}</b>
              </span>
            </div>
          </aside>
        </section>

        {cancellationState.active ? (
          <section className="ppPlansCancellationNotice" aria-label="Cancelled subscription status">
            <span aria-hidden="true"><PlansCreditsIcon type="clock" /></span>
            <div>
              <strong>{cancellationState.planName} subscription cancelled</strong>
              <p>
                Your {cancellationState.planName} benefits remain active until {cancellationState.endsAtLabel || "the end of the paid period"}. Restore the subscription before then to resume renewal.
              </p>
            </div>
          </section>
        ) : null}

      <BetaFeedbackPanelFrame panel={planComparisonFeedbackPanel}>
        <section className="ppPlansMatrixCard" id="plans-comparison" aria-label="Plan comparison">
          <div className="ppPlansBetaFeedbackCorner">
            <BetaFeedbackPanelControls panel={planComparisonFeedbackPanel} allowHide={false} />
          </div>
          <div className="ppPlansMatrix" style={{ "--pp-plans-visible-count": visiblePlans.length }}>
            <div className="ppPlansFeatureHeading">Features</div>
            {visiblePlans.map((plan) => {
              const pricing = getPlansCreditPlanPricing(plan, data);
              const priceLabel = plan.key === currentPlanKey && plan.key === "free" ? "Included" : pricing.priceLabel;
              return (
                <div
                  className={`ppPlansPlanHead ppPlansColumn-${plan.key}${plan.featured ? " isFeatured isFeaturedTop" : ""}${plan.premium ? " isPremium" : ""}${plan.key === currentPlanKey ? " isCurrent" : ""}${plan.unavailable ? " isUnavailable" : ""}`.trim()}
                  key={plan.key}
                >
                  {plan.badge && <span className={`ppPlansPlanBadge ppPlansPlanBadge-${plan.premium ? "green" : "purple"}`}>{plan.badge}</span>}
                  {plan.key === currentPlanKey && <span className={`ppPlansCurrentBadge${cancellationState.active && plan.key === "starter" ? " isCancelled" : ""}`}>{cancellationState.active && plan.key === "starter" ? "Cancelled" : "Current"}</span>}
                  <h2>{plan.name}</h2>
                  <div className="ppPlansPriceBlock">
                    {pricing.compareAtPriceLabel ? <span className="ppPlansOriginalPrice">{pricing.compareAtPriceLabel}</span> : null}
                    <strong>{priceLabel}</strong>
                    <em>{plan.key === "free" ? "forever" : "beta price / month"}</em>
                  </div>
                  <p>{plan.credits}</p>
                </div>
              );
            })}

            {PLANS_CREDIT_FEATURES.map((feature) => (
              <PlanFeatureRow feature={feature} plans={visiblePlans} key={feature.label} />
            ))}

            <div className="ppPlansFeatureCell ppPlansActionsSpacer" aria-hidden="true" />
            {visiblePlans.map((plan) => (
              <div
                className={`ppPlansActionCell ppPlansColumn-${plan.key}${plan.featured ? " isFeatured isFeaturedBottom" : ""}${plan.premium ? " isPremium" : ""}${plan.key === currentPlanKey ? " isCurrent" : ""}${plan.unavailable ? " isUnavailable" : ""}`.trim()}
                key={`${plan.key}-action`}
              >
                <PlanActionButton
                  billingEnabled={billingEnabled}
                  currentPlanKey={currentPlanKey}
                  isSubmitting={isPlanSubmitting}
                  plan={plan}
                  planFetcher={planFetcher}
                  cancellationState={cancellationState}
                  subscriptionId={data?.billing?.subscriptionId}
                  currentPeriodEndLabel={formatPlansDate(data?.billing?.currentPeriodEnd || data?.billing?.accessEndsAt)}
                />
              </div>
            ))}
          </div>
          <div className="ppPlansMobileCards" aria-label="Plan options">
            {visiblePlans.map((plan) => {
              const pricing = getPlansCreditPlanPricing(plan, data);
              const priceLabel = plan.key === currentPlanKey && plan.key === "free" ? "Included" : pricing.priceLabel;
              return (
                <article
                  className={`ppPlansMobileCard ppPlansColumn-${plan.key}${plan.key === currentPlanKey ? " isCurrent" : ""}${plan.unavailable ? " isUnavailable" : ""}`.trim()}
                  key={`${plan.key}-mobile`}
                >
                  <header>
                    <div>
                      <span className="ppPlansMobileCardEyebrow">
                        {plan.key === currentPlanKey ? "Current plan" : plan.badge || "Plan"}
                        {plan.key === currentPlanKey && cancellationState.active && plan.key === "starter" ? " · Cancelled" : ""}
                      </span>
                      <h2>{plan.name}</h2>
                    </div>
                    <div className="ppPlansMobilePrice">
                      {pricing.compareAtPriceLabel ? <span className="ppPlansOriginalPrice">{pricing.compareAtPriceLabel}</span> : null}
                      <strong>{priceLabel}</strong>
                      <em>{plan.key === "free" ? "forever" : "beta price / month"}</em>
                    </div>
                  </header>
                  <p>{plan.credits}</p>
                  <dl>
                    {PLANS_CREDIT_FEATURES.map((feature) => (
                      <div key={`${plan.key}-${feature.label}`}>
                        <dt>
                          {feature.icon ? <PlansCreditsIcon type={feature.icon} /> : null}
                          <span>{feature.label}</span>
                        </dt>
                        <dd>
                          <PlanFeatureValue value={feature.getValue(plan)} />
                        </dd>
                      </div>
                    ))}
                  </dl>
                  <div className="ppPlansMobileAction">
                    <PlanActionButton
                      billingEnabled={billingEnabled}
                      currentPlanKey={currentPlanKey}
                      isSubmitting={isPlanSubmitting}
                      plan={plan}
                      planFetcher={planFetcher}
                      cancellationState={cancellationState}
                      subscriptionId={data?.billing?.subscriptionId}
                      currentPeriodEndLabel={formatPlansDate(data?.billing?.currentPeriodEnd || data?.billing?.accessEndsAt)}
                    />
                  </div>
                </article>
              );
            })}
          </div>
        </section>
      </BetaFeedbackPanelFrame>

      <p className="ppPlansSecureNote">
        <PlansCreditsIcon type="shield" />
        Paid upgrades and purchasable credit packs are approved through Shopify Billing.
      </p>

      <section className="ppPlansLowerGrid">
        <BetaFeedbackPanelFrame panel={creditPacksFeedbackPanel}>
          <div className="ppPlansPanel ppPlansCreditPacks">
            <header>
              <div>
                <h2>Extra credit packs</h2>
                <p>Buy extra credits when your plan allowance is not enough for Product Diagnosis work.</p>
              </div>
              <BetaFeedbackPanelControls panel={creditPacksFeedbackPanel} allowHide={false} />
            </header>
            <div className="ppPlansPackGrid">
              {creditPacks.map((pack) => (
                <article className="ppPlansPackCard" key={pack.id}>
                  <span className="ppPlansPackIcon" aria-hidden="true"><PlansCreditsIcon type="wallet" /></span>
                  <strong>{formatInteger(pack.credits)}</strong>
                  <small>Credits</small>
                  {pack.compareAtPriceLabel ? <span className="ppPlansPackOriginalPrice">{pack.compareAtPriceLabel}</span> : null}
                  <b>{pack.priceLabel}</b>
                  <em>{pack.description}</em>
                  <creditPurchaseFetcher.Form method="post">
                    <input type="hidden" name="intent" value="buy-credit-pack" />
                    <input type="hidden" name="packageId" value={pack.id} />
                    <button
                      type="submit"
                      disabled={!billingEnabled || isCreditSubmitting ? true : undefined}
                    >
                      {isCreditSubmitting ? "Opening..." : `Buy ${formatInteger(pack.credits)} credits`}
                    </button>
                  </creditPurchaseFetcher.Form>
                </article>
              ))}
            </div>
            <p className="ppPlansPackFootnote">
              <PlansCreditsIcon type="info" />
              Extra credits are one-time Shopify app purchases and are added after Shopify confirms approval.
            </p>
            <p className="ppPlansPackFootnote">
              <PlansCreditsIcon type="info" />
              Unused purchased credits stay in your ProductPulse balance until they are consumed by Product Diagnosis.
            </p>
          </div>
        </BetaFeedbackPanelFrame>

        <div className="ppPlansPanel ppPlansFitPanel">
          <header>
            <h2>Which option fits best?</h2>
            <p>Based on product diagnoses per month</p>
          </header>
          <div className="ppPlansFitList">
            {PLAN_USAGE_OPTIONS.map((option) => (
              <article className={`ppPlansFitItem ppPlansFitItem-${option.tone}`} key={option.title}>
                <span aria-hidden="true"><PlansCreditsIcon type={option.icon} /></span>
                <div>
                  <strong>{option.title}</strong>
                  <b>{option.volume}</b>
                  <p>{option.detail}</p>
                </div>
              </article>
            ))}
          </div>
          <footer>
            <strong>Need help choosing?</strong>
            <a href="#plans-comparison">Compare all features <span aria-hidden="true">-&gt;</span></a>
          </footer>
        </div>
      </section>

      <BetaFeedbackPanelFrame panel={billingFeedbackPanel}>
        <section className="ppPlansBillingPanel" aria-label="Billing information">
          <div className="ppPlansBillingHeader">
            <h2>Billing information</h2>
            <BetaFeedbackPanelControls panel={billingFeedbackPanel} allowHide={false} />
          </div>
          <div className="ppPlansBillingGrid">
            <article>
              <span className="ppPlansBillingIcon ppPlansBillingIcon-green" aria-hidden="true"><PlansCreditsIcon type="rollover" /></span>
              <div>
                <strong>Rollover policy</strong>
                <p>Free credits reset according to ProductPulse internal credit rules.</p>
              </div>
            </article>
            <article>
              <span className="ppPlansBillingIcon ppPlansBillingIcon-purple" aria-hidden="true"><PlansCreditsIcon type="card" /></span>
              <div>
                <strong>Shopify Billing required</strong>
                <p>No payment method is collected by ProductPulse. Starter and credit packs must be approved through Shopify.</p>
              </div>
            </article>
            <article>
              <span className="ppPlansBillingIcon ppPlansBillingIcon-purple" aria-hidden="true"><PlansCreditsIcon type="gear" /></span>
              <div>
                <strong>Manage credits</strong>
                <p>Plan changes, invoices and cancellation are handled through Shopify app billing.</p>
                <Link to="/app/plans-and-credits">View credits <span aria-hidden="true">-&gt;</span></Link>
              </div>
            </article>
          </div>
        </section>
      </BetaFeedbackPanelFrame>

      <BetaFeedbackPanelFrame panel={creditActivityFeedbackPanel}>
        <section className="ppPlansPanel ppPlansLedgerPanel" aria-label="Credit activity">
          <header>
            <div>
              <h2>Credit activity</h2>
              <p>Latest credits earned and spent across free grants and Product Diagnosis usage.</p>
            </div>
            <BetaFeedbackPanelControls panel={creditActivityFeedbackPanel} allowHide={false} />
          </header>
          <div className="ppPlansLedgerTableWrap">
            <table className="ppPlansLedgerTable">
              <thead>
                <tr>
                  <th scope="col">Event</th>
                  <th scope="col">Type</th>
                  <th scope="col">Amount</th>
                  <th scope="col">Balance</th>
                  <th scope="col">When</th>
                </tr>
              </thead>
              <tbody>
                {pointActivityRows.length ? pointActivityRows.map((entry) => (
                  <tr key={entry.id}>
                    <td>
                      <strong>{entry.title}</strong>
                      {entry.detail ? <span>{entry.detail}</span> : null}
                    </td>
                    <td><span className={`ppPlansLedgerType ppPlansLedgerType-${entry.direction}`}>{entry.typeLabel}</span></td>
                    <td className={entry.direction === "debit" ? "isDebit" : "isCredit"}>{entry.amountLabel}</td>
                    <td>{entry.balanceLabel}</td>
                    <td>{entry.timeLabel || "-"}</td>
                  </tr>
                )) : (
                  <tr>
                    <td className="ppPlansLedgerEmpty" colSpan={5}>No credit activity yet.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>
      </BetaFeedbackPanelFrame>

      <footer className="ppPlansFooter">
        <span><PlansCreditsIcon type="lock" /> Secure checkout. Your data is encrypted and never shared.</span>
        <span>Questions? <Link to="/app/help">Contact support <span aria-hidden="true">-&gt;</span></Link></span>
      </footer>
      </ScreenShell>
    </FullWidthPage>
  );
}

function PlanActionButton({ billingEnabled, cancellationState = {}, currentPeriodEndLabel = "", currentPlanKey, isSubmitting, plan, planFetcher, subscriptionId }) {
  const [isCancelConfirmOpen, setCancelConfirmOpen] = useState(false);
  const classes = `ppPlansChooseButton${plan.featured ? " isPrimary" : ""}${plan.premium ? " isPremium" : ""}${plan.key === currentPlanKey ? " isCurrent" : ""}${plan.unavailable ? " isUnavailable" : ""}`;
  const label = getPlansCreditPlanCta(plan, currentPlanKey, billingEnabled);

  if (plan.key === currentPlanKey && plan.key === "starter") {
    if (cancellationState.active) {
      return (
        <planFetcher.Form className="ppPlansPlanActionForm" method="post">
          <input type="hidden" name="intent" value="restore-starter" />
          <button className={classes} disabled type="button">
            Active until {cancellationState.endsAtLabel || "period end"}
          </button>
          <button
            className="ppPlansRestoreButton"
            disabled={isSubmitting ? true : undefined}
            type="submit"
          >
            {isSubmitting ? "Opening..." : "Restore subscription"}
          </button>
        </planFetcher.Form>
      );
    }

    return (
      <div className="ppPlansPlanActionForm">
        <button className={classes} disabled type="button">
          {label}
        </button>
        <button
          className="ppPlansCancelButton"
          disabled={isSubmitting || !subscriptionId ? true : undefined}
          type="button"
          onClick={() => setCancelConfirmOpen(true)}
        >
          Cancel subscription
        </button>
        {isCancelConfirmOpen ? (
          <PlansCancelSubscriptionModal
            isSubmitting={isSubmitting}
            periodEndLabel={currentPeriodEndLabel}
            planFetcher={planFetcher}
            planName={plan.name}
            subscriptionId={subscriptionId}
            onCancel={() => setCancelConfirmOpen(false)}
          />
        ) : null}
      </div>
    );
  }

  if (plan.key === currentPlanKey || plan.unavailable || !billingEnabled || plan.key !== "starter") {
    return (
      <button
        className={classes}
        disabled
        type="button"
      >
        {label}
      </button>
    );
  }

  return (
    <planFetcher.Form className="ppPlansPlanActionForm" method="post">
      <input type="hidden" name="intent" value="subscribe-starter" />
      <button
        className={classes}
        disabled={isSubmitting ? true : undefined}
        type="submit"
      >
        {isSubmitting ? "Opening..." : label}
      </button>
    </planFetcher.Form>
  );
}

function PlansCancelSubscriptionModal({ isSubmitting, onCancel, periodEndLabel, planFetcher, planName, subscriptionId }) {
  return (
    <div className="ppAnalysisConfirmOverlay ppPlansCancelConfirmOverlay" role="presentation">
      <section className="ppAnalysisConfirmModal ppPlansCancelConfirmModal" role="dialog" aria-modal="true" aria-labelledby="plans-cancel-confirm-title">
        <div className="ppAnalysisConfirmHeader ppPlansCancelConfirmHeader">
          <span className="ppAnalysisConfirmIcon ppPlansCancelConfirmIcon" aria-hidden="true">
            <PlansCreditsIcon type="calendar" />
          </span>
          <div>
            <span>Subscription change</span>
            <h2 id="plans-cancel-confirm-title">Confirm cancellation</h2>
            <p>
              This will cancel your {planName} subscription through Shopify. You will keep access to all {planName} features until {periodEndLabel || "the end of the current billing cycle"}.
            </p>
          </div>
        </div>

        <div className="ppPlansCancelConfirmDetails">
          <article>
            <strong>Access stays active</strong>
            <p>Your plan benefits remain available until the paid billing period ends.</p>
          </article>
          <article>
            <strong>Restore anytime</strong>
            <p>You can restore the subscription before the period ends to continue renewals.</p>
          </article>
        </div>

        <div className="ppAnalysisConfirmFooter ppPlansCancelConfirmFooter">
          <button className="ppSecondaryButton" type="button" onClick={onCancel} disabled={isSubmitting}>
            Keep subscription
          </button>
          <planFetcher.Form method="post">
            <input type="hidden" name="intent" value="cancel-starter" />
            <input type="hidden" name="subscriptionId" value={subscriptionId || ""} />
            <button className="ppPlansCancelConfirmSubmit" disabled={isSubmitting || !subscriptionId ? true : undefined} type="submit">
              {isSubmitting ? "Cancelling..." : "Cancel subscription"}
            </button>
          </planFetcher.Form>
        </div>
      </section>
    </div>
  );
}

function PlanFeatureRow({ feature, plans = PLANS_CREDIT_PLANS }) {
  return (
    <>
      <div className="ppPlansFeatureCell">
        {feature.icon ? <PlansCreditsIcon type={feature.icon} /> : null}
        <strong>{feature.label}</strong>
        {feature.info && <span className="ppPlansInfoDot" aria-hidden="true">i</span>}
      </div>
      {plans.map((plan) => {
        const value = feature.getValue(plan);
        return (
          <div
            className={`ppPlansValueCell ppPlansColumn-${plan.key}${plan.featured ? " isFeatured" : ""}${plan.premium ? " isPremium" : ""}${plan.unavailable ? " isUnavailable" : ""}`.trim()}
            key={`${feature.label}-${plan.key}`}
          >
            <PlanFeatureValue value={value} />
          </div>
        );
      })}
    </>
  );
}

function PlanFeatureValue({ value }) {
  if (value === true) {
    return <span className="ppPlansCheck" aria-label="Included"><PlansCreditsIcon type="check" /></span>;
  }
  if (value && typeof value === "object") {
    return (
      <span className="ppPlansBetaLimit">
        <span>{value.base}</span>
        <strong>{value.beta}</strong>
        <em>Beta</em>
      </span>
    );
  }
  if (!value) return <span className="ppPlansDash">&mdash;</span>;
  return <span>{value}</span>;
}

function PlansCreditsIcon({ type }) {
  const common = {
    className: `ppPlansIcon ppPlansIcon-${type}`,
    viewBox: "0 0 24 24",
    "aria-hidden": "true",
    focusable: "false",
  };
  if (type === "brand") {
    return (
      <svg {...common}>
        <path d="M6.5 14.5 14.8 6.2a2.8 2.8 0 0 1 4 4l-8.3 8.3H6.5v-4Z" />
        <path d="M13.5 7.5 17 11" />
        <circle cx="18.5" cy="18.5" r="1.6" />
      </svg>
    );
  }
  if (type === "calendar") {
    return <svg {...common}><rect x="4.5" y="5.5" width="15" height="14" rx="2.2" /><path d="M8 3.8v3.5M16 3.8v3.5M4.5 9h15" /></svg>;
  }
  if (type === "info" || type === "help") {
    return <svg {...common}><circle cx="12" cy="12" r="8.2" /><path d="M12 16v-4" /><path d="M12 8.2h.01" /></svg>;
  }
  if (type === "tag") {
    return <svg {...common}><path d="M4.6 12.1 11.7 4.8h5.1l2.6 2.6v5.1l-7.2 7.2-7.6-7.6Z" /><circle cx="15.7" cy="8.8" r="1.15" /><path d="m8.7 12.2 1.7 1.7 3.8-4" /></svg>;
  }
  if (type === "users") {
    return <svg {...common}><circle cx="9" cy="8.4" r="2.4" /><path d="M4.8 18c.8-2.7 2.2-4 4.2-4s3.5 1.3 4.2 4" /><circle cx="16.3" cy="9.5" r="1.9" /><path d="M14.4 14.2c2.2 0 3.7 1.1 4.4 3.3" /></svg>;
  }
  if (type === "spark") {
    return <svg {...common}><path d="M12 3.8 14 9l5.2 2-5.2 2-2 5.2-2-5.2-5.2-2 5.2-2 2-5.2Z" /><path d="m18 4.5.7 1.8 1.8.7-1.8.7-.7 1.8-.7-1.8-1.8-.7 1.8-.7.7-1.8Z" /></svg>;
  }
  if (type === "assistant" || type === "support") {
    return <svg {...common}><path d="M5 12.8a7 7 0 0 1 14 0v3.7a2 2 0 0 1-2 2h-2.2" /><path d="M5 13h3v5H6.8A1.8 1.8 0 0 1 5 16.2V13ZM19 13h-3v5h1.2a1.8 1.8 0 0 0 1.8-1.8V13Z" /><path d="M10.5 19h3" /></svg>;
  }
  if (type === "chart" || type === "bars") {
    return <svg {...common}><path d="M5 19V5" /><path d="M5 19h14" /><rect x="7.5" y="12" width="2.7" height="4.5" rx=".8" /><rect x="11.2" y="8.5" width="2.7" height="8" rx=".8" /><rect x="15" y="5.8" width="2.7" height="10.7" rx=".8" /></svg>;
  }
  if (type === "timeline" || type === "pulse") {
    return <svg {...common}><path d="M4 13h3l2-5 4 9 2.5-6H20" /></svg>;
  }
  if (type === "binoculars") {
    return <svg {...common}><path d="M6.5 10.5 8.5 6h2l.8 4.5" /><path d="M17.5 10.5 15.5 6h-2l-.8 4.5" /><circle cx="8" cy="14" r="3.5" /><circle cx="16" cy="14" r="3.5" /><path d="M11.5 14h1" /><path d="M10.6 8.5h2.8" /></svg>;
  }
  if (type === "export") {
    return <svg {...common}><path d="M12 4v10" /><path d="m8 10 4 4 4-4" /><path d="M5 17.5h14" /></svg>;
  }
  if (type === "code") {
    return <svg {...common}><path d="m9 8-4 4 4 4" /><path d="m15 8 4 4-4 4" /><path d="m13 6-2 12" /></svg>;
  }
  if (type === "shield") {
    return <svg {...common}><path d="M12 4.3 18.5 7v5.2c0 4-2.4 6.6-6.5 7.7-4.1-1.1-6.5-3.7-6.5-7.7V7L12 4.3Z" /><path d="m9.2 12.3 1.8 1.8 3.8-4" /></svg>;
  }
  if (type === "wallet") {
    return <svg {...common}><rect x="4" y="6.8" width="16" height="11.5" rx="2.2" /><path d="M4 9.5h13.5a2 2 0 0 1 2 2v4.8" /><path d="M16 12h4v3.4h-4a1.7 1.7 0 0 1 0-3.4Z" /></svg>;
  }
  if (type === "heart") {
    return <svg {...common}><path d="M12 19s-7-4.4-7-9.2A3.7 3.7 0 0 1 11.5 7l.5.7.5-.7A3.7 3.7 0 0 1 19 9.8C19 14.6 12 19 12 19Z" /><path d="M6.7 12.5h3l1.2-2.4 2.2 4.8 1.4-2.4h2.9" /></svg>;
  }
  if (type === "rollover") {
    return <svg {...common}><path d="M18.2 9.4A6.8 6.8 0 1 0 19 13" /><path d="M18.2 4.8v4.6h-4.6" /><path d="M10 9.5v5l4 2" /></svg>;
  }
  if (type === "card") {
    return <svg {...common}><rect x="4" y="6.5" width="16" height="11" rx="2" /><path d="M4 10h16" /><path d="M7.2 14.3h4.5" /></svg>;
  }
  if (type === "gear") {
    return <svg {...common}><path d="M10.5 4.6h3l.6 2.1c.5.2 1 .5 1.4.8l2.1-.6 1.5 2.6-1.5 1.5c.1.5.1 1.1 0 1.6l1.5 1.5-1.5 2.6-2.1-.6c-.4.3-.9.6-1.4.8l-.6 2.1h-3l-.6-2.1c-.5-.2-1-.5-1.4-.8l-2.1.6-1.5-2.6 1.5-1.5c-.1-.5-.1-1.1 0-1.6L4.9 9.5l1.5-2.6 2.1.6c.4-.3.9-.6 1.4-.8l.6-2.1Z" /><circle cx="12" cy="12" r="2.6" /></svg>;
  }
  if (type === "lock") {
    return <svg {...common}><rect x="5.5" y="10" width="13" height="9" rx="2" /><path d="M8.2 10V7.8a3.8 3.8 0 0 1 7.6 0V10" /></svg>;
  }
  if (type === "check") {
    return <svg {...common}><path d="m5.5 12.5 4 4 9-9" /></svg>;
  }
  return <svg {...common}><circle cx="12" cy="12" r="7.5" /></svg>;
}

function HtmlStylePresetSettings({ value, onPresetChange, customTemplate, onCustomTemplateChange }) {
  const selectedPreset = value.preset === PRODUCT_PULSE_CUSTOM_HTML_STYLE_PRESET
    ? getProductPulseHtmlStylePreset(PRODUCT_PULSE_HTML_STYLE_PRESETS[0].id)
    : getProductPulseHtmlStylePreset(value.preset);
  const previewHtml = buildProductPulseHtmlStylePreviewHtml(value, {
    title: "Product note",
  });
  const customSelected = value.preset === PRODUCT_PULSE_CUSTOM_HTML_STYLE_PRESET;

  return (
    <div className="ppSettingsHtmlStyle">
      <div className="ppSettingsHtmlPresetGrid" role="list" aria-label="HTML style presets">
        {PRODUCT_PULSE_HTML_STYLE_PRESETS.map((preset) => {
          const selected = value.preset === preset.id;
          return (
            <button
              key={preset.id}
              type="button"
              className={`ppSettingsHtmlPresetCard ppSettingsHtmlPresetCard-${preset.tone}${selected ? " isSelected" : ""}`}
              onClick={() => onPresetChange(preset.id)}
              aria-pressed={selected}
            >
              <span>{preset.shortLabel}</span>
              <strong>{preset.label}</strong>
              <small>{preset.description}</small>
            </button>
          );
        })}
      </div>

      <div className="ppSettingsHtmlPreviewGrid">
        <div className="ppSettingsHtmlPreviewPanel">
          <div>
            <span>Live preview</span>
            <strong>{customSelected ? "Custom HTML template" : selectedPreset.label}</strong>
            <p>
              The preview uses sample ProductPulse content. Shopify receives the selected wrapper around generated notes or FAQs.
            </p>
          </div>
          <iframe title="Product HTML style preview" sandbox="" srcDoc={previewHtml}></iframe>
        </div>

        <div className="ppSettingsHtmlEditorPanel">
          <div className="ppSettingsHtmlEditorHeader">
            <div>
              <span>Custom template</span>
              <strong>Edit the wrapper HTML</strong>
            </div>
            <button
              type="button"
              className={`ppSecondaryButton${customSelected ? " isActive" : ""}`}
              onClick={() => onPresetChange(PRODUCT_PULSE_CUSTOM_HTML_STYLE_PRESET)}
            >
              Use custom HTML
            </button>
          </div>
          <label className="ppSettingsHtmlTemplateField">
            <span>HTML template</span>
            <textarea
              aria-label="Custom HTML template"
              value={customTemplate}
              onChange={(event) => onCustomTemplateChange(event.target.value)}
              placeholder={`<section ${PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.attributes}>\n  <h3>${PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.title}</h3>\n  ${PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.contentHtml}\n</section>`}
              rows={8}
            />
          </label>
          <div className="ppSettingsHtmlPlaceholderList" aria-label="Template placeholders">
            <span><code>{PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.attributes}</code> tracking attributes and wrapper classes</span>
            <span><code>{PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.headingHtml}</code> styled ProductPulse heading</span>
            <span><code>{PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.title}</code> plain title text</span>
            <span><code>{PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.contentHtml}</code> generated note, FAQ, specs, or content</span>
          </div>
          <p>
            Custom templates must include <code>{PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.contentHtml}</code>. If you omit <code>{PRODUCT_PULSE_HTML_TEMPLATE_PLACEHOLDERS.attributes}</code>, ProductPulse wraps your HTML to preserve tracking.
          </p>
        </div>
      </div>
    </div>
  );
}

function RiskThresholdSlider({ thresholds, onChange }) {
  const legend = [
    { label: "Ignored", value: `0-${Math.max(0, thresholds.minimumScore - 1)}` },
    { label: "Low", value: `${thresholds.minimumScore}-${Math.max(thresholds.minimumScore, thresholds.mediumThreshold - 1)}` },
    { label: "Medium", value: `${thresholds.mediumThreshold}-${Math.max(thresholds.mediumThreshold, thresholds.highThreshold - 1)}` },
    { label: "High", value: `${thresholds.highThreshold}-100` },
  ];

  const handleChange = (key) => (event) => {
    onChange(getNextClientRiskThresholds(thresholds, key, event.target.value));
  };

  return (
    <div className="ppSettingsRiskSlider" style={{
      "--pp-risk-floor": `${PRODUCT_PULSE_MIN_RISK_THRESHOLD}%`,
      "--pp-risk-min": `${thresholds.minimumScore}%`,
      "--pp-risk-medium": `${thresholds.mediumThreshold}%`,
      "--pp-risk-high": `${thresholds.highThreshold}%`,
    }}>
      <input type="hidden" name="minimumScore" value={thresholds.minimumScore} />
      <input type="hidden" name="mediumThreshold" value={thresholds.mediumThreshold} />
      <input type="hidden" name="highThreshold" value={thresholds.highThreshold} />

      <div className="ppSettingsRiskScale" aria-hidden="true">
        <span>0</span>
        <span>25</span>
        <span>50</span>
        <span>75</span>
        <span>100</span>
      </div>

      <div className="ppSettingsRiskTrack">
        <div className="ppSettingsRiskTrackBase" aria-hidden="true" />
        <input
          className="ppSettingsRiskRange ppSettingsRiskRange-min"
          type="range"
          aria-label="Minimum Catalog Scan score"
          min="0"
          max="100"
          step="1"
          value={thresholds.minimumScore}
          onChange={handleChange("minimumScore")}
        />
        <input
          className="ppSettingsRiskRange ppSettingsRiskRange-medium"
          type="range"
          aria-label="Medium risk starts at"
          min="0"
          max="100"
          step="1"
          value={thresholds.mediumThreshold}
          onChange={handleChange("mediumThreshold")}
        />
        <input
          className="ppSettingsRiskRange ppSettingsRiskRange-high"
          type="range"
          aria-label="High risk starts at"
          min="0"
          max="100"
          step="1"
          value={thresholds.highThreshold}
          onChange={handleChange("highThreshold")}
        />
      </div>

      <div className="ppSettingsRiskLegend" aria-label="Product risk intervals">
        {legend.map((item) => (
          <span key={item.label}>
            <strong>{item.label}</strong>
            {item.value}
          </span>
        ))}
      </div>
    </div>
  );
}

