function ProductMetricTimelineEventMarker(props = {}) {
  const cx = Number(props.cx);
  const cy = Number(props.cy);
  const event = props.payload || {};
  if (!Number.isFinite(cx) || !Number.isFinite(cy)) return null;
  const color = event.color || getProductMetricTimelineEventColor(event);
  const locked = Boolean(props.locked);
  return (
    <g
      className={`ppMetricTimelineEventMarker ppMetricTimelineEventMarker-${event.tone || "slate"}${locked ? " isLocked" : ""}${event.isOverflowMarker ? " isOverflow" : ""}`}
      transform={`translate(${cx} ${cy})`}
      style={{ "--pp-metric-timeline-event-color": color }}
    >
      <circle className="ppMetricTimelineEventMarkerHalo" r={locked ? 16 : 12} />
      <circle className="ppMetricTimelineEventMarkerCircle" r={locked ? 10 : 8} />
      {locked ? renderProductMetricTimelineLockGlyph("ppMetricTimelineEventMarkerLock") : event.isOverflowMarker ? (
        <text className="ppMetricTimelineEventMarkerMoreText" x="0" y="0">
          {formatProductMetricTimelineEventOverflowLabel(event.overflowCount)}
        </text>
      ) : renderProductMetricTimelineEventMarkerIcon(event)}
    </g>
  );
}

function ProductMetricTimelineLockedDotShape(props = {}) {
  const cx = Number(props.cx);
  const cy = Number(props.cy);
  if (!Number.isFinite(cx) || !Number.isFinite(cy)) return null;
  return (
    <g
      className="ppMetricTimelineLockedDot"
      transform={`translate(${cx} ${cy})`}
      style={{ "--pp-metric-timeline-locked-color": props.color || props.fill || "var(--pp-pulse-blue)" }}
    >
      <circle className="ppMetricTimelineLockedDotHalo" r="17" />
      <circle className="ppMetricTimelineLockedDotCircle" r="11" />
      {renderProductMetricTimelineLockGlyph("ppMetricTimelineLockedDotLock")}
    </g>
  );
}

function renderProductMetricTimelineLockGlyph(className = "ppMetricTimelineLockGlyph") {
  return (
    <>
      <rect className={className} x="-4.7" y="-0.8" width="9.4" height="6.6" rx="1.8" />
      <path className={className} d="M-3.1 -0.8V-2.9C-3.1 -4.9 -1.8 -6.1 0 -6.1C1.8 -6.1 3.1 -4.9 3.1 -2.9V-0.8" />
      <path className={className} d="M0 1.6V3.4" />
    </>
  );
}

function formatProductMetricTimelineEventOverflowLabel(count) {
  const value = Math.max(1, Math.min(PRODUCT_METRIC_TIMELINE_EVENT_OVERFLOW_LABEL_MAX, Math.round(Number(count) || 0)));
  return `+${value}`;
}

function renderProductMetricTimelineEventMarkerIcon(event = {}) {
  const normalized = `${event.category || ""} ${event.eventType || ""}`.toLowerCase();
  if (normalized.includes("action") || normalized.includes("applied") || normalized.includes("resolved")) {
    return <path className="ppMetricTimelineEventMarkerIcon" d="M-3.7 -0.1L-1.1 2.5L4.2 -3.2" />;
  }
  if (normalized.includes("review")) {
    return <path className="ppMetricTimelineEventMarkerIcon" d="M0 -4.8L1.4 -1.6L4.8 -1.3L2.2 0.9L3 4.2L0 2.4L-3 4.2L-2.2 0.9L-4.8 -1.3L-1.4 -1.6Z" />;
  }
  if (normalized.includes("return") || normalized.includes("refund")) {
    return (
      <>
        <path className="ppMetricTimelineEventMarkerIcon" d="M3.6 -2.8H-2.5C-4 -2.8 -5 -1.8 -5 -0.3C-5 1.2 -4 2.2 -2.5 2.2H3.2" />
        <path className="ppMetricTimelineEventMarkerIcon" d="M-2.5 -5L-5 -2.8L-2.5 -0.5" />
      </>
    );
  }
  if (normalized.includes("catalog") || normalized.includes("content") || normalized.includes("product")) {
    return (
      <>
        <path className="ppMetricTimelineEventMarkerIcon" d="M0 -4.8L4.1 -2.4V2.4L0 4.8L-4.1 2.4V-2.4Z" />
        <path className="ppMetricTimelineEventMarkerIcon" d="M-4 -2.2L0 0.1L4 -2.2" />
      </>
    );
  }
  if (normalized.includes("watch")) {
    return (
      <>
        <path className="ppMetricTimelineEventMarkerIcon" d="M-5 0C-3.8 -2.4 -2.2 -3.6 0 -3.6C2.2 -3.6 3.8 -2.4 5 0C3.8 2.4 2.2 3.6 0 3.6C-2.2 3.6 -3.8 2.4 -5 0Z" />
        <circle className="ppMetricTimelineEventMarkerIcon ppMetricTimelineEventMarkerIconFill" cx="0" cy="0" r="1.2" />
      </>
    );
  }
  if (normalized.includes("scan") || normalized.includes("diagnosis")) {
    return (
      <>
        <circle className="ppMetricTimelineEventMarkerIcon" cx="-0.9" cy="-0.9" r="3" />
        <path className="ppMetricTimelineEventMarkerIcon" d="M1.6 1.6L4.5 4.5" />
      </>
    );
  }
  if (normalized.includes("risk") || normalized.includes("issue")) {
    return (
      <>
        <path className="ppMetricTimelineEventMarkerIcon" d="M0 -4.2V0.8" />
        <path className="ppMetricTimelineEventMarkerIcon" d="M0 4.1H0.05" />
      </>
    );
  }
  return <circle className="ppMetricTimelineEventMarkerIcon ppMetricTimelineEventMarkerIconFill" cx="0" cy="0" r="2.3" />;
}

function ProductMetricTimelineActiveDot(props = {}) {
  const cx = Number(props.cx);
  const cy = Number(props.cy);
  if (!Number.isFinite(cx) || !Number.isFinite(cy)) return null;
  return <circle className="ppMetricTimelineActiveDot" cx={cx} cy={cy} r="6" style={{ fill: props.color || "currentColor" }} />;
}

function ProductMetricTimelineLegend({ chart }) {
  const items = Array.isArray(chart.legendItems) ? chart.legendItems : [];
  if (!items.length || (items.length < 2 && chart.kind !== "events")) return null;
  return (
    <div className={`ppMetricTimelineLegend${chart.kind === "events" ? " ppMetricTimelineLegend-events" : ""}`} aria-label={`${chart.title} ${chart.kind === "events" ? "event" : "line"} legend`}>
      {items.map((item) => (
        <span className="ppMetricTimelineLegendItem" key={`${chart.key}-${item.label}`}>
          {chart.kind === "events" ? (
            <ProductPulseIconBadge
              className="ppMetricTimelineLegendIcon"
              color={item.color}
              icon={item.icon || "chart-line"}
              size="legend"
              tone={item.tone || "slate"}
            />
          ) : (
            <i
              className={`ppMetricTimelineLegendLine${item.dashed ? " isDashed" : ""}`}
              style={{ "--pp-metric-timeline-legend-color": item.color }}
              aria-hidden="true"
            />
          )}
          {item.label}
        </span>
      ))}
    </div>
  );
}

function ProductMetricTimelineTooltip({ active, payload, chart, lockedPoint = null }) {
  const point = lockedPoint || (Array.isArray(payload) && payload.length ? payload[0]?.payload : null);
  if (!active || !point) return null;
  if (chart.kind === "events") return <ProductMetricTimelineEventTooltip event={point} />;
  return (
    <div className="ppRetentionLinePopover ppMetricTimelineTooltip" role="tooltip">
      <strong>{point.label}</strong>
      <span className="ppRetentionLinePopoverRows">
        <span><b>{chart.title}</b><small>{formatProductMetricTimelineValue(point.value, chart.axis)}</small></span>
        {getProductMetricTimelineSecondaryLines(chart).map((line) => {
          const value = point[line.dataKey];
          return value != null ? (
            <span key={`${chart.key}-${line.dataKey}`}><b>{line.label}</b><small>{formatProductMetricTimelineValue(value, line.axis || chart.axis)}</small></span>
          ) : null;
        })}
      </span>
    </div>
  );
}

function ProductMetricTimelineEventTooltip({ event = {} }) {
  const dayEvents = getProductMetricTimelineEventTooltipItems(event);
  const eventCount = dayEvents.length;
  return (
    <div className={`ppRetentionLinePopover ppMetricTimelineTooltip ppMetricTimelineEventTooltip ppMetricTimelineEventTooltip-${event.tone || "slate"}`} role="tooltip">
      <span className="ppMetricTimelineEventTooltipHeader">
        <strong>{event.dayLabel || event.dateLabel || event.label}</strong>
        <span>{formatInteger(eventCount)} {eventCount === 1 ? "event" : "events"}</span>
      </span>
      <span className="ppMetricTimelineEventTooltipGroups">
        {dayEvents.map((item) => (
          <span
            className="ppMetricTimelineEventTooltipRow"
            key={item.id || `${item.eventType}-${item.time}`}
            style={{ "--pp-metric-timeline-event-tooltip-color": item.color }}
          >
            <ProductPulseIconBadge
              className="ppMetricTimelineEventTooltipRowIcon"
              color={item.color}
              icon={item.icon || getProductTimelineIcon(item.category, item.eventType)}
              size="tooltip"
              tone={item.tone || "slate"}
            />
            <span className="ppMetricTimelineEventTooltipRowCopy">
              <span className="ppMetricTimelineEventTooltipTitle">
                <strong>{item.title}</strong>
                <time>{item.timeLabel || formatProductMetricTimelinePointTime(item.time)}</time>
              </span>
              <small>{item.summary || item.source || "ProductPulse timeline event"}</small>
            </span>
          </span>
        ))}
      </span>
    </div>
  );
}

function getProductMetricTimelineEventTooltipItems(event = {}) {
  const dayEvents = Array.isArray(event.dayEvents) && event.dayEvents.length ? event.dayEvents : [event];
  return [...dayEvents]
    .sort((left, right) => (left.time || 0) - (right.time || 0))
    .map((item) => ({
      ...item,
      color: item.color || getProductMetricTimelineEventColor(item),
      icon: item.icon || getProductTimelineIcon(item.category, item.eventType),
      tone: item.tone || "slate",
    }));
}

function getProductMetricTimelineEventsWithDayGroups(points = []) {
  const dayMap = new Map();
  points.forEach((point) => {
    const key = getProductMetricTimelineEventDayKey(point);
    if (!key) return;
    const events = dayMap.get(key) || [];
    events.push(point);
    dayMap.set(key, events);
  });

  const dayPayloads = new Map();
  dayMap.forEach((events, key) => {
    const sortedEvents = [...events].sort((left, right) => left.time - right.time);
    const groups = getProductMetricTimelineEventTooltipGroups(sortedEvents);
    dayPayloads.set(key, {
      dayEvents: sortedEvents,
      dayEventGroups: groups,
      dayEventCount: sortedEvents.length,
      dayLabel: getProductMetricTimelineEventDayLabel(sortedEvents[0]),
    });
  });

  return points.map((point) => ({
    ...point,
    ...(dayPayloads.get(getProductMetricTimelineEventDayKey(point)) || {}),
  }));
}

function getProductMetricTimelineVisibleEventMarkers(points = []) {
  const dayMap = new Map();
  points.forEach((point) => {
    const key = getProductMetricTimelineEventDayKey(point);
    if (!key) return;
    const events = dayMap.get(key) || [];
    events.push(point);
    dayMap.set(key, events);
  });

  const markers = [];
  dayMap.forEach((events, key) => {
    const sortedEvents = [...events].sort((left, right) => left.time - right.time);
    if (sortedEvents.length <= PRODUCT_METRIC_TIMELINE_EVENT_VISIBLE_PER_DAY) {
      markers.push(...sortedEvents);
      return;
    }

    const visibleEvents = sortedEvents.slice(0, PRODUCT_METRIC_TIMELINE_EVENT_VISIBLE_PER_DAY);
    const overflowEvents = sortedEvents.slice(PRODUCT_METRIC_TIMELINE_EVENT_VISIBLE_PER_DAY);
    const overflowBase = overflowEvents[0] || sortedEvents[0];
    const overflowLane = Math.min(
      PRODUCT_METRIC_TIMELINE_EVENT_MAX_LANES,
      Math.max(
        PRODUCT_METRIC_TIMELINE_EVENT_VISIBLE_PER_DAY + 1,
        Number(overflowBase.lane || overflowBase.value || 1),
      ),
    );
    markers.push(...visibleEvents);
    markers.push({
      ...overflowBase,
      id: `${key}-overflow-${overflowEvents.length}`,
      title: `${formatInteger(overflowEvents.length)} more events`,
      summary: `${formatInteger(sortedEvents.length)} events occurred on ${overflowBase.dayLabel || overflowBase.dateLabel || overflowBase.label || "this day"}.`,
      eventType: "timeline_event_overflow",
      isOverflowMarker: true,
      overflowCount: overflowEvents.length,
      dayEvents: sortedEvents,
      dayEventGroups: getProductMetricTimelineEventTooltipGroups(sortedEvents),
      dayEventCount: sortedEvents.length,
      dayLabel: overflowBase.dayLabel || getProductMetricTimelineEventDayLabel(overflowBase),
      lane: overflowLane,
      value: overflowLane,
      color: "var(--pp-slate-700)",
      icon: "plus",
      tone: "slate",
    });
  });

  return markers.sort((left, right) => left.time - right.time || Number(left.lane || 0) - Number(right.lane || 0));
}

function getProductMetricTimelineEventTooltipGroups(events = []) {
  const groupMap = new Map();
  events.forEach((event) => {
    const key = event.category || "timeline";
    const existing = groupMap.get(key) || {
      key,
      label: event.categoryLabel || getProductTimelineCategoryLabel(key),
      icon: event.icon || getProductTimelineIcon(key, event.eventType),
      color: event.color || getProductMetricTimelineEventColor(event),
      tone: event.tone || "slate",
      events: [],
      firstTime: event.time,
    };
    existing.events.push(event);
    existing.firstTime = Math.min(existing.firstTime, event.time);
    groupMap.set(key, existing);
  });
  return Array.from(groupMap.values())
    .map((group) => ({ ...group, events: [...group.events].sort((left, right) => left.time - right.time) }))
    .sort((left, right) => right.events.length - left.events.length || left.firstTime - right.firstTime || left.label.localeCompare(right.label));
}

function getProductMetricTimelineEventDayKey(event = {}) {
  if (event.dayKey) return String(event.dayKey);
  const date = parseProductMetricTimelineDate(event.time || event.occurredAt);
  return date ? date.toISOString().slice(0, 10) : "";
}

function getProductMetricTimelineEventDayLabel(event = {}) {
  if (event.dateLabel) return event.dateLabel;
  const date = parseProductMetricTimelineDate(event.time || event.occurredAt);
  return date ? formatProductMetricTimelinePointLabel(date) : "Timeline events";
}

function formatProductMetricTimelinePointTime(time) {
  const date = parseProductMetricTimelineDate(time);
  return date ? formatTimelineClock(date) : "";
}

function ProductMetricTimelineOrderActivityTooltip({ active, payload, lockedPoint = null }) {
  const point = lockedPoint || (Array.isArray(payload) && payload.length ? payload[0]?.payload : null);
  if (!active || !point) return null;
  return (
    <div className="ppRetentionLinePopover ppMetricTimelineTooltip" role="tooltip">
      <strong>{point.label}</strong>
      <span><b>Orders</b><small>{formatInteger(point.orders)} orders · {formatInteger(point.orderUnits)} units</small></span>
      <span><b>Returns</b><small>{formatInteger(point.returnedOrders)} cohorts · {formatInteger(point.returnedUnits)} units</small></span>
      <span><b>Refunds</b><small>{formatInteger(point.refundedOrders)} cohorts · {formatInteger(point.refundedUnits)} units</small></span>
      <span><b>Revenue</b><small>{formatMoney(point.revenue || 0)}</small></span>
      <span><b>Unresolved returns</b><small>{formatInteger(point.unresolvedReturns || 0)}</small></span>
    </div>
  );
}

function getProductMetricTimelineClickTime(chart = {}, active = {}) {
  if (chart.kind === "events") {
    const activeIndex = getProductMetricTimelineActiveIndex(active);
    const eventPoint = Number.isFinite(activeIndex) ? getProductMetricTimelineTooltipData(chart)[activeIndex] : null;
    const eventTime = getProductMetricTimelineSyncTime(eventPoint?.time);
    if (Number.isFinite(eventTime)) return eventTime;
  }

  const labelTime = getProductMetricTimelineSyncTime(active?.activeLabel);
  if (Number.isFinite(labelTime)) return labelTime;

  const activeIndex = getProductMetricTimelineActiveIndex(active);
  if (!Number.isFinite(activeIndex)) return null;
  const data = getProductMetricTimelineTooltipData(chart);
  const point = data[activeIndex];
  const pointTime = getProductMetricTimelineSyncTime(point?.time);
  return Number.isFinite(pointTime) ? pointTime : null;
}

function getProductMetricTimelineActiveIndex(active = {}) {
  const index = Number(active?.activeTooltipIndex ?? active?.activeIndex);
  return Number.isFinite(index) ? Math.round(index) : null;
}

function getProductMetricTimelineLockedTooltipIndex(chart = {}, lockedTime) {
  const targetTime = getProductMetricTimelineSyncTime(lockedTime);
  if (!Number.isFinite(targetTime)) return undefined;
  const data = getProductMetricTimelineTooltipData(chart);
  if (!data.length) return undefined;
  const ticks = data.map((point) => ({ value: point?.time }));
  return getProductMetricTimelineNearestSyncIndex(ticks, { activeLabel: targetTime });
}

function getProductMetricTimelineLockedTooltipPoint(chart = {}, lockedTooltipIndex) {
  if (!Number.isFinite(lockedTooltipIndex)) return null;
  const data = getProductMetricTimelineTooltipData(chart);
  return data[lockedTooltipIndex] || null;
}

function getProductMetricTimelineTooltipData(chart = {}) {
  if (Array.isArray(chart.data) && chart.data.length) return chart.data;
  return Array.isArray(chart.points) ? chart.points : [];
}

function getProductMetricTimelineTooltipLockProps(lockedTooltipIndex) {
  if (!Number.isFinite(lockedTooltipIndex)) return {};
  return {
    active: true,
    defaultIndex: lockedTooltipIndex,
    trigger: "click",
  };
}

function getProductMetricTimelineNearestSyncIndex(ticks = [], active = {}) {
  if (!Array.isArray(ticks) || !ticks.length) return 0;
  const target = getProductMetricTimelineSyncTime(active?.activeLabel);
  if (!Number.isFinite(target)) {
    const fallbackIndex = Math.round(Number(active?.activeTooltipIndex ?? active?.activeIndex ?? 0));
    return Math.round(clampNumber(fallbackIndex, 0, ticks.length - 1));
  }

  let nearestIndex = 0;
  let nearestDistance = Infinity;
  ticks.forEach((tick, index) => {
    const value = getProductMetricTimelineSyncTime(tick?.value);
    if (!Number.isFinite(value)) return;
    const distance = Math.abs(value - target);
    if (distance < nearestDistance) {
      nearestDistance = distance;
      nearestIndex = index;
    }
  });
  const maxDistance = PRODUCT_METRIC_TIMELINE_SYNC_MAX_DISTANCE_DAYS * PRODUCT_METRIC_TIMELINE_DAY_MS;
  return nearestDistance <= maxDistance ? nearestIndex : undefined;
}

function getProductMetricTimelineSyncTime(value) {
  if (value == null || value === "") return null;
  const number = Number(value);
  if (Number.isFinite(number)) return number;
  const date = parseProductMetricTimelineDate(value);
  return date ? date.getTime() : null;
}

function readProductMetricTimelineChartOrder() {
  if (typeof window === "undefined" || !window.localStorage) return [];
  try {
    const stored = JSON.parse(window.localStorage.getItem(PRODUCT_METRIC_TIMELINE_ORDER_STORAGE_KEY) || "[]");
    return Array.isArray(stored) ? stored.filter((key) => typeof key === "string") : [];
  } catch {
    return [];
  }
}

function saveProductMetricTimelineChartOrder(order = []) {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    window.localStorage.setItem(PRODUCT_METRIC_TIMELINE_ORDER_STORAGE_KEY, JSON.stringify(order));
  } catch {
    // Browsers can reject localStorage in private or embedded contexts.
  }
}

function normalizeProductMetricTimelineChartOrder(availableKeys = [], order = []) {
  const available = availableKeys.filter((key) => typeof key === "string");
  const availableSet = new Set(available);
  const normalized = [];
  (Array.isArray(order) ? order : []).forEach((key) => {
    if (availableSet.has(key) && !normalized.includes(key)) normalized.push(key);
  });
  available.forEach((key) => {
    if (!normalized.includes(key)) normalized.push(key);
  });
  return normalized;
}

function getProductMetricTimelineOrderedCharts(charts = [], order = []) {
  const chartMap = new Map(charts.map((chart) => [chart.key, chart]));
  return normalizeProductMetricTimelineChartOrder(charts.map((chart) => chart.key), order)
    .map((key) => chartMap.get(key))
    .filter(Boolean);
}

function moveProductMetricTimelineChartOrder(availableKeys = [], order = [], chartKey, direction) {
  const normalized = normalizeProductMetricTimelineChartOrder(availableKeys, order);
  const index = normalized.indexOf(chartKey);
  const targetIndex = direction === "up" ? index - 1 : direction === "down" ? index + 1 : index;
  if (index < 0 || targetIndex < 0 || targetIndex >= normalized.length || targetIndex === index) return normalized;
  const next = [...normalized];
  [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
  return next;
}

function isProductMetricTimelineTopPinnedChart(chart = {}) {
  return chart.pinned === true || chart.pinPosition === "top";
}

function isProductMetricTimelineBottomPinnedChart(chart = {}) {
  return chart.pinPosition === "bottom";
}

function isProductMetricTimelinePinnedChart(chart = {}) {
  return isProductMetricTimelineTopPinnedChart(chart) || isProductMetricTimelineBottomPinnedChart(chart);
}

