function getReturnRefundResolutionBuckets(relationship = {}) {
  const buckets = [
    { key: "linked", label: "Return + refund", value: relationship.returnedAndRefundedUnits, displayValue: `${formatInteger(relationship.returnedAndRefundedUnits)} units`, tone: "red" },
    { key: "return-only", label: "Return only", value: relationship.returnedNotRefundedUnits, displayValue: `${formatInteger(relationship.returnedNotRefundedUnits)} units`, tone: "amber" },
    { key: "refund-only", label: "Refund only", value: relationship.refundedWithoutReturnUnits, displayValue: `${formatInteger(relationship.refundedWithoutReturnUnits)} units`, tone: "blue" },
    { key: "exchange", label: "Exchange/replacement", value: relationship.exchangeOrReplacementUnits, displayValue: `${formatInteger(relationship.exchangeOrReplacementUnits)} units`, tone: "green" },
    { key: "unknown", label: "Pending/unknown", value: relationship.pendingOrUnknownCount, displayValue: `${formatInteger(relationship.pendingOrUnknownCount)} cases`, tone: "slate" },
  ];
  const total = buckets.reduce((sum, bucket) => sum + Math.max(0, Number(bucket.value || 0)), 0);
  if (!total) return buckets.map((bucket) => ({ ...bucket, width: bucket.key === "unknown" ? 100 : 0 }));
  return buckets.map((bucket) => ({
    ...bucket,
    width: Math.max(Number(bucket.value || 0) > 0 ? 5 : 0, (Number(bucket.value || 0) / total) * 100),
  }));
}

function ProductRiskSiblingNavigation({ navigation = {}, currentTitle = "" }) {
  const previous = navigation?.previous || null;
  const next = navigation?.next || null;
  return (
    <nav className="ppProductRiskSiblingNav" aria-label="Navigate products by risk score">
      <ProductRiskSiblingLink direction="previous" item={previous} fallbackTitle={currentTitle} />
      <ProductRiskSiblingLink direction="next" item={next} fallbackTitle={currentTitle} />
    </nav>
  );
}

function ProductRiskSiblingLink({ direction, item, fallbackTitle = "" }) {
  const isPrevious = direction === "previous";
  const label = isPrevious ? "Previous product" : "Next product";
  const helper = isPrevious ? "Higher risk" : "Lower risk";
  const icon = isPrevious ? "chevron-left" : "chevron-right";
  const riskLabel = item?.riskScore != null ? `${item.riskScore}/100` : "";
  const title = item?.title || fallbackTitle || "product";
  const content = (
    <>
      {isPrevious && <s-icon type={icon} size="small"></s-icon>}
      <span>
        <strong>{label}</strong>
        <small>{item ? `${helper}${riskLabel ? ` · ${riskLabel}` : ""}` : `No ${helper.toLowerCase()}`}</small>
      </span>
      {!isPrevious && <s-icon type={icon} size="small"></s-icon>}
    </>
  );

  if (!item?.href) {
    return (
      <span className="ppProductRiskSiblingLink isUnavailable" aria-disabled="true">
        {content}
      </span>
    );
  }

  return (
    <Link
      className="ppProductRiskSiblingLink"
      to={item.href}
      title={`Go to ${helper.toLowerCase()} product: ${title}${riskLabel ? ` (${riskLabel})` : ""}`}
    >
      {content}
    </Link>
  );
}

