const PRODUCT_RETENTION_LTV_BREAKDOWN_MODES = [
  { key: "cumulative", label: "Cumulative (USD)", ariaLabel: "Show LTV breakdown as cumulative dollars" },
  { key: "share", label: "Share", ariaLabel: "Show LTV breakdown as share" },
  { key: "perCustomer", label: "Per customer", ariaLabel: "Show LTV breakdown per customer" },
];

function ProductRetentionLtvBreakdown({ chart, productTitle }) {
  const [mode, setMode] = useState("cumulative");
  const view = useMemo(() => getProductRetentionLtvBreakdownView(chart, mode), [chart, mode]);

  return (
    <article className="ppRetentionChartCard ppRetentionLtvCard ppRetentionLtvBreakdownCard">
      <div className="ppRetentionBreakdownHeader">
        <div className="ppRetentionBreakdownTitle">
          <span className="ppRetentionBreakdownIcon" aria-hidden="true">
            <ProductPulseGlyph type="financial-exposure" />
          </span>
          <div>
            <h3>LTV Breakdown</h3>
            <p>Where LTV comes from after the first purchase of this product.</p>
          </div>
        </div>
      </div>
      {chart.hasData ? (
        <>
          <div className="ppRetentionBreakdownModes" role="group" aria-label="LTV breakdown view">
            {PRODUCT_RETENTION_LTV_BREAKDOWN_MODES.map((item) => (
              <button
                key={item.key}
                type="button"
                className={mode === item.key ? "isActive" : ""}
                aria-pressed={mode === item.key}
                aria-label={item.ariaLabel}
                onClick={() => setMode(item.key)}
              >
                {item.label}
              </button>
            ))}
          </div>
          <ProductRetentionLtvStackedChart chart={view} productTitle={productTitle} />
          <ProductRetentionLtvBreakdownLegend includeInitial={view.includeInitial} />
        </>
      ) : (
        <ProductRetentionEmptySlot message="No LTV breakdown is stored yet." />
      )}
    </article>
  );
}

function ProductRetentionLtvStackedChart({ chart, productTitle }) {
  const gradientIdBase = `ppRetentionLtvBreakdownGradient-${useId().replace(/:/g, "")}`;
  return (
    <div className="ppRetentionLtvBreakdownChart" role="group" aria-label={`LTV breakdown for ${productTitle}`}>
      <AreaChart
        width={chart.width}
        height={chart.height}
        data={chart.data}
        margin={{ top: 24, right: 24, left: 18, bottom: 34 }}
        syncId="product-retention-ltv-breakdown"
      >
          <defs>
            <linearGradient id={`${gradientIdBase}-same`} x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stopColor="var(--pp-insight-violet)" stopOpacity="0.88" />
              <stop offset="100%" stopColor="var(--pp-insight-violet)" stopOpacity="0.18" />
            </linearGradient>
            <linearGradient id={`${gradientIdBase}-other`} x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stopColor="var(--pp-pulse-blue)" stopOpacity="0.78" />
              <stop offset="100%" stopColor="var(--pp-pulse-blue)" stopOpacity="0.16" />
            </linearGradient>
            <linearGradient id={`${gradientIdBase}-initial`} x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stopColor="var(--pp-signal-teal)" stopOpacity="0.72" />
              <stop offset="100%" stopColor="var(--pp-signal-teal)" stopOpacity="0.14" />
            </linearGradient>
          </defs>
          <CartesianGrid vertical={false} stroke="rgba(100, 116, 139, 0.16)" strokeDasharray="5 7" />
          <XAxis
            dataKey="ageDay"
            type="number"
            domain={[0, chart.xMax]}
            ticks={chart.xTicks.map((tick) => tick.value)}
            tickFormatter={(value) => formatInteger(value)}
            axisLine={{ stroke: "rgba(100, 116, 139, 0.28)" }}
            tickLine={{ stroke: "rgba(100, 116, 139, 0.28)" }}
            tick={{ fill: "var(--pp-slate-600)", fontSize: 11, fontWeight: 850 }}
            allowDecimals={false}
          />
          <YAxis
            domain={[0, chart.yMax]}
            ticks={chart.yTicks.map((tick) => tick.value)}
            tickFormatter={chart.yFormatter}
            axisLine={{ stroke: "rgba(100, 116, 139, 0.28)" }}
            tickLine={false}
            tick={{ fill: "var(--pp-slate-600)", fontSize: 11, fontWeight: 850 }}
            width={58}
          />
          <RechartsTooltip
            content={<ProductRetentionLtvTooltipContent chart={chart} />}
            cursor={{ stroke: "rgba(124, 92, 255, 0.36)", strokeWidth: 1.5, strokeDasharray: "5 5" }}
            wrapperStyle={{ outline: "none", zIndex: 8 }}
          />
          {chart.includeInitial ? (
            <Area
              type="monotone"
              dataKey="initialValue"
              stackId="ltv"
              name="Initial product"
              stroke="var(--pp-signal-teal)"
              strokeWidth={2.4}
              fill={`url(#${gradientIdBase}-initial)`}
              dot={false}
              activeDot={false}
              isAnimationActive={false}
            />
          ) : null}
          <Area
            type="monotone"
            dataKey="otherValue"
            stackId="ltv"
            name="Cross-sell"
            stroke="var(--pp-pulse-blue)"
            strokeWidth={2.4}
            fill={`url(#${gradientIdBase}-other)`}
            dot={false}
            activeDot={false}
            isAnimationActive={false}
          />
          <Area
            type="monotone"
            dataKey="sameValue"
            stackId="ltv"
            name="Same product"
            stroke="var(--pp-insight-violet)"
            strokeWidth={2.8}
            fill={`url(#${gradientIdBase}-same)`}
            dot={false}
            activeDot={<ProductRetentionLtvActiveDot />}
            isAnimationActive={false}
          />
      </AreaChart>
      <span className="ppRetentionLineAxisTitle ppRetentionLineAxisTitle-y">{chart.yAxisLabel}</span>
      <span className="ppRetentionLineAxisTitle ppRetentionLineAxisTitle-x">Days since first purchase</span>
    </div>
  );
}

function ProductRetentionLtvActiveDot(props = {}) {
  const cx = Number(props.cx);
  const cy = Number(props.cy);
  if (!Number.isFinite(cx) || !Number.isFinite(cy)) return null;
  return <circle className="ppRetentionLtvActiveDot" cx={cx} cy={cy} r="6" />;
}

function ProductRetentionLtvTooltipContent({ active, payload, chart }) {
  const row = Array.isArray(payload) && payload.length ? payload[0]?.payload : null;
  if (!active || !row) return null;
  return (
    <div className="ppRetentionLinePopover ppRetentionLtvPopover ppRetentionRechartsTooltip" role="tooltip">
      <strong>{row.xLabel}</strong>
      <span className="ppRetentionLinePopoverRows">
        {chart.includeInitial ? (
          <span><b>Initial product</b><small>{chart.valueFormatter(row.initialValue, row.initialProductCents)}</small></span>
        ) : null}
        <span><b>Cross-sell</b><small>{chart.valueFormatter(row.otherValue, row.otherProductCents)}</small></span>
        <span><b>Same product</b><small>{chart.valueFormatter(row.sameValue, row.sameProductRepeatCents)}</small></span>
        <span><b>{chart.totalLabel}</b><small>{chart.valueFormatter(row.totalValue, row.displayTotalCents)}</small></span>
      </span>
    </div>
  );
}

function ProductRetentionLtvBreakdownLegend({ includeInitial = true }) {
  return (
    <div className="ppRetentionLtvBreakdownLegend">
      <span><i className="ppRetentionLegendLtvSame" />Same product</span>
      <span><i className="ppRetentionLegendLtvOther" />Other products (cross-sell)</span>
      {includeInitial ? <span><i className="ppRetentionLegendLtvInitial" />Initial product (1st purchase)</span> : null}
    </div>
  );
}

function ProductRetentionLtvContributionDonut({ contribution }) {
  const total = Math.max(0, Number(contribution.totalCents || 0));
  const sameShare = total ? (contribution.sameProductRepeatCents / total) * 100 : 0;
  const otherShare = total ? (contribution.otherProductCents / total) * 100 : 0;
  const initialShare = Math.max(0, 100 - sameShare - otherShare);
  const rows = [
    { key: "same", label: "Same product", value: contribution.sameProductRepeatCents, share: sameShare, className: "ppRetentionLegendLtvSame", color: "var(--pp-insight-violet)" },
    { key: "other", label: "Other products", value: contribution.otherProductCents, share: otherShare, className: "ppRetentionLegendLtvOther", color: "var(--pp-pulse-blue)" },
    { key: "initial", label: "Initial product", value: contribution.initialProductCents, share: initialShare, className: "ppRetentionLegendLtvInitial", color: "var(--pp-signal-teal)" },
  ];
  const pieRows = total ? rows.filter((row) => row.value > 0) : [{ key: "empty", label: "No LTV", value: 1, share: 100, color: "var(--pp-slate-200)" }];

  return (
    <section className="ppRetentionLtvDetailCard">
      <h4>LTV contribution ({formatInteger(contribution.ageDay)} days)</h4>
      <div className="ppRetentionLtvDonutWrap">
        <div className="ppRetentionLtvDonut" aria-label={`LTV contribution total ${formatRetentionMoneyCents(total)}`}>
          <div className="ppRetentionLtvDonutChart" aria-hidden="true">
            <PieChart width={210} height={210}>
              <Pie
                data={pieRows}
                dataKey="value"
                nameKey="label"
                innerRadius="68%"
                outerRadius="96%"
                startAngle={90}
                endAngle={-270}
                paddingAngle={total ? 2 : 0}
                stroke="var(--pp-cloud-white)"
                strokeWidth={3}
                isAnimationActive={false}
              >
                {pieRows.map((row) => <Cell key={row.key} fill={row.color} />)}
              </Pie>
              <RechartsTooltip
                content={<ProductRetentionLtvDonutTooltip />}
                wrapperStyle={{ outline: "none", zIndex: 8 }}
              />
            </PieChart>
          </div>
          <div className="ppRetentionLtvDonutCenter">
            <strong>{formatRetentionMoneyCents(total)}</strong>
            <span>LTV total</span>
          </div>
        </div>
        <div className="ppRetentionLtvDonutLegend">
          {rows.map((row) => (
            <span key={row.key}>
              <i className={row.className} />
              <b>{row.label}</b>
              <strong>{formatRetentionMoneyCents(row.value)} <small>({formatPercent(row.share)})</small></strong>
            </span>
          ))}
        </div>
      </div>
    </section>
  );
}

function ProductRetentionLtvDonutTooltip({ active, payload }) {
  const row = Array.isArray(payload) && payload.length ? payload[0]?.payload : null;
  if (!active || !row) return null;
  return (
    <div className="ppRetentionLinePopover ppRetentionLtvPopover ppRetentionRechartsTooltip" role="tooltip">
      <strong>{row.label}</strong>
      <span className="ppRetentionLinePopoverRows">
        <span><b>Contribution</b><small>{formatRetentionMoneyCents(row.value)}</small></span>
        <span><b>Share</b><small>{formatPercent(row.share)}</small></span>
      </span>
    </div>
  );
}

function ProductRetentionLtvInsights({ contribution, summary }) {
  const total = Math.max(0, Number(contribution.totalCents || 0));
  const followOnCents = Math.max(0, Number(contribution.sameProductRepeatCents || 0) + Number(contribution.otherProductCents || 0));
  const followOnShare = total ? followOnCents / total : 0;
  const sameProductShare = total ? Number(contribution.sameProductRepeatCents || 0) / total : 0;
  const medianDays = summary?.medianDaysToSecondPurchase == null ? "N/A" : formatRetentionDays(summary.medianDaysToSecondPurchase);

  return (
    <section className="ppRetentionLtvDetailCard ppRetentionLtvInsightsCard">
      <h4>Key insights</h4>
      <div className="ppRetentionLtvInsightRows">
        <span>
          <i><ProductPulseGlyph type="product-momentum" /></i>
          <b>{formatRetentionRate(followOnShare)} of {formatInteger(contribution.ageDay)}-day LTV comes from repeat purchases and cross-sell.</b>
        </span>
        <span>
          <i><ProductPulseGlyph type="diagnostic-confidence" /></i>
          <b>Median time to second purchase is {medianDays}.</b>
        </span>
        <span>
          <i><ProductPulseGlyph type="shopify-product" /></i>
          <b>Same-product repurchases contribute {formatRetentionMoneyCents(contribution.sameProductRepeatCents)} ({formatRetentionRate(sameProductShare)}) of LTV.</b>
        </span>
      </div>
    </section>
  );
}

function ProductRetentionNextOutcome({ rows }) {
  return (
    <article className="ppRetentionChartCard">
      <div className="ppRetentionChartHeader">
        <div>
          <h3>Next purchase outcome</h3>
          <p>First purchase after the initial product purchase.</p>
        </div>
      </div>
      {rows.length ? (
        <div className="ppRetentionOutcomeRows">
          {rows.map((row) => (
            <div className="ppRetentionOutcomeRow" key={row.key}>
              <span>{row.label}</span>
              <div className="ppRetentionOutcomeBar" aria-label={`${row.label}: ${formatRetentionRate(row.sameProductAgainPercent)} same product, ${formatRetentionRate(row.boughtAnotherProductPercent)} another product, ${formatRetentionRate(row.didNotReturnPercent)} did not return`}>
                <i className="ppRetentionOutcomeSame" style={{ width: `${row.sameProductAgainDisplayShare * 100}%` }} />
                <i className="ppRetentionOutcomeOther" style={{ width: `${row.boughtAnotherProductDisplayShare * 100}%` }} />
                <i className="ppRetentionOutcomeNone" style={{ width: `${row.didNotReturnDisplayShare * 100}%` }} />
              </div>
              <strong>{formatRetentionRate(row.sameProductAgainPercent + row.boughtAnotherProductPercent)}</strong>
            </div>
          ))}
          <div className="ppRetentionChartLegend">
            <span><i className="ppRetentionLegendSame" />Same product</span>
            <span><i className="ppRetentionLegendOther" />Another product</span>
            <span><i className="ppRetentionLegendNone" />Did not return</span>
          </div>
        </div>
      ) : (
        <ProductRetentionEmptySlot message="No next-purchase outcome rows are stored yet." />
      )}
    </article>
  );
}

function RetentionLineChart({ chart, series, ariaLabel, className = "", xAxisLabel = "", yAxisLabel = "" }) {
  const gradientIdBase = `ppRetentionLineGradient-${useId().replace(/:/g, "")}`;
  return (
    <div className={`ppRetentionLineChart ${className}`.trim()} role="group" aria-label={ariaLabel}>
      <svg className="ppRetentionLineSvg" viewBox={`0 0 ${chart.width} ${chart.height}`} aria-hidden="true" focusable="false">
        <defs>
          {series.map((item) => (
            <linearGradient id={`${gradientIdBase}-${item.key}`} x1="0" x2="0" y1="0" y2="1" key={item.key}>
              <stop offset="0%" stopColor={item.color || "currentColor"} stopOpacity="0.22" />
              <stop offset="100%" stopColor={item.color || "currentColor"} stopOpacity="0.02" />
            </linearGradient>
          ))}
        </defs>
        {chart.yTicks.map((tick) => (
          <g className="ppRetentionGridLine" key={`grid-${tick.label}`}>
            <line x1={chart.plot.left} x2={chart.plot.right} y1={tick.y} y2={tick.y} />
            <text x={chart.plot.left - 14} y={tick.y + 5} textAnchor="end">{tick.label}</text>
          </g>
        ))}
        <line className="ppRetentionLineAxis" x1={chart.plot.left} x2={chart.plot.right} y1={chart.plot.bottom} y2={chart.plot.bottom} />
        <line className="ppRetentionLineAxis" x1={chart.plot.left} x2={chart.plot.left} y1={chart.plot.top} y2={chart.plot.bottom} />
        {chart.xTicks.map((tick) => (
          <g className="ppRetentionLineXTick" key={`${tick.label}-${tick.x}`}>
            <line x1={tick.x} x2={tick.x} y1={chart.plot.bottom} y2={chart.plot.bottom + 6} />
            <text x={tick.x} y={chart.plot.bottom + chart.xLabelOffset} textAnchor={tick.anchor}>{tick.label}</text>
          </g>
        ))}
        {series.map((item) => chart.areaPaths[item.key] ? (
          <path key={`area-${item.key}`} className={`${item.className} ppRetentionLineArea`} d={chart.areaPaths[item.key]} style={{ fill: `url(#${gradientIdBase}-${item.key})` }} />
        ) : null)}
        {series.map((item) => chart.paths[item.key] ? (
          <path key={`path-${item.key}`} className={`${item.className} ppRetentionLinePath`} d={chart.paths[item.key]} />
        ) : null)}
      </svg>
      {yAxisLabel && <span className="ppRetentionLineAxisTitle ppRetentionLineAxisTitle-y">{yAxisLabel}</span>}
      {xAxisLabel && <span className="ppRetentionLineAxisTitle ppRetentionLineAxisTitle-x">{xAxisLabel}</span>}
      {series.flatMap((item) => (chart.pointsBySeries[item.key] || []).map((point, index) => (
        <RetentionLinePointButton point={point} seriesItem={item} allSeries={series} chart={chart} key={`${item.key}-${point.x}-${point.y}-${index}`} />
      )))}
    </div>
  );
}

function RetentionLinePointButton({ point, seriesItem, allSeries, chart }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);
  if (!point || !chart?.width || !chart?.height) return null;
  const left = `${(point.x / chart.width) * 100}%`;
  const top = `${(point.y / chart.height) * 100}%`;
  const valueLabel = chart.yFormatter(point.value);
  const metricRows = getRetentionLinePointMetricRows(point, allSeries, chart);

  return (
    <button
      type="button"
      className={`${seriesItem.className} ppRetentionLinePoint${open ? " isActive" : ""}`}
      ref={triggerRef}
      style={{ left, top }}
      aria-label={`${seriesItem.label}, ${point.xLabel}: ${valueLabel}`}
      onBlur={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <span aria-hidden="true" />
      <FloatingTablePopover anchorRef={triggerRef} open={open} className="ppRetentionLinePopover" width={292} estimatedHeight={190} placement="top-center">
        <strong>{point.xLabel}</strong>
        <p>{seriesItem.label}: {valueLabel}</p>
        {metricRows.length ? (
          <span className="ppRetentionLinePopoverRows">
            {metricRows.map((row) => (
              <span key={row.label}><b>{row.label}</b><small>{row.value}</small></span>
            ))}
          </span>
        ) : null}
      </FloatingTablePopover>
    </button>
  );
}

function getRetentionLinePointMetricRows(point, series, chart) {
  return series
    .map((item) => {
      if (point.row?.[item.key] == null) return null;
      const value = Number(point.row[item.key]);
      if (!Number.isFinite(value)) return null;
      return { label: item.label, value: chart.yFormatter(value) };
    })
    .filter(Boolean);
}

function ProductRetentionEmptySlot({ message }) {
  return (
    <div className="ppRetentionEmptySlot">
      <EmptyProductDetailState message={message} />
    </div>
  );
}

function getProductRetentionMonthlyCohortRows(cells = []) {
  const byCohortDate = new Map();
  cells
    .filter((cell) => cell.cohortDate && Number(cell.cohortSize || 0) > 0)
    .forEach((cell) => {
      const rows = byCohortDate.get(cell.cohortDate) || [];
      rows.push(cell);
      byCohortDate.set(cell.cohortDate, rows);
    });

  const monthRows = new Map();
  byCohortDate.forEach((cohortCells, cohortDate) => {
    const sortedCells = [...cohortCells].sort((left, right) => left.ageDay - right.ageDay);
    const cohortSize = Math.max(...sortedCells.map((cell) => Number(cell.cohortSize || 0)), 0);
    if (!cohortSize) return;
    const monthKey = cohortDate.slice(0, 7);
    const row = monthRows.get(monthKey) || {
      key: monthKey,
      label: formatRetentionMonthLabel(monthKey),
      cohortSize: 0,
      cells: Array.from({ length: PRODUCT_RETENTION_HEATMAP_MONTHS }, () => ({
        observedSize: 0,
        weightedRate: 0,
        rate: null,
        isObserved: false,
      })),
    };
    row.cohortSize += cohortSize;

    for (let month = 0; month < PRODUCT_RETENTION_HEATMAP_MONTHS; month += 1) {
      const targetAgeDay = month * 30;
      const targetCell = month === 0
        ? sortedCells.find((cell) => cell.ageDay === 0) || sortedCells[0]
        : sortedCells.find((cell) => cell.ageDay === targetAgeDay);
      const rate = month === 0
        ? 1
        : targetCell?.isObserved
          ? targetCell.anyRepeatRate
          : null;
      if (rate == null) continue;
      row.cells[month].observedSize += cohortSize;
      row.cells[month].weightedRate += rate * cohortSize;
      row.cells[month].isObserved = targetCell?.isObserved !== false || month === 0;
    }
    monthRows.set(monthKey, row);
  });

  return Array.from(monthRows.values())
    .sort((left, right) => left.key.localeCompare(right.key))
    .slice(-12)
    .map((row) => ({
      ...row,
      cells: row.cells.map((cell) => ({
        ...cell,
        rate: cell.observedSize ? cell.weightedRate / cell.observedSize : null,
      })),
    }));
}

function getProductRetentionRepeatChart(rows = []) {
  const chartRows = rows
    .filter((row) => Number.isFinite(row.ageDay))
    .map((row) => ({
      x: row.ageDay,
      xLabel: `${formatInteger(row.ageDay)} days`,
      anyRepeatCumulativeRate: row.anyRepeatCumulativeRate,
      sameProductRepeatCumulativeRate: row.sameProductRepeatCumulativeRate,
    }));
  const maxAge = Math.max(180, ...chartRows.map((row) => row.x), 1);
  const maxValue = Math.max(
    ...chartRows.flatMap((row) => [
      row.anyRepeatCumulativeRate,
      row.sameProductRepeatCumulativeRate,
    ]),
    0,
  );
  const chart = buildRetentionLineChartGeometry({
    rows: chartRows,
    seriesKeys: ["anyRepeatCumulativeRate", "sameProductRepeatCumulativeRate"],
    xMin: 0,
    xMax: maxAge,
    xTicks: PRODUCT_RETENTION_REPEAT_CHART_AGE_TICKS.filter((tick) => tick <= maxAge).map((tick) => ({ value: tick, label: String(tick) })),
    yMax: getRetentionRateAxisMax(maxValue),
    yFormatter: formatRetentionRate,
    height: 360,
    plot: { left: 110, right: 958, top: 26, bottom: 270 },
    xLabelOffset: 24,
  });

  return {
    ...chart,
    pointsBySeries: getSampledRetentionRepeatPoints(chart.pointsBySeries),
  };
}

function getSampledRetentionRepeatPoints(pointsBySeries = {}) {
  return Object.fromEntries(
    Object.entries(pointsBySeries).map(([key, points]) => [
      key,
      getSampledRetentionRepeatSeriesPoints(points),
    ]),
  );
}

function getSampledRetentionRepeatSeriesPoints(points = []) {
  const source = Array.isArray(points) ? points : [];
  if (source.length <= 6) return source;

  const targetCount = Math.min(18, Math.max(4, Math.ceil(source.length / 3)));
  const selectedIndexes = new Set([0, source.length - 1]);
  const minimumGap = Math.max(1, Math.floor(source.length / targetCount / 2));
  const candidates = source
    .map((point, index) => {
      if (index === 0 || index === source.length - 1) return null;
      const previousValue = Number(source[index - 1]?.value ?? point.value);
      const currentValue = Number(point.value);
      const nextValue = Number(source[index + 1]?.value ?? point.value);
      const previousDelta = currentValue - previousValue;
      const nextDelta = nextValue - currentValue;
      const jumpScore = Math.max(Math.abs(previousDelta), Math.abs(nextDelta));
      const turnScore = Math.abs(nextDelta - previousDelta);
      const breakoutScore = previousValue <= 0 && currentValue > 0 ? 0.08 : 0;
      return {
        index,
        score: (jumpScore * 10) + (turnScore * 6) + breakoutScore,
      };
    })
    .filter(Boolean)
    .sort((left, right) => right.score - left.score);

  candidates.forEach((candidate) => {
    if (selectedIndexes.size >= targetCount) return;
    const hasNearbySelection = Array.from(selectedIndexes).some((index) => Math.abs(index - candidate.index) < minimumGap);
    if (!hasNearbySelection || candidate.score > 0.08) {
      selectedIndexes.add(candidate.index);
    }
  });

  for (let step = 1; selectedIndexes.size < targetCount && step < targetCount - 1; step += 1) {
    selectedIndexes.add(Math.round((step * (source.length - 1)) / (targetCount - 1)));
  }

  return Array.from(selectedIndexes)
    .sort((left, right) => left - right)
    .map((index) => source[index]);
}

function getProductRetentionLtvBreakdownChart(rows = []) {
  const sourceRows = (Array.isArray(rows) ? rows : [])
    .filter((row) => Number.isFinite(row.ageDay))
    .map((row) => ({
      ageDay: normalizeRetentionCount(row.ageDay),
      totalCents: normalizeRetentionCents(row.cumulativeLtvCents),
      sameProductTotalCents: normalizeRetentionCents(row.sameProductLtvCents),
      otherProductCents: normalizeRetentionCents(row.otherProductLtvCents),
    }))
    .filter((row) => row.ageDay >= 0)
    .sort((left, right) => left.ageDay - right.ageDay);
  const initialProductBaseCents = sourceRows.find((row) => row.sameProductTotalCents > 0)?.sameProductTotalCents || 0;
  const chartRows = sourceRows.map((row) => {
    const totalCents = Math.max(0, row.totalCents);
    const sameProductTotalCents = clampNumber(row.sameProductTotalCents, 0, totalCents);
    const initialProductCents = clampNumber(Math.min(initialProductBaseCents, sameProductTotalCents, totalCents), 0, totalCents);
    const otherProductCents = clampNumber(row.otherProductCents, 0, Math.max(0, totalCents - initialProductCents));
    const sameProductRepeatCents = Math.max(0, totalCents - initialProductCents - otherProductCents);
    return {
      ...row,
      x: row.ageDay,
      xLabel: `${formatInteger(row.ageDay)} days`,
      totalCents,
      initialProductCents,
      otherProductCents,
      sameProductRepeatCents,
    };
  });
  const fallbackContribution = {
    ageDay: 0,
    totalCents: 0,
    initialProductCents: 0,
    otherProductCents: 0,
    sameProductRepeatCents: 0,
  };
  const contribution = [...chartRows].reverse().find((row) => row.totalCents > 0) || chartRows[chartRows.length - 1] || fallbackContribution;

  return {
    hasData: chartRows.some((row) => row.totalCents > 0),
    rows: chartRows,
    maxAge: Math.max(180, ...chartRows.map((row) => row.ageDay), 1),
    maxTotalCents: Math.max(...chartRows.map((row) => row.totalCents), 0),
    contribution,
  };
}

function getProductRetentionLtvBreakdownView(chart, mode = "cumulative") {
  const width = 1000;
  const height = 360;
  const plot = { left: 76, right: 968, top: 24, bottom: 288 };
  const xLabelOffset = 24;
  const isShareMode = mode === "share";
  const includeInitial = isShareMode;
  const maxDisplayedCents = includeInitial
    ? chart.maxTotalCents
    : Math.max(...(chart.rows || []).map((row) => (
      Number(row.otherProductCents || 0) + Number(row.sameProductRepeatCents || 0)
    )), 0);
  const yMax = isShareMode ? 1 : getRetentionMoneyAxisMax(maxDisplayedCents);
  const xMin = 0;
  const xMax = Math.max(Number(chart.maxAge || 0), 1);
  const getX = (value) => plot.left + ((Number(value || 0) - xMin) / Math.max(xMax - xMin, 1)) * (plot.right - plot.left);
  const getY = (value) => plot.bottom - (Number(value || 0) / Math.max(yMax, 1)) * (plot.bottom - plot.top);
  const valueForMode = (cents, totalCents) => {
    if (!isShareMode) return Number(cents || 0);
    return totalCents ? Number(cents || 0) / totalCents : 0;
  };
  const chartRows = (chart.rows || []).map((row) => {
    const displayTotalCents = includeInitial
      ? row.totalCents
      : Math.max(0, Number(row.otherProductCents || 0) + Number(row.sameProductRepeatCents || 0));
    const initialValue = includeInitial ? valueForMode(row.initialProductCents, row.totalCents) : 0;
    const otherValue = valueForMode(row.otherProductCents, row.totalCents);
    const sameValue = valueForMode(row.sameProductRepeatCents, row.totalCents);
    const totalValue = isShareMode && row.totalCents > 0 ? 1 : Number(displayTotalCents || 0);
    const initialTopValue = initialValue;
    const otherTopValue = initialValue + otherValue;
    const sameTopValue = isShareMode && row.totalCents > 0 ? 1 : initialValue + otherValue + sameValue;
    const x = Math.round(getX(row.ageDay) * 10) / 10;
    return {
      ...row,
      initialValue,
      otherValue,
      sameValue,
      totalValue,
      displayTotalCents,
      x,
      initialY: Math.round(getY(initialTopValue) * 10) / 10,
      otherY: Math.round(getY(otherTopValue) * 10) / 10,
      sameY: Math.round(getY(sameTopValue) * 10) / 10,
    };
  });
  const initialPoints = chartRows.map((row) => ({ x: row.x, y: row.initialY }));
  const otherPoints = chartRows.map((row) => ({ x: row.x, y: row.otherY }));
  const samePoints = chartRows.map((row) => ({ x: row.x, y: row.sameY }));
  const pointRows = chartRows.filter((row, index) => (
    PRODUCT_RETENTION_LTV_BREAKDOWN_TICKS.includes(row.ageDay)
      || index === chartRows.length - 1
  ));
  const yFormatter = isShareMode ? formatRetentionRate : formatRetentionMoneyCents;
  const valueFormatter = isShareMode
    ? (value, cents) => `${formatRetentionRate(value)} (${formatRetentionMoneyCents(cents)})`
    : (_value, cents) => formatRetentionMoneyCents(cents);
  const yTickValues = isShareMode ? [1, 0.75, 0.5, 0.25, 0] : [yMax, yMax * 0.75, yMax * 0.5, yMax * 0.25, 0];

  return {
    width,
    height,
    plot,
    xLabelOffset,
    mode,
    includeInitial,
    xMax,
    yMax,
    yAxisLabel: isShareMode ? "LTV contribution share" : mode === "perCustomer" ? "LTV per customer (USD)" : "Cumulative LTV (USD)",
    totalLabel: includeInitial ? "Total" : "Follow-on total",
    moneyFormatter: formatRetentionMoneyCents,
    valueFormatter,
    yFormatter,
    data: chartRows.map((row) => ({
      ...row,
      xLabel: `${formatInteger(row.ageDay)} days`,
    })),
    yTicks: yTickValues.map((value) => ({
      value,
      y: getY(value),
      label: yFormatter(value),
    })),
    xTicks: PRODUCT_RETENTION_LTV_BREAKDOWN_TICKS.filter((tick) => tick <= xMax).map((tick, index, ticks) => ({
      value: tick,
      x: Math.round(getX(tick) * 10) / 10,
      label: String(tick),
      anchor: index === 0 ? "start" : index === ticks.length - 1 ? "end" : "middle",
    })),
    paths: {
      initial: buildSmoothSvgPath(initialPoints),
      other: buildSmoothSvgPath(otherPoints),
      same: buildSmoothSvgPath(samePoints),
    },
    areaPaths: {
      initial: buildAreaToBaselinePath(initialPoints, plot.bottom),
      other: buildStackedAreaPath(otherPoints, initialPoints),
      same: buildStackedAreaPath(samePoints, otherPoints),
    },
    points: pointRows.map((row) => ({
      ...row,
      y: row.sameY,
    })),
  };
}

function buildAreaToBaselinePath(points = [], baselineY = 0) {
  const source = points.filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  if (!source.length) return "";
  return `${buildSmoothSvgPath(source)} L ${formatRetentionChartNumber(source[source.length - 1].x)} ${baselineY} L ${formatRetentionChartNumber(source[0].x)} ${baselineY} Z`;
}

function buildStackedAreaPath(upperPoints = [], lowerPoints = []) {
  const upper = upperPoints.filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  const lower = lowerPoints.filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  if (!upper.length || !lower.length) return "";
  const lowerPath = [...lower]
    .reverse()
    .map((point) => `L ${formatRetentionChartNumber(point.x)} ${formatRetentionChartNumber(point.y)}`)
    .join(" ");
  return `${buildSmoothSvgPath(upper)} ${lowerPath} Z`;
}

function getProductRetentionTrendChart(rows = []) {
  const trendRows = getProductRetentionTrendRows(rows);
  const chartRows = trendRows.map((row, index) => ({
    x: index,
    xLabel: row.label,
    repeatPurchaseRate90d: row.repeatPurchaseRate90d,
    sameProductRepurchaseRate90d: row.sameProductRepurchaseRate90d,
    crossSellRetentionRate90d: row.crossSellRetentionRate90d,
  }));
  const maxValue = Math.max(
    ...chartRows.flatMap((row) => [
      row.repeatPurchaseRate90d,
      row.sameProductRepurchaseRate90d,
      row.crossSellRetentionRate90d,
    ]),
    0,
  );
  return buildRetentionLineChartGeometry({
    rows: chartRows,
    seriesKeys: ["repeatPurchaseRate90d", "sameProductRepurchaseRate90d", "crossSellRetentionRate90d"],
    xMin: 0,
    xMax: Math.max(chartRows.length - 1, 1),
    xTicks: getRetentionCategoryTicks(trendRows),
    yMax: getRetentionRateAxisMax(maxValue),
    yFormatter: formatRetentionRate,
  });
}

function getProductRetentionTrendRows(rows = []) {
  const matureRows = rows
    .filter((row) => row.isMature90d && row.repeatPurchaseRate90d != null)
    .sort((left, right) => left.date.localeCompare(right.date));
  if (matureRows.length <= 18) {
    return matureRows.map((row) => ({
      key: row.date,
      label: formatRetentionDateShort(row.date),
      cohortSize: row.cohortSize,
      repeatPurchaseRate90d: row.repeatPurchaseRate90d,
      sameProductRepurchaseRate90d: row.sameProductRepurchaseRate90d,
      crossSellRetentionRate90d: row.crossSellRetentionRate90d,
    }));
  }

  const groups = new Map();
  matureRows.forEach((row) => {
    const key = row.date.slice(0, 7);
    const weight = Math.max(1, Number(row.cohortSize || 0));
    const group = groups.get(key) || {
      key,
      label: formatRetentionMonthLabel(key),
      cohortSize: 0,
      repeatWeight: 0,
      sameWeight: 0,
      crossWeight: 0,
      repeatWeighted: 0,
      sameWeighted: 0,
      crossWeighted: 0,
    };
    group.cohortSize += row.cohortSize;
    if (row.repeatPurchaseRate90d != null) {
      group.repeatWeight += weight;
      group.repeatWeighted += row.repeatPurchaseRate90d * weight;
    }
    if (row.sameProductRepurchaseRate90d != null) {
      group.sameWeight += weight;
      group.sameWeighted += row.sameProductRepurchaseRate90d * weight;
    }
    if (row.crossSellRetentionRate90d != null) {
      group.crossWeight += weight;
      group.crossWeighted += row.crossSellRetentionRate90d * weight;
    }
    groups.set(key, group);
  });

  return Array.from(groups.values())
    .sort((left, right) => left.key.localeCompare(right.key))
    .slice(-12)
    .map((group) => ({
      key: group.key,
      label: group.label,
      cohortSize: group.cohortSize,
      repeatPurchaseRate90d: group.repeatWeight ? group.repeatWeighted / group.repeatWeight : null,
      sameProductRepurchaseRate90d: group.sameWeight ? group.sameWeighted / group.sameWeight : null,
      crossSellRetentionRate90d: group.crossWeight ? group.crossWeighted / group.crossWeight : null,
    }));
}

function getProductRetentionOutcomeRows(rows = []) {
  const sourceRows = rows.length > 8 ? groupRetentionOutcomeRowsByMonth(rows) : rows;
  return sourceRows
    .slice(-8)
    .map((row) => {
      const same = normalizeRetentionRate(row.sameProductAgainPercent) || 0;
      const other = normalizeRetentionRate(row.boughtAnotherProductPercent) || 0;
      const none = normalizeRetentionRate(row.didNotReturnPercent) || 0;
      const total = same + other + none;
      const displayScale = total > 1 ? 1 / total : 1;
      return {
        key: row.key || row.date,
        label: row.label || formatRetentionDateShort(row.date),
        sameProductAgainPercent: same,
        boughtAnotherProductPercent: other,
        didNotReturnPercent: none,
        sameProductAgainDisplayShare: same * displayScale,
        boughtAnotherProductDisplayShare: other * displayScale,
        didNotReturnDisplayShare: none * displayScale,
      };
    });
}

function groupRetentionOutcomeRowsByMonth(rows = []) {
  const groups = new Map();
  rows.forEach((row) => {
    const key = row.date.slice(0, 7);
    const group = groups.get(key) || {
      key,
      label: formatRetentionMonthLabel(key),
      count: 0,
      sameProductAgainPercent: 0,
      boughtAnotherProductPercent: 0,
      didNotReturnPercent: 0,
    };
    group.count += 1;
    group.sameProductAgainPercent += normalizeRetentionRate(row.sameProductAgainPercent) || 0;
    group.boughtAnotherProductPercent += normalizeRetentionRate(row.boughtAnotherProductPercent) || 0;
    group.didNotReturnPercent += normalizeRetentionRate(row.didNotReturnPercent) || 0;
    groups.set(key, group);
  });
  return Array.from(groups.values())
    .sort((left, right) => left.key.localeCompare(right.key))
    .map((group) => ({
      ...group,
      sameProductAgainPercent: group.count ? group.sameProductAgainPercent / group.count : 0,
      boughtAnotherProductPercent: group.count ? group.boughtAnotherProductPercent / group.count : 0,
      didNotReturnPercent: group.count ? group.didNotReturnPercent / group.count : 0,
    }));
}

function buildRetentionLineChartGeometry({
  rows,
  seriesKeys,
  xMin,
  xMax,
  xTicks,
  yMax,
  yFormatter,
  height = 330,
  plot = { left: 70, right: 968, top: 28, bottom: 250 },
  xLabelOffset = 24,
}) {
  const safeRows = rows.filter((row) => Number.isFinite(row.x)).sort((left, right) => left.x - right.x);
  const width = 1000;
  const safeXMax = Math.max(Number(xMax || 0), xMin + 1);
  const safeYMax = Math.max(Number(yMax || 0), 1);
  const getX = (value) => plot.left + ((Number(value || 0) - xMin) / Math.max(safeXMax - xMin, 1)) * (plot.right - plot.left);
  const getY = (value) => plot.bottom - (Number(value || 0) / safeYMax) * (plot.bottom - plot.top);
  const paths = {};
  const areaPaths = {};
  const pointsBySeries = {};
  let hasData = false;

  seriesKeys.forEach((key) => {
    const points = safeRows
      .map((row) => {
        if (row[key] == null) return null;
        const value = Number(row[key]);
        if (!Number.isFinite(value)) return null;
        return {
          x: Math.round(getX(row.x) * 10) / 10,
          y: Math.round(getY(value) * 10) / 10,
          value,
          xValue: row.x,
          xLabel: row.xLabel || row.label || String(row.x),
          row,
        };
      })
      .filter(Boolean);
    if (points.length) hasData = true;
    paths[key] = points.length ? buildSmoothSvgPath(points) : "";
    areaPaths[key] = points.length > 1
      ? `${paths[key]} L ${formatRetentionChartNumber(points[points.length - 1].x)} ${plot.bottom} L ${formatRetentionChartNumber(points[0].x)} ${plot.bottom} Z`
      : "";
    pointsBySeries[key] = points;
  });

  const yTickValues = [safeYMax, safeYMax * 0.75, safeYMax * 0.5, safeYMax * 0.25, 0];
  return {
    width,
    height,
    plot,
    hasData,
    paths,
    areaPaths,
    pointsBySeries,
    yFormatter,
    yTicks: yTickValues.map((value) => ({
      y: getY(value),
      label: yFormatter(value),
    })),
    xTicks: xTicks.map((tick, index) => ({
      x: Math.round(getX(tick.value) * 10) / 10,
      label: tick.label,
      anchor: index === 0 ? "start" : index === xTicks.length - 1 ? "end" : "middle",
    })),
    xLabelOffset,
  };
}

function getRetentionCategoryTicks(rows = []) {
  if (!rows.length) return [];
  if (rows.length === 1) return [{ value: 0, label: rows[0].label }];
  const indexes = Array.from(new Set([0, Math.floor((rows.length - 1) / 2), rows.length - 1]));
  return indexes.map((index) => ({ value: index, label: rows[index].label }));
}

function getRetentionRateAxisMax(value) {
  const maxValue = Number(value || 0);
  if (maxValue <= 0) return 0.1;
  return Math.min(1, Math.max(0.1, Math.ceil(maxValue * 20) / 20));
}

function getRetentionMoneyAxisMax(value) {
  const maxValue = Math.max(0, Number(value || 0));
  if (maxValue <= 0) return 100;
  if (maxValue <= 1000) return Math.ceil(maxValue / 100) * 100;
  if (maxValue <= 10000) return Math.ceil(maxValue / 1000) * 1000;
  return Math.ceil(maxValue / 5000) * 5000;
}

function formatRetentionRate(value, fallback = "N/A") {
  const rate = normalizeRetentionRate(value);
  return rate == null ? fallback : formatPercent(rate * 100);
}

function formatRetentionDays(value) {
  const number = toNullableFiniteNumber(value);
  if (number == null) return "N/A";
  const days = Math.round(number);
  return `${formatInteger(days)} day${days === 1 ? "" : "s"}`;
}

function formatRetentionMoneyCents(value) {
  return formatMoney(normalizeRetentionCents(value) / 100);
}

function formatRetentionMonthLabel(monthKey = "") {
  const [year, month] = String(monthKey || "").split("-").map((part) => Number(part));
  if (!year || !month) return monthKey || "Cohort";
  return new Intl.DateTimeFormat("en-US", { month: "short" }).format(new Date(Date.UTC(year, month - 1, 1)));
}

function formatRetentionDateShort(value = "") {
  if (!value) return "";
  const date = new Date(String(value).includes("T") ? value : `${value}T00:00:00`);
  if (Number.isNaN(date.getTime())) return String(value);
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(date);
}

function formatRetentionChartNumber(value) {
  return Math.round(Number(value || 0) * 10) / 10;
}

function humanizeRetentionLabel(value = "") {
  const normalized = String(value || "").replace(/_/g, " ").trim();
  if (!normalized) return "Unknown";
  return normalized.charAt(0).toUpperCase() + normalized.slice(1);
}

function getProductRetentionRangeLabel(run = null, summary = {}) {
  const start = run?.windowStartDate || summary.earliestOrderDate;
  const end = run?.windowEndDate || summary.latestOrderDate;
  if (!start || !end) return "";
  return `${formatProductAnalysisDate(start)} - ${formatProductAnalysisDate(end)}`;
}

// eslint-disable-next-line no-unused-vars
function getProductRetentionWarningLabel(summary = {}, run = null) {
  if (run?.status === "failed") return "Calculation failed";
  if (summary.errorMessage) return "Calculation failed";
  if (summary.lowSampleWarning) return "Low sample";
  if (!summary.hasEnoughData) return "Partial data";
  return "";
}

function getProductRetentionEmptyMessage(summary = {}, run = null) {
  const errorMessage = firstNonEmptyString(summary.errorMessage, run?.errorMessage);
  if (errorMessage) {
    return `Product retention calculation failed: ${truncateText(errorMessage, 180)} Re-run Product Diagnosis to calculate retention metrics.`;
  }
  return "No product retention metrics are stored yet. Run Product Diagnosis after Shopify order evidence is available.";
}

function formatProductRetentionStatus(status = "") {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "completed") return "Completed";
  if (normalized === "partial") return "Partial";
  if (normalized === "failed") return "Failed";
  return humanizeRetentionLabel(status);
}

// eslint-disable-next-line no-unused-vars
function getProductRetentionStatusTone(status = "") {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "completed") return "success";
  if (normalized === "failed") return "critical";
  return "warning";
}

function ProductMomentumPanel({ detail }) {
  const [collapsed, setCollapsed] = useProductDetailPanelCollapsed("productMomentum");
  const momentum = detail.productMomentum;
  const panel = buildBetaFeedbackPanel(
    "product.momentum",
    "Sales Momentum",
    buildProductBetaFeedbackContext(detail, {}, {
      momentum: momentum ? {
        score: momentum.score,
        label: momentum.display?.label,
        trendLabel: momentum.display?.trendLabel,
        confidence: momentum.confidence,
        confidenceLabel: momentum.confidenceLabel,
        unitsLast30Days: momentum.inputs?.unitsLast30Days,
        revenueLast30Days: momentum.inputs?.revenueLast30Days,
        components: momentum.components,
      } : {
        available: false,
      },
    }),
    buildProductBetaRelatedEntity(detail),
  );
  if (!momentum) {
    return (
      <BetaFeedbackPanelFrame panel={panel}>
        <section className={`ppProductMomentumPanel${collapsed ? " isCollapsed" : ""}`} aria-label="Sales Momentum">
          <div className="ppProductMomentumHeader">
            <div>
              <span>Commercial signal</span>
              <h2>Sales Momentum</h2>
              <p>Commercial strength is calculated from recent Shopify order velocity, growth and catalog position.</p>
            </div>
            <div className="ppBetaFeedbackHeaderActions">
              <BetaFeedbackPanelControls panel={panel} />
              <ProductDetailPanelCollapseButton
                collapsed={collapsed}
                label="Sales Momentum"
                onToggle={() => setCollapsed((current) => !current)}
              />
            </div>
          </div>
          <ProductDetailPanelCollapseRegion collapsed={collapsed}>
            <EmptyProductDetailState message="Run Product Diagnosis to calculate Sales Momentum for this product." />
          </ProductDetailPanelCollapseRegion>
        </section>
      </BetaFeedbackPanelFrame>
    );
  }

  const componentRows = [
    { key: "velocity", label: "Velocity", value: momentum.components.currentVelocityScore },
    { key: "growth", label: "Growth", value: momentum.components.growthScore },
    { key: "catalog", label: "Catalog share", value: momentum.components.catalogShareScore },
    { key: "trend", label: "Trend consistency", value: momentum.components.trendConsistencyScore },
    { key: "recency", label: "Recency", value: momentum.components.recencyScore },
  ];
  const trendCallout = getProductMomentumTrendInsight(momentum.inputs?.weeklyUnitsLast4Weeks, momentum.display?.trendLabel);

  return (
    <BetaFeedbackPanelFrame panel={panel}>
      <section className={`ppProductMomentumPanel${collapsed ? " isCollapsed" : ""}`} aria-label="Sales Momentum">
        <div className="ppProductMomentumHeader">
          <div>
            <span>Commercial signal</span>
            <h2>Sales Momentum</h2>
            <p>This score answers whether the product matters commercially right now. It is separate from Product Risk.</p>
          </div>
          <div className="ppBetaFeedbackHeaderActions">
            <BetaFeedbackPanelControls panel={panel} />
            <ProductDetailPanelCollapseButton
              collapsed={collapsed}
              label="Sales Momentum"
              onToggle={() => setCollapsed((current) => !current)}
            />
          </div>
        </div>
        <ProductDetailPanelCollapseRegion collapsed={collapsed}>
          <>
            <div className="ppProductMomentumBody">
              <ProductMomentumGauge momentum={momentum} />
              <ProductMomentumWeeklyChart momentum={momentum} />
            </div>
            <div className={`ppProductMomentumTrendCallout ppProductMomentumTrendCallout-${trendCallout.tone}`}>
              <span>
                <ProductMomentumComponentIcon type={trendCallout.icon} />
              </span>
              <strong>{trendCallout.label}</strong>
            </div>
            <div className="ppProductMomentumBreakdown">
              {componentRows.map(({ key, label, value }) => (
                <ProductMomentumComponentMetric
                  componentKey={key}
                  key={key}
                  label={label}
                  momentum={momentum}
                  value={value}
                />
              ))}
            </div>
            <div className="ppProductMomentumMeta">
              <span><b>{momentum.confidenceLabel}</b> · {formatInteger(momentum.confidence)}/100</span>
              <span>{formatInteger(momentum.inputs.unitsLast30Days)} units · {formatMoney(momentum.inputs.revenueLast30Days)} revenue in the last 30 days</span>
            </div>
          </>
        </ProductDetailPanelCollapseRegion>
        <ProductChartAiInterpretation detail={detail} chartKey="productMomentum" />
      </section>
    </BetaFeedbackPanelFrame>
  );
}

function ProductMomentumComponentMetric({ componentKey, label, value, momentum }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);
  const help = getProductMomentumComponentHelp(componentKey, momentum);
  return (
    <div className="ppProductMomentumComponent">
      <span className="ppProductMomentumComponentIconWrap">
        <button
          type="button"
          className="ppProductMomentumComponentIconButton"
          ref={triggerRef}
          aria-label={`Explain ${label} momentum component`}
          onBlur={() => setOpen(false)}
          onFocus={() => setOpen(true)}
          onMouseEnter={() => setOpen(true)}
          onMouseLeave={() => setOpen(false)}
        >
          <ProductMomentumComponentIcon type={componentKey} />
        </button>
        <FloatingTablePopover
          anchorRef={triggerRef}
          open={open}
          className="ppProductMomentumComponentPopover"
          width={316}
          estimatedHeight={156}
          placement="top-center"
        >
          <strong>{label}</strong>
          <p>{help.description}</p>
          <small>{help.detail}</small>
        </FloatingTablePopover>
      </span>
      <span>{label}</span>
      <strong>{formatInteger(value)}</strong>
    </div>
  );
}

function getProductMomentumComponentHelp(componentKey, momentum = {}) {
  const inputs = momentum.inputs || {};
  const catalog = momentum.catalog || {};
  const trendInsight = getProductMomentumTrendInsight(inputs.weeklyUnitsLast4Weeks);
  const growthLabel = momentum.display?.growthLabel || formatSignedPercent(Number(momentum.display?.growthPercent || 0));
  const catalogLabel = momentum.display?.catalogPositionLabel || "Catalog baseline pending";
  const helpers = {
    velocity: {
      description: "Measures how strongly this product is selling right now compared with the catalog.",
      detail: `${formatInteger(inputs.unitsLast30Days)} units and ${formatMoney(inputs.revenueLast30Days)} revenue in the last 30 days.`,
    },
    growth: {
      description: "Compares the current 30-day sales window with the previous 30 days.",
      detail: `${growthLabel} vs previous 30 days; ${formatInteger(inputs.unitsPrevious30Days)} previous units.`,
    },
    catalog: {
      description: "Shows whether this product is commercially important relative to other products in the store.",
      detail: `${catalogLabel}${catalog.catalogProductCount ? ` across ${formatInteger(catalog.catalogProductCount)} catalog products` : ""}.`,
    },
    trend: {
      description: "Reads the last four weekly unit buckets for direction and consistency.",
      detail: `${trendInsight.label}; weekly units: ${getProductMomentumWeeklyChartRows(momentum).map((row) => formatInteger(row.value)).join(" / ")}.`,
    },
    recency: {
      description: "Measures whether sales happened recently enough to trust the momentum signal.",
      detail: `${formatInteger(inputs.unitsLast7Days || 0)} units in the last 7 days; ${inputs.lastSaleAt ? `latest sale ${formatProductAnalysisDate(inputs.lastSaleAt)}` : "latest sale date unavailable"}.`,
    },
  };
  return helpers[componentKey] || {
    description: "Sales Momentum component used in the commercial score.",
    detail: "Higher values increase Sales Momentum when the source data is reliable.",
  };
}

function ProductMomentumWeeklyChart({ momentum }) {
  const rows = getProductMomentumWeeklyChartRows(momentum);
  const axisMax = getProductMomentumWeeklyAxisMax(rows.map((row) => row.value));
  const ticks = [axisMax, axisMax * (2 / 3), axisMax * (1 / 3), 0].map((value, index) => ({
    key: `${index}-${value}`,
    value: Math.round(value),
    top: `${100 - ((value / axisMax) * 100)}%`,
  }));

  return (
    <div className="ppProductMomentumWeeklyChart" role="img" aria-label={`Last 4 weekly units sold for ${momentum.tier} Sales Momentum`}>
      <span className="ppProductMomentumWeeklyYAxisTitle">Units sold</span>
      <div className="ppProductMomentumWeeklyYAxis" aria-hidden="true">
        {ticks.map((tick) => <span key={tick.key} style={{ top: tick.top }}>{formatInteger(tick.value)}</span>)}
      </div>
      <div className="ppProductMomentumWeeklyPlot">
        <div className="ppProductMomentumWeeklyGrid" aria-hidden="true">
          {ticks.slice(0, -1).map((tick) => <span key={tick.key} style={{ top: tick.top }} />)}
        </div>
        <div className="ppProductMomentumWeeklyBars">
          {rows.map((row) => (
            <div
              className={`ppProductMomentumWeeklyBarGroup${row.isLatest ? " isLatest" : ""}`}
              key={row.label}
              style={{ "--pp-momentum-weekly-height": `${row.height}%` }}
            >
              <span className="ppProductMomentumWeeklyBarTrack" aria-hidden="true">
                <strong>{formatInteger(row.value)}</strong>
                <span className="ppProductMomentumWeeklyBar" style={{ height: `${row.height}%` }}>
                  {row.isLatest && row.value > 0 ? (
                    <span className="ppProductMomentumWeeklyStar">
                      <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
                        <path d="M12 4.4L14.1 9L19.1 9.6L15.4 13L16.4 18L12 15.4L7.6 18L8.6 13L4.9 9.6L9.9 9L12 4.4Z" fill="currentColor" />
                      </svg>
                    </span>
                  ) : null}
                </span>
              </span>
              <small>{row.label}</small>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function getProductMomentumWeeklyChartRows(momentum = {}) {
  const values = Array.isArray(momentum.inputs?.weeklyUnitsLast4Weeks)
    ? momentum.inputs.weeklyUnitsLast4Weeks.map((value) => Math.max(0, Number(value || 0))).slice(-4)
    : [];
  const normalizedValues = [...Array(Math.max(0, 4 - values.length)).fill(0), ...values].slice(-4);
  const axisMax = getProductMomentumWeeklyAxisMax(normalizedValues);
  return normalizedValues.map((value, index) => ({
    label: ["W-3", "W-2", "W-1", "Now"][index],
    value,
    height: value > 0 ? clampNumber((value / axisMax) * 100, 5, 100) : 0,
    isLatest: index === normalizedValues.length - 1,
  }));
}

function getProductMomentumWeeklyAxisMax(values = []) {
  const maxValue = Math.max(0, ...values.map((value) => Number(value || 0)));
  if (maxValue <= 0) return 1;
  return Math.max(maxValue + 1, Math.ceil(maxValue * 1.1));
}

function ProductMomentumGauge({ momentum }) {
  const score = clampNumber(Number(momentum.score || 0), 0, 100);
  const rotation = -180 + (score * 1.8);
  const getArcPoint = (value, radius) => {
    const angle = ((-180 + value * 1.8) * Math.PI) / 180;
    return {
      x: 260 + Math.cos(angle) * radius,
      y: 276 + Math.sin(angle) * radius,
    };
  };
  const tickMarks = Array.from({ length: 41 }, (_, index) => {
    const value = index * 2.5;
    const isMajor = value % 25 === 0;
    const outer = getArcPoint(value, 202);
    const inner = getArcPoint(value, isMajor ? 168 : 181);
    return (
      <line
        key={value}
        className={isMajor ? "isMajor" : ""}
        x1={inner.x}
        y1={inner.y}
        x2={outer.x}
        y2={outer.y}
      />
    );
  });

  return (
    <div className="ppProductMomentumGauge">
      <div className="ppProductMomentumGaugeScale" aria-hidden="true">
        <svg viewBox="0 0 520 330" preserveAspectRatio="xMidYMid meet">
          <defs>
            <linearGradient id="ppProductMomentumGaugeGradient" x1="0%" y1="100%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#DDE5EF" />
              <stop offset="44%" stopColor="#3B82F6" />
              <stop offset="70%" stopColor="#32C9B7" />
              <stop offset="100%" stopColor="#22C55E" />
            </linearGradient>
            <filter id="ppProductMomentumNeedleShadow" x="-20%" y="-30%" width="140%" height="160%">
              <feDropShadow dx="0" dy="7" stdDeviation="5" floodColor="#0F172A" floodOpacity="0.18" />
            </filter>
          </defs>
          <path className="ppProductMomentumGaugeArc" d="M 58 276 A 202 202 0 0 1 462 276" stroke="url(#ppProductMomentumGaugeGradient)" />
          <g className="ppProductMomentumNeedle" style={{ transform: `rotate(${rotation}deg)`, transformOrigin: "260px 276px" }}>
            <path d="M 260 266 L 456 274 Q 467 276 456 278 L 260 286 Z" filter="url(#ppProductMomentumNeedleShadow)" />
            <circle cx="260" cy="276" r="19" filter="url(#ppProductMomentumNeedleShadow)" />
          </g>
          <g className="ppProductMomentumGaugeTicks">{tickMarks}</g>
        </svg>
        <span className="ppProductMomentumGaugeLabel ppProductMomentumGaugeLabel-0">0</span>
        <span className="ppProductMomentumGaugeLabel ppProductMomentumGaugeLabel-25">25</span>
        <span className="ppProductMomentumGaugeLabel ppProductMomentumGaugeLabel-50">50</span>
        <span className="ppProductMomentumGaugeLabel ppProductMomentumGaugeLabel-75">75</span>
        <span className="ppProductMomentumGaugeLabel ppProductMomentumGaugeLabel-100">100</span>
      </div>
      <div className="ppProductMomentumGaugeCenter">
        <strong>{formatInteger(score)} <small>/ 100</small></strong>
        <span>{momentum.direction}</span>
        <p><b>{momentum.display.growthLabel}</b> vs previous 30 days · <b>{momentum.display.catalogPositionLabel}</b></p>
      </div>
    </div>
  );
}

