function getOrderActivityUnresolvedReturnSeries(months = []) {
  let runningUnresolved = 0;
  return (Array.isArray(months) ? months : []).map((month) => {
    const opened = Math.max(0, Number(month.returnedUnits || month.returnedOrders || 0));
    const explicitResolved = optionalFiniteMetricNumber(month.resolvedReturnUnits, month.returnResolvedUnits, month.resolvedReturns);
    const explicitUnresolved = optionalFiniteMetricNumber(month.unresolvedReturnUnits, month.openReturnUnits, month.pendingReturnUnits, month.unresolvedReturns);
    const resolved = explicitResolved === null
      ? Math.min(Math.max(0, Number(month.refundedUnits || month.refundedOrders || 0)), runningUnresolved + opened)
      : Math.max(0, explicitResolved);
    const value = explicitUnresolved === null
      ? Math.max(0, runningUnresolved + opened - resolved)
      : Math.max(0, explicitUnresolved);
    runningUnresolved = value;
    return {
      key: month.key,
      label: month.label,
      shortLabel: month.shortLabel,
      value,
      opened,
      resolved,
    };
  });
}

function getOrderActivityStackTotal(month = {}, visibleSeries = ORDER_ACTIVITY_DEFAULT_VISIBLE_SERIES) {
  return (visibleSeries.orders ? Math.max(0, Number(month.orders || 0)) : 0)
    + (visibleSeries.returns ? Math.max(0, Number(month.returnedOrders || 0)) : 0)
    + (visibleSeries.refunds ? Math.max(0, Number(month.refundedOrders || 0)) : 0);
}

function getOrderActivitySegmentHeight(value, maxValue) {
  const count = Number(value || 0);
  if (!count) return 0;
  return Math.max(3, Math.min(100, (count / Math.max(Number(maxValue || 1), 1)) * 100));
}

function getOrderActivityAxisMax(value) {
  const max = Math.max(Number(value || 0), 1);
  const magnitude = max <= 10 ? 5 : max <= 50 ? 10 : max <= 100 ? 25 : 50;
  return Math.ceil(max / magnitude) * magnitude;
}

function getOrderActivityAxisTicks(axisMax) {
  const max = Math.max(Number(axisMax || 0), 1);
  return [1, 0.75, 0.5, 0.25, 0].map((ratio) => {
    const value = Math.round(max * ratio);
    return {
      value,
      y: Math.round((100 - (value / max) * 100) * 10) / 10,
    };
  });
}

function getOrderActivityRevenueAxisMax(value) {
  const max = Math.max(Number(value || 0), 1);
  const magnitude = max <= 1500 ? 300 : max <= 5000 ? 1000 : max <= 25000 ? 5000 : 10000;
  return Math.ceil(max / magnitude) * magnitude;
}

function getOrderActivityRevenueAxisTicks(axisMax) {
  const max = Math.max(Number(axisMax || 0), 1);
  return [1, 0.75, 0.5, 0.25, 0].map((ratio) => {
    const value = Math.round(max * ratio);
    return {
      value,
      y: Math.round((100 - (value / max) * 100) * 10) / 10,
    };
  });
}

function getOrderActivityLinePath(months = [], key, axisMax) {
  const count = months.length;
  if (!count) return "";
  const max = Math.max(Number(axisMax || 0), 1);
  const points = months.map((month, index) => {
    const value = Math.max(0, Number(month[key] || 0));
    return {
      x: Math.round((((index + 0.5) / count) * 100) * 10) / 10,
      y: Math.round((100 - (value / max) * 100) * 10) / 10,
    };
  });
  return buildSmoothSvgPath(points);
}

function ReturnPredictionActionImpact({ adjustment = null }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);
  const closeTimerRef = useRef(null);
  const pending = Number(adjustment?.pending || 0);
  const applied = Number(adjustment?.applied || 0);
  const reviewed = Number(adjustment?.reviewed || 0);
  const dismissed = Number(adjustment?.dismissed || 0);
  const total = Number(adjustment?.total || pending + applied + reviewed + dismissed || 0);
  const handled = Number(adjustment?.handled || applied + reviewed + dismissed);
  const shift = Number(adjustment?.adjustmentPoints || 0);
  const direction = shift < 0 ? "improving" : shift > 0 ? "worsening" : "neutral";
  const roundedShift = Math.round(shift * 10) / 10;
  const shiftLabel = `${roundedShift > 0 ? "+" : ""}${roundedShift} ${Math.abs(roundedShift) === 1 ? "point" : "points"}`;
  const handleOpen = () => {
    if (closeTimerRef.current) window.clearTimeout(closeTimerRef.current);
    closeTimerRef.current = null;
    setOpen(true);
  };
  const handleClose = () => {
    if (closeTimerRef.current) window.clearTimeout(closeTimerRef.current);
    closeTimerRef.current = window.setTimeout(() => {
      setOpen(false);
      closeTimerRef.current = null;
    }, 140);
  };

  useEffect(() => () => {
    if (closeTimerRef.current) window.clearTimeout(closeTimerRef.current);
  }, []);

  return (
    <div className={`ppReturnPredictionImpactBadge ppReturnPredictionImpactBadge-${direction}`}>
      <button
        type="button"
        className="ppReturnPredictionImpactTrigger"
        aria-label={`Recommendation impact ${shiftLabel}`}
        ref={triggerRef}
        onBlur={handleClose}
        onFocus={handleOpen}
        onMouseEnter={handleOpen}
        onMouseLeave={handleClose}
      >
        <s-icon type={direction === "improving" ? "check" : direction === "worsening" ? "alert-circle" : "info"} size="small"></s-icon>
        <span>{shiftLabel}</span>
      </button>
      <FloatingTablePopover
        anchorRef={triggerRef}
        open={open}
        className="ppReturnPredictionImpactTooltip"
        width={320}
        estimatedHeight={248}
        placement="top-end"
        onMouseEnter={handleOpen}
        onMouseLeave={handleClose}
      >
        <strong>Recommendation impact</strong>
        <p>
          Applied and reviewed recommendations pull the forecast downward on the next diagnosis refresh.
          They also widen the forecast range slightly because action outcomes are less certain than observed returns.
          Open recommendations do not move the forecast yet; dismissed items are excluded from future action impact.
        </p>
        <span className="ppReturnPredictionImpactShift">
          <b>{shiftLabel}</b>
          <small>modeled return-rate shift</small>
        </span>
        <span className="ppReturnPredictionImpactCounts" aria-label={`${handled} of ${total} recommendations handled`}>
          <span><b>{applied}</b> applied</span>
          <span><b>{reviewed}</b> reviewed</span>
          <span><b>{dismissed}</b> dismissed</span>
          <span><b>{pending}</b> open</span>
        </span>
      </FloatingTablePopover>
    </div>
  );
}

function getMonthlyOrderActivityRangeLabel(months = []) {
  const activeMonths = months.filter((month) => month.orders || month.returnedOrders || month.refundedOrders);
  const range = activeMonths.length ? activeMonths : months;
  const first = range[0];
  const last = range[range.length - 1];
  if (!first || !last) return "";
  if ((first.label || first.key) === (last.label || last.key)) return first.label || first.key;
  return `${first.label || first.key} to ${last.label || last.key}`;
}

