function ProductRiskHistoryPanel({ detail }) {
  const [collapsed, setCollapsed] = useProductDetailPanelCollapsed("productRiskOverTime");
  const gradientId = `ppProductRiskHistoryAreaGradient-${useId().replace(/:/g, "")}`;
  const historyPoints = getProductRiskHistoryPoints(detail);
  const chart = getProductRiskHistoryChart(historyPoints);
  const latest = historyPoints[historyPoints.length - 1] || null;
  const previous = historyPoints.length > 1 ? historyPoints[historyPoints.length - 2] : null;
  const currentRisk = latest ? latest.riskScore : Number(detail.riskScore || 0);
  const trendTone = getTrendTone(historyPoints.map((point) => point.riskScore), currentRisk);
  const change = latest && previous ? latest.riskScore - previous.riskScore : 0;
  const hasSavedHistory = historyPoints.some((point) => point.kind === "history");
  const changeLabel = getProductRiskHistoryChangeLabel(change, hasSavedHistory);
  const windowLabel = getProductRiskHistoryWindowLabel(historyPoints, hasSavedHistory);
  const statCards = getProductRiskHistoryStatCards(detail, historyPoints, change, changeLabel, windowLabel);
  const milestones = getProductRiskHistoryMilestones(detail, historyPoints, chart.points, chart);
  const footerCards = getProductRiskHistoryFooterCards(historyPoints, changeLabel, windowLabel, milestones);
  const panel = buildBetaFeedbackPanel(
    "product.riskHistory",
    "Product risk over time",
    buildProductBetaFeedbackContext(detail, {}, {
      chart: {
        kind: "riskHistory",
        pointCount: historyPoints.length,
        currentRisk,
        change,
        changeLabel,
        windowLabel,
        hasSavedHistory,
      },
    }),
    buildProductBetaRelatedEntity(detail),
  );

  return (
    <BetaFeedbackPanelFrame panel={panel}>
      <section className={`ppProductRiskHistoryPanel ppProductRiskHistoryPanel-${trendTone}${collapsed ? " isCollapsed" : ""}`} aria-label="Product risk over time">
      <div className="ppProductRiskHistoryHeader">
        <div className="ppProductRiskHistoryTitleBlock">
          <div>
            <span>Diagnosis history</span>
            <h2>Product risk over time</h2>
            <p>Saved ProductPulse risk scores, signal changes and diagnosis milestones for this product.</p>
          </div>
        </div>
        <div className="ppBetaFeedbackHeaderActions">
          <BetaFeedbackPanelControls panel={panel} />
          <ProductDetailPanelCollapseButton
            collapsed={collapsed}
            label="Product risk over time"
            onToggle={() => setCollapsed((current) => !current)}
          />
        </div>
      </div>
      <ProductDetailPanelCollapseRegion collapsed={collapsed}>
        <>
          <div className="ppProductRiskHistoryStats" aria-label="Product risk history summary">
            {statCards.map((card) => (
              <ProductRiskHistoryStatCard card={card} key={card.id} />
            ))}
          </div>
          <div className="ppProductRiskHistoryChart" aria-label="Product risk history chart">
            <svg viewBox={`0 0 ${chart.width} ${chart.height}`} role="img" aria-label={changeLabel}>
              <defs>
                <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
                  <stop offset="0%" stopColor="currentColor" stopOpacity="0.24" />
                  <stop offset="100%" stopColor="currentColor" stopOpacity="0.02" />
                </linearGradient>
              </defs>
              {chart.yTicks.map((tick) => (
                <g className="ppProductRiskHistoryGridLine" key={tick.value}>
                  <line x1={chart.plot.left} x2={chart.plot.right} y1={tick.y} y2={tick.y} />
                  <text x={chart.plot.left - 16} y={tick.y + 5} textAnchor="end">{tick.label}</text>
                </g>
              ))}
              <line className="ppProductRiskHistoryAxis" x1={chart.plot.left} x2={chart.plot.right} y1={chart.plot.bottom} y2={chart.plot.bottom} />
              <line className="ppProductRiskHistoryAxis" x1={chart.plot.left} x2={chart.plot.left} y1={chart.plot.top} y2={chart.plot.bottom} />
              <g className="ppProductRiskHistoryReference">
                <line x1={chart.plot.left} x2={chart.plot.right} y1={chart.reference.y} y2={chart.reference.y} />
                <text x={chart.plot.left + 10} y={chart.reference.y - 10}>{chart.reference.label}</text>
              </g>
              {chart.xTicks.map((tick) => (
                <g className="ppProductRiskHistoryXTick" key={`${tick.label}-${tick.x}`}>
                  <line x1={tick.x} x2={tick.x} y1={chart.plot.bottom} y2={chart.plot.bottom + 6} />
                  <text x={tick.x} y={chart.plot.bottom + 28} textAnchor={tick.anchor}>{tick.label}</text>
                </g>
              ))}
              <path className="ppProductRiskHistoryArea" d={chart.areaPath} style={{ fill: `url(#${gradientId})` }} />
              <path className="ppProductRiskHistoryLine" d={chart.linePath} />
            </svg>
            {chart.points.map((point, index) => (
              <ProductRiskHistoryPointButton
                key={historyPoints[index]?.id || historyPoints[index]?.recordedAt || `${historyPoints[index]?.label}-${index}`}
                point={historyPoints[index]}
                previousPoint={index > 0 ? historyPoints[index - 1] : null}
                chartPoint={point}
                chart={chart}
              />
            ))}
            {milestones.map((milestone) => (
              <ProductRiskHistoryMilestoneLabel milestone={milestone} key={milestone.id} chart={chart} />
            ))}
          </div>
          <div className="ppProductRiskHistoryMeta">
            {footerCards.map((card) => (
              <ProductRiskHistoryMetaCard card={card} key={card.id} />
            ))}
          </div>
        </>
      </ProductDetailPanelCollapseRegion>
      <ProductChartAiInterpretation detail={detail} chartKey="productRiskOverTime" />
      </section>
    </BetaFeedbackPanelFrame>
  );
}

function ProductRiskHistoryStatCard({ card }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);
  const title = String(card?.label || "");
  const value = String(card?.value || "");
  const detail = String(card?.detail || "");

  return (
    <button
      type="button"
      className={`ppProductRiskHistoryStat ppProductRiskHistoryStat-${card.tone}`}
      ref={triggerRef}
      aria-label={`${title}: ${value}. ${detail}`}
      onBlur={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <span aria-hidden="true">
        <s-icon type={card.icon} size="small"></s-icon>
      </span>
      <div>
        <small>{card.label}</small>
        <strong>{card.value}</strong>
        <em>{card.detail}</em>
      </div>
      <ProductRiskHistoryCardPopover anchorRef={triggerRef} open={open} title={card.label} value={card.value} detail={card.detail} />
    </button>
  );
}

function ProductRiskHistoryMetaCard({ card }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);
  const title = String(card?.title || "");
  const detail = String(card?.detail || "");

  return (
    <button
      type="button"
      className={`ppProductRiskHistoryMetaCard ppProductRiskHistoryMetaCard-${card.tone}`}
      ref={triggerRef}
      aria-label={`${title}: ${detail}`}
      onBlur={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <span aria-hidden="true">
        <s-icon type={card.icon} size="small"></s-icon>
      </span>
      <span>
        <strong>{card.title}</strong>
        <small>{card.detail}</small>
      </span>
      <ProductRiskHistoryCardPopover anchorRef={triggerRef} open={open} title={card.title} detail={card.detail} />
    </button>
  );
}

function ProductRiskHistoryCardPopover({ anchorRef, open, title, value, detail }) {
  return (
    <FloatingTablePopover anchorRef={anchorRef} open={open} className="ppProductRiskHistoryPopover ppProductRiskHistoryCardPopover" width={270} estimatedHeight={120} placement="top-center">
      <strong>{title}</strong>
      {value ? <p>{value}</p> : null}
      {detail ? <small>{detail}</small> : null}
    </FloatingTablePopover>
  );
}

function ProductRiskHistoryPointButton({ point, previousPoint, chartPoint, chart }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);
  if (!point || !chartPoint || !chart?.width || !chart?.height) return null;
  const pointEvents = getProductRiskHistoryPointEvents(point, previousPoint);
  const eventRows = pointEvents
    .filter((event) => !event.scoreOnly && event.detail)
    .slice(0, 3)
    .map((event) => ({ label: event.title, value: event.detail }));
  const metricRows = getProductRiskHistoryPointMetricRows(point);
  const left = `${(chartPoint.x / chart.width) * 100}%`;
  const top = `${(chartPoint.y / chart.height) * 100}%`;
  const label = `${point.label}: product risk ${formatInteger(point.riskScore)} of 100`;

  return (
    <button
      type="button"
      className={`ppProductRiskHistoryPoint ppProductRiskHistoryPoint-${pointEvents[0]?.tone || "red"}${open ? " isActive" : ""}`}
      ref={triggerRef}
      style={{ left, top }}
      aria-label={label}
      onBlur={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <span aria-hidden="true" />
      <FloatingTablePopover anchorRef={triggerRef} open={open} className="ppProductRiskHistoryPopover" width={292} estimatedHeight={220} placement="top-center">
        <strong>{point.label}</strong>
        <p>{pointEvents[0]?.title || point.primaryIssue || point.source || "Saved ProductPulse score"}</p>
        <span className="ppProductRiskHistoryPopoverScore">
          <b>{formatInteger(point.riskScore)} / 100</b>
          <small>{point.source}</small>
        </span>
        {eventRows.length ? (
          <span className="ppProductRiskHistoryPopoverRows ppProductRiskHistoryPopoverEventRows">
            {eventRows.map((row) => (
              <span key={row.label}><b>{row.label}</b><small>{row.value}</small></span>
            ))}
          </span>
        ) : null}
        {metricRows.length ? (
          <span className="ppProductRiskHistoryPopoverRows">
            {metricRows.map((row) => (
              <span key={row.label}><b>{row.label}</b><small>{row.value}</small></span>
            ))}
          </span>
        ) : null}
      </FloatingTablePopover>
    </button>
  );
}

function ProductRiskHistoryMilestoneLabel({ milestone, chart }) {
  if (!milestone) return null;
  const chartHeight = Number(chart?.height || 330);
  const plotBottom = Number(chart?.plot?.bottom || 250);
  const ruleTop = 6;
  const ruleBottom = Math.min(88, Math.max(ruleTop + 20, (plotBottom / chartHeight) * 100));
  return (
    <>
      <span
        className={`ppProductRiskHistoryMilestoneRule ppProductRiskHistoryMilestoneRule-${milestone.tone}`}
        style={{
          left: `${milestone.xPercent}%`,
          top: `${ruleTop}%`,
          height: `${ruleBottom - ruleTop}%`,
        }}
        aria-hidden="true"
      />
      <div
        className={`ppProductRiskHistoryMilestone ppProductRiskHistoryMilestone-${milestone.align} ppProductRiskHistoryMilestone-${milestone.tone}`}
        style={{ left: `${milestone.xPercent}%`, top: `${milestone.topPercent}%` }}
      >
        <small>{milestone.label}</small>
        <strong>{milestone.title}</strong>
      </div>
    </>
  );
}

function getProductRiskHistoryPoints(detail = {}) {
  const savedHistory = (Array.isArray(detail.riskHistory) ? detail.riskHistory : [])
    .map((entry, index) => {
      const riskScore = Number(entry.riskScore);
      if (!Number.isFinite(riskScore)) return null;
      return {
        kind: "history",
        riskScore: Math.max(0, Math.min(100, Math.round(riskScore))),
        label: entry.recordedAt ? formatProductAnalysisDate(entry.recordedAt) : `Analysis ${index + 1}`,
        source: getProductRiskHistorySourceLabel(entry.source),
        recordedAt: entry.recordedAt || null,
        primaryIssue: entry.primaryIssue || "",
        confidence: optionalFiniteMetricNumber(entry.confidence),
        returnRate: optionalFiniteMetricNumber(entry.returnRate),
        refundRate: optionalFiniteMetricNumber(entry.refundRate),
        negativeReviewRate: optionalFiniteMetricNumber(entry.negativeReviewRate),
        returnUnits: optionalFiniteMetricNumber(entry.returnUnits),
        refundUnits: optionalFiniteMetricNumber(entry.refundUnits),
        negativeReviewCount: optionalFiniteMetricNumber(entry.negativeReviewCount),
        reviewCount: optionalFiniteMetricNumber(entry.reviewCount),
        avgRating: optionalFiniteMetricNumber(entry.avgRating),
        refundAmount: optionalFiniteMetricNumber(entry.refundAmount),
        signalCount: optionalFiniteMetricNumber(entry.signalCount),
        sourceCount: optionalFiniteMetricNumber(entry.sourceCount),
      };
    })
    .filter(Boolean);

  if (savedHistory.length) return savedHistory;

  const trendValues = (Array.isArray(detail.riskTrend) ? detail.riskTrend : [])
    .map(Number)
    .filter((value) => Number.isFinite(value));
  if (trendValues.length) {
    return trendValues.map((value, index) => ({
      kind: "trend",
      riskScore: Math.max(0, Math.min(100, Math.round(value))),
      label: index === trendValues.length - 1 ? "Current" : `Point ${index + 1}`,
      source: "Stored risk trend",
      recordedAt: null,
      primaryIssue: "",
    }));
  }

  if (Number.isFinite(Number(detail.riskScore))) {
    return [{
      kind: "current",
      riskScore: Math.max(0, Math.min(100, Math.round(Number(detail.riskScore)))),
      label: "Current",
      source: "Current snapshot",
      recordedAt: null,
      primaryIssue: "",
    }];
  }

  return [];
}

function getProductRiskHistoryChart(historyPoints = []) {
  const values = historyPoints.map((point) => point.riskScore);
  const width = 1000;
  const height = 330;
  const plot = { left: 56, right: 972, top: 26, bottom: 250 };
  const emptyChart = {
    width,
    height,
    plot,
    hasDatedRange: false,
    minTime: null,
    maxTime: null,
    linePath: "",
    areaPath: "",
    points: [],
    yTicks: [100, 75, 50, 25, 0].map((value) => ({
      value,
      label: formatInteger(value),
      y: getProductRiskHistoryY(value, plot),
    })),
    xTicks: [],
    reference: { value: 55, label: "Medium risk 55", y: getProductRiskHistoryY(55, plot) },
  };
  if (!values.length) return emptyChart;

  const timeValues = historyPoints.map((point) => new Date(point.recordedAt || "").getTime());
  const hasDatedRange = timeValues.filter((time) => Number.isFinite(time)).length >= 2
    && Math.max(...timeValues.filter((time) => Number.isFinite(time))) > Math.min(...timeValues.filter((time) => Number.isFinite(time)));
  const minTime = hasDatedRange ? Math.min(...timeValues.filter((time) => Number.isFinite(time))) : 0;
  const maxTime = hasDatedRange ? Math.max(...timeValues.filter((time) => Number.isFinite(time))) : 0;
  const points = values.map((value, index) => {
    const rawTime = timeValues[index];
    const xRatio = hasDatedRange && Number.isFinite(rawTime)
      ? (rawTime - minTime) / Math.max(1, maxTime - minTime)
      : values.length === 1
        ? 0.5
        : index / (values.length - 1);
    return {
      x: Math.round((plot.left + xRatio * (plot.right - plot.left)) * 10) / 10,
      y: getProductRiskHistoryY(value, plot),
      value,
    };
  });
  const linePath = buildSmoothSvgPath(points);
  const first = points[0];
  const last = points[points.length - 1];
  const areaPath = points.length
    ? `${linePath} L ${last.x},${plot.bottom} L ${first.x},${plot.bottom} Z`
    : "";
  const xTicks = hasDatedRange
    ? getProductRiskHistoryDateTicks({ minTime, maxTime, plot, points, historyPoints })
    : getProductRiskHistoryIndexedTicks(historyPoints, points, plot);
  return {
    ...emptyChart,
    linePath,
    areaPath,
    points,
    xTicks,
    hasDatedRange,
    minTime: hasDatedRange ? minTime : null,
    maxTime: hasDatedRange ? maxTime : null,
  };
}

function getProductRiskHistoryY(value, plot) {
  const score = Math.max(0, Math.min(100, Number(value) || 0));
  return Math.round((plot.top + ((100 - score) / 100) * (plot.bottom - plot.top)) * 10) / 10;
}

function getProductRiskHistoryIndexedTicks(historyPoints = [], points = [], plot) {
  const xTickIndexes = getProductRiskHistoryTickIndexes(historyPoints.length);
  return xTickIndexes.map((index) => ({
    x: points[index]?.x || plot.left,
    label: getProductRiskHistoryTickLabel(historyPoints[index], index),
    anchor: index === 0 ? "start" : index === historyPoints.length - 1 ? "end" : "middle",
  }));
}

function getProductRiskHistoryDateTicks({ minTime, maxTime, plot, points = [], historyPoints = [] }) {
  const firstPoint = historyPoints[0] || null;
  const lastPoint = historyPoints[historyPoints.length - 1] || null;
  const monthTicks = getProductRiskHistoryBiMonthlyTicks(minTime, maxTime);
  const tickTimes = uniqueSortedNumbers([minTime, ...monthTicks, maxTime]);
  if (tickTimes.length <= 2 && historyPoints.length > 2) {
    return getProductRiskHistoryIndexedTicks(historyPoints, points, plot);
  }
  return tickTimes.map((time, index) => {
    const xRatio = (time - minTime) / Math.max(1, maxTime - minTime);
    return {
      x: Math.round((plot.left + xRatio * (plot.right - plot.left)) * 10) / 10,
      label: getProductRiskHistoryMonthTickLabel(time, index === 0 ? firstPoint : index === tickTimes.length - 1 ? lastPoint : null),
      anchor: index === 0 ? "start" : index === tickTimes.length - 1 ? "end" : "middle",
    };
  });
}

function getProductRiskHistoryBiMonthlyTicks(minTime, maxTime) {
  const start = new Date(minTime);
  const end = new Date(maxTime);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) return [];
  const cursor = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), 1));
  if (cursor.getTime() <= minTime) cursor.setUTCMonth(cursor.getUTCMonth() + 2);
  const ticks = [];
  while (cursor.getTime() < maxTime) {
    ticks.push(cursor.getTime());
    cursor.setUTCMonth(cursor.getUTCMonth() + 2);
  }
  return ticks;
}

function getProductRiskHistoryMonthTickLabel(time, point = null) {
  if (point?.recordedAt) return getProductRiskHistoryTickLabel(point);
  const date = new Date(time);
  if (!Number.isNaN(date.getTime())) {
    return date.toLocaleDateString("en-US", { month: "short", year: "2-digit", timeZone: "UTC" });
  }
  return "";
}

function uniqueSortedNumbers(values = []) {
  return Array.from(new Set(values.filter((value) => Number.isFinite(value)).map((value) => Math.round(value)))).sort((left, right) => left - right);
}

function getProductRiskHistoryTickIndexes(length) {
  if (length <= 0) return [];
  if (length === 1) return [0];
  if (length === 2) return [0, 1];
  return Array.from(new Set([0, Math.floor((length - 1) / 2), length - 1]));
}

function getProductRiskHistoryTickLabel(point, index = 0) {
  if (point?.recordedAt) {
    const date = new Date(point.recordedAt);
    if (!Number.isNaN(date.getTime())) {
      return date.toLocaleDateString("en-US", { month: "short", year: "2-digit" });
    }
  }
  return point?.label || `Point ${index + 1}`;
}

function getProductRiskHistoryStatCards(detail = {}, historyPoints = [], change = 0, changeLabel = "", windowLabel = "") {
  const values = historyPoints.map((point) => point.riskScore).filter((value) => Number.isFinite(value));
  const minRisk = values.length ? Math.min(...values) : Number(detail.riskScore || 0);
  const maxRisk = values.length ? Math.max(...values) : Number(detail.riskScore || 0);
  const last = historyPoints[historyPoints.length - 1] || null;
  const first = historyPoints[0] || null;
  const rangeLabel = `${formatInteger(minRisk)} - ${formatInteger(maxRisk)}`;
  return [
    {
      id: "change",
      icon: "chart-line",
      tone: change > 0 ? "red" : change < 0 ? "green" : "blue",
      value: getProductRiskHistoryDeltaValue(change),
      label: "vs last analysis",
      detail: last?.label ? `${formatInteger(last.riskScore)} on ${last.label}` : changeLabel,
    },
    {
      id: "saved-scores",
      icon: "database",
      tone: "purple",
      value: formatInteger(historyPoints.length),
      label: "Saved scores",
      detail: first?.label && last?.label && first.label !== last.label ? `${first.label} - ${last.label}` : windowLabel,
    },
    {
      id: "range",
      icon: "chart-line",
      tone: "orange",
      value: rangeLabel,
      label: "Saved range",
      detail: `Min ${formatInteger(minRisk)} · Max ${formatInteger(maxRisk)}`,
    },
    {
      id: "percentile",
      icon: "profile",
      tone: "red",
      value: getProductRiskHistoryPercentileLabel(detail, last),
      label: "Risk percentile",
      detail: "vs similar products",
    },
  ];
}

function getProductRiskHistoryDeltaValue(change = 0) {
  if (change > 0) return `+${formatInteger(change)} pts`;
  if (change < 0) return `${formatInteger(change)} pts`;
  return "0 pts";
}

function getProductRiskHistoryPercentileLabel(detail = {}, latest = null) {
  const explicit = optionalFiniteMetricNumber(detail.riskPercentile, detail.metrics?.riskPercentile, latest?.riskPercentile);
  const risk = optionalFiniteMetricNumber(latest?.riskScore, detail.riskScore);
  const percentile = explicit ?? Math.max(1, Math.min(99, Math.round(risk || 0)));
  return `${formatInteger(percentile)}th`;
}

function getProductRiskHistoryFooterCards(historyPoints = [], changeLabel = "", windowLabel = "", milestones = []) {
  const first = historyPoints[0] || null;
  const latest = historyPoints[historyPoints.length - 1] || null;
  const largestJump = getProductRiskHistoryLargestJump(historyPoints);
  const longChange = first && latest ? latest.riskScore - first.riskScore : 0;
  const mainMilestone = milestones[0];
  return [
    {
      id: "last-change",
      icon: "chart-line",
      tone: longChange > 0 ? "red" : longChange < 0 ? "green" : "blue",
      title: changeLabel,
      detail: first && latest ? `${formatInteger(first.riskScore)} -> ${formatInteger(latest.riskScore)}` : windowLabel,
    },
    {
      id: "largest-jump",
      icon: "alert-circle",
      tone: largestJump.change > 0 ? "red" : "orange",
      title: mainMilestone?.title || "Largest movement",
      detail: largestJump.label || "Waiting for more saved history",
    },
    {
      id: "trend",
      icon: "chart-line",
      tone: longChange > 0 ? "purple" : longChange < 0 ? "green" : "blue",
      title: getProductRiskHistoryTrendSummary(historyPoints),
      detail: getProductRiskHistoryLongRangeDetail(historyPoints),
    },
    {
      id: "saved",
      icon: "calendar",
      tone: "green",
      title: `${formatInteger(historyPoints.length)} saved score${historyPoints.length === 1 ? "" : "s"}`,
      detail: windowLabel,
    },
  ];
}

function getProductRiskHistoryMilestones(detail = {}, historyPoints = [], chartPoints = [], chart = {}) {
  const timelineMilestones = getProductRiskHistoryTimelineMilestones(detail, chart);
  if (timelineMilestones.length) return timelineMilestones;
  return getProductRiskHistoryEvidenceMilestones(historyPoints, chartPoints);
}

function getProductRiskHistoryEvidenceMilestones(historyPoints = [], chartPoints = []) {
  const candidates = [];
  for (let index = 1; index < historyPoints.length; index += 1) {
    const point = historyPoints[index];
    const previous = historyPoints[index - 1];
    const event = getProductRiskHistoryPointEvents(point, previous).find((item) => !item.scoreOnly) || null;
    if (!event) continue;
    const chartPoint = chartPoints[index];
    if (!chartPoint) continue;
    candidates.push({
      id: `${event.title}-${index}`,
      ...event,
      label: point.label,
      dateKey: getProductRiskHistoryPointDateKey(point, index),
      xPercent: Math.max(12, Math.min(88, (chartPoint.x / 1000) * 100)),
      topPercent: index % 2 === 0 ? 16 : 8,
      align: chartPoint.x > 760 ? "right" : "left",
      pointYPercent: (chartPoint.y / 330) * 100,
      priority: event.priority || 0,
    });
  }
  const selected = [];
  candidates
    .sort((a, b) => b.priority - a.priority)
    .forEach((candidate) => {
      if (selected.length >= 2) return;
      const sameDate = selected.some((item) => item.dateKey && item.dateKey === candidate.dateKey);
      const tooClose = selected.some((item) => Math.abs(item.xPercent - candidate.xPercent) < 14);
      if (sameDate || tooClose) return;
      selected.push(candidate);
    });

  return selected
    .sort((a, b) => a.xPercent - b.xPercent)
    .map((milestone, index) => ({
      ...milestone,
      topPercent: index === 0 ? 8 : 22,
    }));
}

function getProductRiskHistoryTimelineMilestones(detail = {}, chart = {}) {
  if (!chart?.hasDatedRange || !Number.isFinite(chart.minTime) || !Number.isFinite(chart.maxTime)) return [];
  const events = getProductMetricTimelineEventPoints(detail)
    .filter((event) => Number.isFinite(event.time) && event.time >= chart.minTime && event.time <= chart.maxTime)
    .filter((event) => !isProductRiskHistoryRiskOnlyTimelineEvent(event))
    .map((event) => {
      const x = getProductRiskHistoryChartXForTime(chart, event.time);
      return {
        id: `timeline-${event.id || event.eventType || event.time}`,
        title: event.title,
        detail: event.summary || event.source || event.categoryLabel || "Product timeline event",
        label: event.dateLabel || formatProductMetricTimelinePointLabel(new Date(event.time)),
        dateKey: event.dayKey || new Date(event.time).toISOString().slice(0, 10),
        time: event.time,
        xPercent: Math.max(12, Math.min(88, (x / chart.width) * 100)),
        topPercent: 8,
        align: x > chart.width * 0.76 ? "right" : "left",
        tone: getProductRiskHistoryTimelineMilestoneTone(event),
        priority: getProductRiskHistoryTimelineMilestonePriority(event),
      };
    })
    .filter((event) => event.title && Number.isFinite(event.time));

  if (!events.length) return [];

  const preferredSpacing = PRODUCT_RISK_HISTORY_TIMELINE_MILESTONE_MIN_SPACING_DAYS * PRODUCT_METRIC_TIMELINE_DAY_MS;
  const fallbackSpacing = PRODUCT_RISK_HISTORY_TIMELINE_MILESTONE_FALLBACK_SPACING_DAYS * PRODUCT_METRIC_TIMELINE_DAY_MS;
  const targetCount = Math.min(PRODUCT_RISK_HISTORY_TIMELINE_MILESTONE_MAX, events.length);
  let selected = selectProductRiskHistoryTimelineMilestones(events, preferredSpacing);
  if (selected.length < Math.min(3, targetCount)) {
    selected = selectProductRiskHistoryTimelineMilestones(events, fallbackSpacing);
  }

  return selected
    .sort((a, b) => a.time - b.time)
    .slice(0, PRODUCT_RISK_HISTORY_TIMELINE_MILESTONE_MAX)
    .map((milestone, index) => ({
      ...milestone,
      topPercent: index % 2 === 0 ? 8 : 22,
    }));
}

function selectProductRiskHistoryTimelineMilestones(events = [], minSpacingMs = 0) {
  const selected = [];
  [...events]
    .sort((left, right) => right.priority - left.priority || Math.abs(right.xPercent - 50) - Math.abs(left.xPercent - 50))
    .forEach((candidate) => {
      if (selected.length >= PRODUCT_RISK_HISTORY_TIMELINE_MILESTONE_MAX) return;
      const tooClose = selected.some((item) => Math.abs(item.time - candidate.time) < minSpacingMs);
      if (tooClose) return;
      selected.push(candidate);
    });
  return selected;
}

function isProductRiskHistoryRiskOnlyTimelineEvent(event = {}) {
  const category = String(event.category || "").toLowerCase();
  const eventType = String(event.eventType || "").toLowerCase();
  const title = String(event.title || "").toLowerCase();
  const categoryLabel = String(event.categoryLabel || "").toLowerCase();
  if (category === "risk" || categoryLabel === "risk") return true;
  if (eventType.includes("risk_score") || eventType.includes("product_risk") || eventType.includes("risk_level") || eventType.includes("risk_tone")) return true;
  if (title.includes("product risk") || title.includes("risk score")) return true;
  if (/\bmoved to (low|medium|high|critical)\b/.test(title) || /\b(low|medium|high|critical) risk\b/.test(title)) return true;
  return false;
}

function getProductRiskHistoryChartXForTime(chart = {}, time) {
  const minTime = Number(chart.minTime);
  const maxTime = Number(chart.maxTime);
  const width = Number(chart.width || 1000);
  const plot = chart.plot || { left: 56, right: width - 28 };
  if (!Number.isFinite(time) || !Number.isFinite(minTime) || !Number.isFinite(maxTime) || maxTime <= minTime) {
    return plot.left || 0;
  }
  return Math.round(((plot.left || 0) + ((time - minTime) / Math.max(1, maxTime - minTime)) * ((plot.right || width) - (plot.left || 0))) * 10) / 10;
}

function getProductRiskHistoryTimelineMilestonePriority(event = {}) {
  const category = String(event.category || "").toLowerCase();
  const eventType = String(event.eventType || "").toLowerCase();
  const tone = String(event.tone || mapProductTimelineTone(event.severityTone) || "").toLowerCase();
  const categoryWeight = category.includes("risk")
    ? 36
    : category.includes("return") || category.includes("refund") || category.includes("review")
      ? 30
      : category.includes("action")
        ? 22
        : category.includes("diagnosis") || category.includes("watch")
          ? 14
          : category.includes("scan")
            ? 5
            : 10;
  const typeWeight = eventType.includes("increased") || eventType.includes("spike") || eventType.includes("pressure")
    ? 18
    : eventType.includes("applied") || eventType.includes("resolved")
      ? 10
      : 0;
  const toneWeight = tone === "red" ? 24 : tone === "orange" ? 16 : tone === "green" ? 8 : tone === "blue" ? 6 : 0;
  return Number(event.importance || 0) + categoryWeight + typeWeight + toneWeight;
}

function getProductRiskHistoryTimelineMilestoneTone(event = {}) {
  const tone = String(event.tone || mapProductTimelineTone(event.severityTone) || "").toLowerCase();
  if (tone === "green") return "green";
  if (tone === "orange" || tone === "blue" || tone === "violet") return "orange";
  return "red";
}

function getProductRiskHistoryPointEvents(point = {}, previous = null) {
  const events = [];
  const add = (event) => {
    if (event?.title) events.push(event);
  };
  const negativeReviewDelta = getProductRiskHistoryMetricDelta(point, previous, "negativeReviewCount");
  const reviewCountDelta = getProductRiskHistoryMetricDelta(point, previous, "reviewCount");
  if (negativeReviewDelta !== null && negativeReviewDelta >= PRODUCT_RISK_HISTORY_NEGATIVE_REVIEW_MILESTONE_MIN) {
    add({
      title: `${formatInteger(negativeReviewDelta)} new negative review${negativeReviewDelta === 1 ? "" : "s"}`,
      detail: `${formatInteger(previous.negativeReviewCount || 0)} -> ${formatInteger(point.negativeReviewCount || 0)} negative reviews`,
      tone: "orange",
      priority: 118 + Math.min(30, negativeReviewDelta),
    });
  }

  const ratingDelta = getProductRiskHistoryMetricDelta(point, previous, "avgRating");
  const hasMaterialReviewVolume = negativeReviewDelta === null
    ? reviewCountDelta === null || reviewCountDelta >= PRODUCT_RISK_HISTORY_NEGATIVE_REVIEW_MILESTONE_MIN
    : negativeReviewDelta >= PRODUCT_RISK_HISTORY_NEGATIVE_REVIEW_MILESTONE_MIN;
  if (ratingDelta !== null && ratingDelta <= -0.5 && hasMaterialReviewVolume) {
    add({
      title: "Average rating dropped",
      detail: `${formatDecimal(previous.avgRating, 1)} -> ${formatDecimal(point.avgRating, 1)} stars`,
      tone: "red",
      priority: 106 + Math.min(20, Math.abs(ratingDelta) * 10),
    });
  }

  const returnUnitsDelta = getProductRiskHistoryMetricDelta(point, previous, "returnUnits");
  if (returnUnitsDelta !== null && returnUnitsDelta >= PRODUCT_RISK_HISTORY_RETURN_UNIT_MILESTONE_MIN) {
    add({
      title: `${formatInteger(returnUnitsDelta)} returned units added`,
      detail: `${formatInteger(previous.returnUnits || 0)} -> ${formatInteger(point.returnUnits || 0)} returned units`,
      tone: "red",
      priority: 112 + Math.min(30, returnUnitsDelta),
    });
  }

  const returnDelta = getProductRiskHistoryMetricDelta(point, previous, "returnRate");
  const hasReturnUnitData = optionalFiniteMetricNumber(point.returnUnits, previous?.returnUnits) !== null;
  if (
    returnDelta !== null
    && returnDelta >= PRODUCT_RISK_HISTORY_RATE_ONLY_MILESTONE_MIN
    && (!hasReturnUnitData || returnUnitsDelta >= PRODUCT_RISK_HISTORY_RETURN_UNIT_MILESTONE_MIN)
  ) {
    add({
      title: "Return rate spike",
      detail: `${formatPercent(previous.returnRate)} -> ${formatPercent(point.returnRate)}`,
      tone: "red",
      priority: 120 + returnDelta,
    });
  }

  const refundUnitsDelta = getProductRiskHistoryMetricDelta(point, previous, "refundUnits");
  if (refundUnitsDelta !== null && refundUnitsDelta >= PRODUCT_RISK_HISTORY_REFUND_UNIT_MILESTONE_MIN) {
    add({
      title: `${formatInteger(refundUnitsDelta)} refunded units added`,
      detail: `${formatInteger(previous.refundUnits || 0)} -> ${formatInteger(point.refundUnits || 0)} refunded units`,
      tone: "orange",
      priority: 108 + Math.min(26, refundUnitsDelta),
    });
  }

  const refundDelta = getProductRiskHistoryMetricDelta(point, previous, "refundRate");
  const refundAmountDelta = getProductRiskHistoryMetricDelta(point, previous, "refundAmount");
  const hasRefundUnitData = optionalFiniteMetricNumber(point.refundUnits, previous?.refundUnits) !== null;
  if (
    (
      refundDelta !== null
      && refundDelta >= PRODUCT_RISK_HISTORY_RATE_ONLY_MILESTONE_MIN
      && (!hasRefundUnitData || refundUnitsDelta >= PRODUCT_RISK_HISTORY_REFUND_UNIT_MILESTONE_MIN)
    )
    || (
      refundAmountDelta !== null
      && refundAmountDelta >= PRODUCT_RISK_HISTORY_REFUND_AMOUNT_ONLY_MILESTONE_MIN
      && (!hasRefundUnitData || refundUnitsDelta >= PRODUCT_RISK_HISTORY_REFUND_UNIT_MILESTONE_MIN)
    )
  ) {
    add({
      title: "Refund pressure increased",
      detail: refundDelta !== null
        ? `${formatPercent(previous.refundRate)} -> ${formatPercent(point.refundRate)}`
        : `Refund value ${formatMoney(point.refundAmount || 0)}`,
      tone: "orange",
      priority: 110 + Math.max(refundDelta || 0, Math.min(24, (refundAmountDelta || 0) / 10)),
    });
  }

  if (!events.length && point.primaryIssue) {
    add({
      title: point.primaryIssue,
      detail: point.source || "Saved product-risk snapshot",
      tone: "blue",
      priority: 10,
    });
  }

  const riskDelta = previous ? point.riskScore - previous.riskScore : 0;
  if (!events.length && Math.abs(riskDelta) >= 8) {
    add({
      title: "Risk score changed",
      detail: `${formatInteger(previous.riskScore)} -> ${formatInteger(point.riskScore)} (${riskDelta > 0 ? "+" : ""}${formatInteger(riskDelta)} pts). No supporting signal delta was stored for this snapshot.`,
      tone: riskDelta > 0 ? "red" : "green",
      priority: 1,
      scoreOnly: true,
    });
  }

  return events.sort((a, b) => b.priority - a.priority);
}

function getProductRiskHistoryPointDateKey(point = {}, index = 0) {
  if (point.recordedAt) {
    const date = new Date(point.recordedAt);
    if (!Number.isNaN(date.getTime())) return date.toISOString().slice(0, 10);
  }
  return point.label || `point-${index}`;
}

function getProductRiskHistoryMetricDelta(point = {}, previous = {}, key = "") {
  if (!previous) return null;
  const current = optionalFiniteMetricNumber(point[key]);
  const prior = optionalFiniteMetricNumber(previous[key]);
  if (current === null || prior === null) return null;
  return current - prior;
}

function getProductRiskHistoryPointMetricRows(point = {}) {
  return [
    Number.isFinite(Number(point.returnRate)) ? { label: "Return rate", value: formatPercent(point.returnRate) } : null,
    Number.isFinite(Number(point.returnUnits)) ? { label: "Returned units", value: formatInteger(point.returnUnits) } : null,
    Number.isFinite(Number(point.refundRate)) ? { label: "Refund rate", value: formatPercent(point.refundRate) } : null,
    Number.isFinite(Number(point.refundUnits)) ? { label: "Refunded units", value: formatInteger(point.refundUnits) } : null,
    Number.isFinite(Number(point.negativeReviewCount)) ? { label: "Negative reviews", value: formatInteger(point.negativeReviewCount) } : null,
    Number.isFinite(Number(point.reviewCount)) ? { label: "Total reviews", value: formatInteger(point.reviewCount) } : null,
    Number.isFinite(Number(point.avgRating)) ? { label: "Average rating", value: `${formatDecimal(point.avgRating, 1)} / 5` } : null,
    Number.isFinite(Number(point.signalCount)) ? { label: "Evidence signals", value: formatInteger(point.signalCount) } : null,
    Number.isFinite(Number(point.refundAmount)) ? { label: "Refund value", value: formatMoney(point.refundAmount) } : null,
  ].filter(Boolean);
}

function getProductRiskHistoryLargestJump(historyPoints = []) {
  let largest = { change: 0, label: "" };
  for (let index = 1; index < historyPoints.length; index += 1) {
    const current = historyPoints[index];
    const previous = historyPoints[index - 1];
    const change = current.riskScore - previous.riskScore;
    if (Math.abs(change) > Math.abs(largest.change)) {
      largest = {
        change,
        label: `${current.label} · ${change > 0 ? "+" : ""}${formatInteger(change)} pts from previous score`,
      };
    }
  }
  return largest;
}

// eslint-disable-next-line no-unused-vars
function getProductRiskHistoryTrendLabel(historyPoints = []) {
  const first = historyPoints[0];
  const last = historyPoints[historyPoints.length - 1];
  if (!first || !last || first === last) return "No trend";
  const delta = last.riskScore - first.riskScore;
  if (delta >= 5) return "Rising";
  if (delta <= -5) return "Improving";
  return "Stable";
}

function getProductRiskHistoryTrendSummary(historyPoints = []) {
  const first = historyPoints[0];
  const last = historyPoints[historyPoints.length - 1];
  if (!first || !last || first === last) return "Waiting for trend";
  const delta = last.riskScore - first.riskScore;
  if (delta >= 5) return "Consistent uptrend";
  if (delta <= -5) return "Risk improving";
  return "Mostly stable";
}

function getProductRiskHistoryLongRangeDetail(historyPoints = []) {
  const first = historyPoints[0];
  const last = historyPoints[historyPoints.length - 1];
  if (!first || !last || first === last) return "More saved scores needed.";
  const delta = last.riskScore - first.riskScore;
  return `${delta > 0 ? "+" : ""}${formatInteger(delta)} pts across ${formatInteger(historyPoints.length)} saved scores`;
}

function parseSvgPointString(value = "") {
  return String(value || "")
    .trim()
    .split(/\s+/)
    .map((pair) => {
      const [x, y] = pair.split(",").map(Number);
      return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
    })
    .filter(Boolean);
}

function buildSmoothSvgPath(points = []) {
  const source = (Array.isArray(points) ? points : [])
    .map((point) => ({
      x: Number(point.x),
      y: Number(point.y),
    }))
    .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  if (!source.length) return "";
  if (source.length === 1) return `M ${source[0].x},${source[0].y}`;
  if (source.length === 2) return `M ${source[0].x},${source[0].y} L ${source[1].x},${source[1].y}`;

  const commands = [`M ${source[0].x},${source[0].y}`];
  for (let index = 1; index < source.length - 1; index += 1) {
    const current = source[index];
    const next = source[index + 1];
    const midX = Math.round(((current.x + next.x) / 2) * 10) / 10;
    const midY = Math.round(((current.y + next.y) / 2) * 10) / 10;
    commands.push(`Q ${current.x},${current.y} ${midX},${midY}`);
  }
  const last = source[source.length - 1];
  commands.push(`L ${last.x},${last.y}`);
  return commands.join(" ");
}

function getProductRiskHistoryChangeLabel(change, hasSavedHistory) {
  if (!hasSavedHistory) return "Waiting for another saved analysis";
  if (change > 0) return `Up ${Math.abs(change)} pts since last analysis`;
  if (change < 0) return `Down ${Math.abs(change)} pts since last analysis`;
  return "Stable since last analysis";
}

function getProductRiskHistoryWindowLabel(points = [], hasSavedHistory = false) {
  if (!hasSavedHistory) return "Saved history appears after Catalog Scan or Product Diagnosis runs again.";
  const first = points[0];
  const last = points[points.length - 1];
  if (first?.recordedAt && last?.recordedAt && first.recordedAt !== last.recordedAt) {
    return `${points.length} saved scores · ${first.label} to ${last.label}`;
  }
  return `${points.length} saved score${points.length === 1 ? "" : "s"}`;
}

function getProductRiskHistorySourceLabel(source) {
  const normalized = String(source || "").toLowerCase();
  if (normalized.includes("full")) return "Product diagnosis";
  if (normalized.includes("quick")) return "Catalog Scan";
  if (normalized.includes("watch")) return "Watchlist scan";
  return source ? String(source) : "ProductPulse";
}

function announceProductPulseJobs(actionData) {
  if (typeof window === "undefined" || actionData?.status !== "success") return;
  const jobs = [
    ...(Array.isArray(actionData.jobs) ? actionData.jobs : []),
    actionData.job,
  ].filter(Boolean);
  if (!jobs.length) return;
  window.dispatchEvent(new CustomEvent("productpulse:jobs-queued", { detail: { jobs } }));
}

export function AnalyticsScreen({ data }) {
  const location = useLocation();
  const analyticsFetcher = useFetcher();
  const analyticsLoadRef = useRef(analyticsFetcher.load);
  const analyticsDeferred = Boolean(data?.analyticsDeferred);
  const analyticsCacheScope = data?.shop || data?.shopDomain || data?.storeDomain || "";
  const analyticsDataHref = useMemo(() => {
    return `${buildEmbeddedApiPath(location.pathname, "/app/analytics-data")}${location.search || ""}`;
  }, [location.pathname, location.search]);
  const fetchedAnalytics = analyticsFetcher.data?.analytics || null;
  const cachedAnalytics = analyticsDeferred ? getCachedAnalyticsForScope(analyticsCacheScope) : null;
  const analyticsView = data?.analytics || fetchedAnalytics || cachedAnalytics || getAnalyticsPlaceholderData();
  const analyticsHasLoadedData = Boolean(data?.analytics || fetchedAnalytics || cachedAnalytics);
  const analyticsInitialLoading = analyticsDeferred && !analyticsHasLoadedData;
  const analyticsRefreshing = analyticsDeferred && analyticsHasLoadedData && analyticsFetcher.state !== "idle";
  const [businessImpactOpen, setBusinessImpactOpen] = useState(false);
  const [impactBreakdownKey, setImpactBreakdownKey] = useState(analyticsView.impactBreakdown?.defaultKey || "collection");
  const kpis = analyticsView.kpis || [];
  const businessImpact = analyticsView.businessImpact || { title: "Estimated Margin Exposure", subtitle: "", metrics: [] };
  const riskBubbles = analyticsView.riskBubbles || [];
  const impactTrend = analyticsView.impactTrend || { series: [], labels: [] };
  const actionImpactTrend = analyticsView.actionImpactTrend || { series: [], labels: [] };
  const issueImpact = analyticsView.issueImpact || { rows: [] };
  const impactBreakdown = analyticsView.impactBreakdown || { defaultKey: "collection", filters: [] };
  const breakdownFilters = useMemo(() => impactBreakdown.filters || [], [impactBreakdown.filters]);
  const selectedBreakdown = breakdownFilters.find((filter) => filter.key === impactBreakdownKey)
    || breakdownFilters.find((filter) => filter.key === impactBreakdown.defaultKey)
    || breakdownFilters[0]
    || { key: "collection", label: "By collection", rows: [] };
  const actionPerformance = analyticsView.actionPerformance || { rows: [], effectiveness: [] };
  const catalogCoverage = analyticsView.catalogCoverage || { rows: [] };
  const evidenceSourceCoverage = analyticsView.evidenceSourceCoverage || [];
  const topProductsAtRisk = analyticsView.topProductsAtRisk || [];
  const deepDiagnosisCharts = analyticsView.deepDiagnosisCharts || {};

  useEffect(() => {
    analyticsLoadRef.current = analyticsFetcher.load;
  }, [analyticsFetcher.load]);

  useEffect(() => {
    if (!analyticsDeferred || !data?.analytics) return;
    setCachedAnalyticsForScope(analyticsCacheScope, data.analytics);
  }, [analyticsCacheScope, analyticsDeferred, data?.analytics]);

  useEffect(() => {
    if (!analyticsDeferred || !fetchedAnalytics) return;
    setCachedAnalyticsForScope(analyticsCacheScope, fetchedAnalytics);
  }, [analyticsCacheScope, analyticsDeferred, fetchedAnalytics]);

  useEffect(() => {
    if (!analyticsDeferred) return;
    if (data?.analytics || fetchedAnalytics || cachedAnalytics) return;
    analyticsLoadRef.current(analyticsDataHref);
  }, [analyticsDataHref, analyticsDeferred, cachedAnalytics, data?.analytics, fetchedAnalytics]);

  useEffect(() => {
    if (!breakdownFilters.length) return;
    if (breakdownFilters.some((filter) => filter.key === impactBreakdownKey)) return;
    setImpactBreakdownKey(impactBreakdown.defaultKey || breakdownFilters[0]?.key || "collection");
  }, [breakdownFilters, impactBreakdown.defaultKey, impactBreakdownKey]);

  return (
    <FullWidthPage label="Analytics" className="ppAnalyticsPage">
      <ScreenShell className={`ppDashboard ppAnalyticsScreen${analyticsInitialLoading ? " isAnalyticsDataLoading" : ""}${analyticsRefreshing ? " isAnalyticsDataRefreshing" : ""}`}>
        <div className="ppDashboardDataStage" aria-busy={analyticsInitialLoading ? "true" : "false"}>
          <div className={`ppDashboardDataContent${analyticsInitialLoading ? " isBlurred" : ""}`}>
            <div className="ppAnalyticsTopbar">
              <div>
                <h1>Analytics</h1>
                <p>Visualize product quality risk, issue trends and estimated margin exposure.</p>
              </div>
            </div>

            <div className="ppAnalyticsKpis" aria-label="Analytics overview">
              {kpis.map((kpi, index) => (
                <AnalyticsKpiCard key={kpi.label} kpi={kpi} index={index} />
              ))}
            </div>

        <div className="ppAnalyticsDeepChartGrid">
          <AnalyticsRiskMarginTrendPanel chart={deepDiagnosisCharts.riskMarginTrend} />
          <AnalyticsIssueDistributionPanel distribution={deepDiagnosisCharts.issueDistribution} />
        </div>

        <div className="ppAnalyticsActionImpactGrid">
          <AnalyticsActionImpactTrendPanel chart={actionImpactTrend} />
          <AnalyticsSourceCoverageMixPanel mix={deepDiagnosisCharts.sourceCoverageMix} />
        </div>

        <div className="ppAnalyticsChartGrid">
          <AnalyticsPanel title="Risk vs. margin impact" subtitle="X: product risk · Y: estimated margin exposure · Bubble size: revenue at risk" className="ppAnalyticsPanelRiskMargin">
            <RiskRevenueBubbleChart bubbles={riskBubbles} />
          </AnalyticsPanel>

          <AnalyticsPanel title="Estimated Margin Exposure over time" subtitle="Current total vs. reconstructed trend-weighted exposure" className="ppAnalyticsPanelTrend">
            <AnalyticsTrendChart chart={impactTrend} ariaLabel="Estimated Margin Exposure over time" />
          </AnalyticsPanel>

          <AnalyticsPanel title="Issue impact by type" subtitle="Issue types ranked by Estimated Margin Exposure, not just raw signal volume" className="ppAnalyticsPanelIssueImpact">
            <IssueImpactTable rows={issueImpact.rows} />
          </AnalyticsPanel>

          <AnalyticsPanel
            title="Impact breakdown"
            subtitle="Slice margin exposure by Shopify catalog dimensions and evidence source"
            className="ppAnalyticsPanelBreakdown"
          >
            <AnalyticsBreakdownTabs filters={breakdownFilters} selectedKey={selectedBreakdown.key} onChange={setImpactBreakdownKey} />
            <ImpactBreakdownPanel breakdown={selectedBreakdown} />
          </AnalyticsPanel>

          <AnalyticsPanel title="Action performance" subtitle="Recommended-action workflow health and post-fix measurement readiness" className="ppAnalyticsPanelActionPerformance">
            <ActionPerformancePanel performance={actionPerformance} />
          </AnalyticsPanel>

          <AnalyticsPanel title="Catalog coverage" subtitle="How representative the current analytics set is" className="ppAnalyticsPanelCatalogCoverage">
            <CatalogCoveragePanel coverage={catalogCoverage} />
          </AnalyticsPanel>

          <AnalyticsPanel title="Evidence source coverage" subtitle="Evidence coverage, contribution and source state" className="ppAnalyticsPanelSourceCoverage">
            <EvidenceSourceCoveragePanel rows={evidenceSourceCoverage} />
          </AnalyticsPanel>
        </div>

        <div className="ppAnalyticsBottom">
          <AnalyticsPanel title="Top products at risk" subtitle="Top 5 products ranked by operational priority" className="ppAnalyticsPanelTopProducts">
            <TopProductsAtRiskTable rows={topProductsAtRisk} />
          </AnalyticsPanel>

          <s-section padding="none">
            <div className="ppAnalyticsPanel ppBusinessImpactPanel">
              <div className="ppAnalyticsPanelHeader">
                <div>
                  <h2>
                    {businessImpact.title}
                    <AnalyticsInfoPopover info={getAnalyticsPanelInfo(businessImpact.title)} />
                  </h2>
                  <p>{businessImpact.subtitle}</p>
                </div>
              </div>
              <div className="ppBusinessImpactGrid">
                {businessImpact.metrics.map((metric) => (
                  <AnalyticsImpactMetric key={metric.label} metric={metric} />
                ))}
              </div>
              <button className="ppAnalyticsInfoLink" type="button" onClick={() => setBusinessImpactOpen(true)}>
                <s-icon type="info" size="small"></s-icon>
                Learn how ProductPulse AI improves these outcomes
              </button>
            </div>
          </s-section>
        </div>
        {businessImpactOpen && (
          <BusinessImpactInfoModal
            businessImpact={businessImpact}
            windowLabel={analyticsView.windowLabel || "Stored scan window"}
            onClose={() => setBusinessImpactOpen(false)}
          />
        )}
          </div>

          {analyticsInitialLoading && (
            <div className="ppDashboardDataOverlay" role="status" aria-live="polite">
              <span className="ppDashboardDataSpinner" aria-hidden="true">
                <i></i>
                <i></i>
                <i></i>
              </span>
              <strong>Loading Analytics data</strong>
              <small>Preparing risk trends, impact charts and coverage.</small>
            </div>
          )}
        </div>
      </ScreenShell>
    </FullWidthPage>
  );
}

