function getMomentumCatalogComparisonLabel(momentum = {}) {
  const catalogProductCount = Number(momentum.catalog?.catalogProductCount || 0);
  if (catalogProductCount > 0) return `${formatInteger(catalogProductCount)} products compared`;
  if (momentum.catalog?.hasCatalogBaseline) return "Catalog baseline available";
  return "Catalog baseline pending";
}

function getProductDetailHref(product = {}) {
  if (product.href) return product.href;
  const identifier = product.handle || product.slug || product.id;
  return identifier ? `/app/products/${identifier}` : "/app/products";
}

function getProductMetricTimelinesHref(product = {}) {
  return `${getProductDetailHref(product)}/metric-timelines`;
}

function getProductEvidenceSourceHref(product = {}, source = null, fallbackHref = "") {
  const baseEvidenceHref = fallbackHref || `${getProductDetailHref(product)}/evidence`;
  if (!source) return baseEvidenceHref;
  const sourceToken = normalizeSourceToken(source);
  const sourceLabel = sourceToken.label || sourceToken.title || "";
  return sourceLabel ? `${getProductDetailHref(product)}/evidence?source=${encodeURIComponent(sourceLabel)}` : baseEvidenceHref;
}

function ProductSignalCell({ product }) {
  const signalCount = Number(product.signals || product.signalCount || 0);
  const sourceCount = getProductEvidenceSourceCount(product);
  const strengthLabel = product.signalStrengthLabel || getEvidenceStrengthLabel({ signalCount, sourceCount });
  const values = getProductSignalValues(product, signalCount, sourceCount);
  const tone = product.signalTone || getEvidenceTone(product, signalCount);
  const evidenceHref = `${getProductDetailHref(product)}/evidence`;

  return (
    <Link className="ppSignalTrigger" to={evidenceHref} aria-label={`Open evidence for ${product.title}`}>
      <span className="ppSignalTriggerMain">
        <SignalBars tone={tone} values={values} />
        <span>{signalCount}</span>
      </span>
      <span className="ppSignalStrengthLine">{strengthLabel} · {sourceCount} source{sourceCount === 1 ? "" : "s"}</span>
    </Link>
  );
}

function getProductEvidenceSourceCount(product = {}) {
  const sourceCount = Number(product.sourceCount || 0);
  if (sourceCount > 0) return sourceCount;
  const sourceTokens = Array.isArray(product.sources) ? product.sources.length : 0;
  return Math.max(sourceTokens + Number(product.sourceOverflow || 0), 0);
}

function getProductSignalValues(product = {}, signalCount = 0, sourceCount = 0) {
  if (Array.isArray(product.signalBars) && product.signalBars.length > 0) {
    return product.signalBars.map((value) => Number(value || 0));
  }

  const normalizedSignalCount = Math.max(0, Number(signalCount || 0));
  if (!normalizedSignalCount) return [4, 4, 4];
  const activeBars = Math.max(1, Math.min(3, Number(sourceCount || 1)));
  const height = Math.min(100, Math.max(18, normalizedSignalCount * 8));
  return Array.from({ length: 3 }, (_, index) => (index < activeBars ? height : 8));
}

function getEvidenceStrengthLabel({ signalCount, sourceCount, conflicting = false }) {
  if (conflicting) return "Conflicting";
  if (signalCount >= 10 && sourceCount >= 3) return "Strong";
  if (signalCount >= 5 || sourceCount >= 2) return "Moderate";
  if (signalCount >= 1) return sourceCount <= 1 ? "Sparse" : "Weak";
  return "Sparse";
}

function getEvidenceTone(product, signalCount) {
  if (signalCount <= 0) return "gray";
  const normalized = String(product.risk || product.riskLabel || product.signalTone || "").toLowerCase();
  if (normalized.includes("high") || normalized.includes("red") || normalized.includes("critical")) return "red";
  if (normalized.includes("medium") || normalized.includes("watch") || normalized.includes("orange") || normalized.includes("warning")) return "orange";
  return "green";
}

function SignalBars({ values, tone }) {
  return (
    <span className={`ppSignalBars ppSignalBars-${tone}`} aria-hidden="true">
      {values.map((value, index) => (
        <span key={`${value}-${index}`} style={{ height: `${value}%` }} />
      ))}
    </span>
  );
}

function FloatingTablePopover({
  anchorRef,
  open,
  className = "",
  width = 320,
  estimatedHeight = 220,
  placement = "bottom-start",
  role = "tooltip",
  children,
  onMouseEnter,
  onMouseLeave,
}) {
  const style = useFloatingTablePopoverStyle(anchorRef, open, { width, estimatedHeight, placement });
  if (!open || !style || typeof document === "undefined") return null;

  return createPortal(
    <div
      className={`${className} ppFloatingTablePopover`.trim()}
      role={role}
      style={style}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      {children}
    </div>,
    document.body,
  );
}

function useFloatingTablePopoverStyle(anchorRef, open, { width = 320, estimatedHeight = 220, placement = "bottom-start" } = {}) {
  const [style, setStyle] = useState(null);

  useEffect(() => {
    if (!open || typeof window === "undefined") {
      setStyle(null);
      return undefined;
    }

    const update = () => {
      const anchor = anchorRef.current;
      if (!anchor) return;
      const rect = anchor.getBoundingClientRect();
      const margin = 12;
      const offset = 8;
      const viewportWidth = window.innerWidth || 0;
      const viewportHeight = window.innerHeight || 0;
      let left = rect.left;

      if (placement.endsWith("end")) {
        left = rect.right - width;
      } else if (placement.endsWith("center")) {
        left = rect.left + rect.width / 2 - width / 2;
      }

      left = Math.max(margin, Math.min(left, viewportWidth - width - margin));

      const preferredBelow = rect.bottom + offset;
      const preferredAbove = rect.top - estimatedHeight - offset;
      const wantsTop = placement.startsWith("top");
      const top = wantsTop
        ? (preferredAbove >= margin ? preferredAbove : Math.min(preferredBelow, viewportHeight - estimatedHeight - margin))
        : (preferredBelow + estimatedHeight <= viewportHeight - margin ? preferredBelow : Math.max(margin, preferredAbove));

      setStyle({
        position: "fixed",
        top: `${Math.round(top)}px`,
        left: `${Math.round(left)}px`,
        width: `${width}px`,
        zIndex: 10000,
      });
    };

    update();
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, true);
    return () => {
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", update, true);
    };
  }, [anchorRef, open, width, estimatedHeight, placement]);

  return style;
}

