function OrdersEvidencePanel({ source, product, reportHref }) {
  const metrics = product.metrics || {};
  const activity = normalizeProductMonthlyOrderActivity(metrics.monthlyOrderActivity);
  const purchaseContext = normalizeProductPurchaseContext(
    metrics.productPurchaseContextSummary || metrics.purchaseContextSummary || product.productPurchaseContext || product.purchaseContext,
    metrics.productPurchaseContextFactors,
    metrics,
  );
  const summary = activity.summary || {};
  const unitsSold = Number(summary.totalOrderUnits || metrics.soldUnits || 0);
  const orderCount = Number(summary.totalOrders || metrics.orderCount || metrics.ordersLast30Days || 0);
  const revenue = Number(summary.totalRevenue || metrics.salesAmount || metrics.revenueLast30Days || metrics.revenueAtRisk || 0);
  const windowDays = Number(activity.windowDays || metrics.windowDays || 365);
  const aov = orderCount ? revenue / orderCount : Number(metrics.avgOrderValue || metrics.avgUnitRevenue || 0);
  const velocity = windowDays ? unitsSold / windowDays : 0;
  const channelRows = getOrderChannelRows(metrics, orderCount);
  const geographyRows = getOrderGeographyRows(metrics, orderCount);
  const insightRows = [
    { label: "Units sold in window", value: formatInteger(unitsSold), detail: "Units sold in window", tone: "blue" },
    { label: "Order window", value: formatInteger(windowDays), detail: "Order window", tone: "violet" },
    { label: "Total signals detected", value: formatInteger(metrics.signalCount || source.points.length), detail: "Total signals detected", tone: "blue" },
  ];

  return (
    <div className="ppEvidenceSourcePanel ppEvidenceSourcePanel-specialized ppOrdersEvidenceReport">
      <EvidenceSourceReportHeader source={source} title="Shopify orders" eyebrow="Orders" summary="Order data establishes baseline sold units, velocity and demand context." />

      <div className="ppEvidenceHeroMetricStrip ppEvidenceHeroMetricStrip-four">
        <EvidenceSourceStatCard icon="cash-dollar" label="Units sold" value={formatInteger(unitsSold)} detail="Sold in scan window" tone="teal" />
        <EvidenceSourceStatCard icon="cash-dollar" label="Orders" value={formatInteger(orderCount)} detail="Orders in scan window" tone="teal" />
        <EvidenceSourceStatCard icon="clock" label="Order window" value={`${formatInteger(windowDays)} days`} detail="Analysis window" tone="blue" />
        <EvidenceSourceStatCard icon="cash-dollar" label="AOV" value={formatMoney(aov)} detail="Average order value" tone="blue" />
      </div>

      <div className="ppReturnsEvidenceGrid">
        <section className="ppEvidenceReportSectionCard ppOrdersLineChartCard">
          <h4>Units sold over time</h4>
          <p>Units, order count, units per order and product share inside each basket</p>
          <EvidenceOrdersLineChart months={activity.months} fallbackValue={unitsSold} purchaseContext={purchaseContext} />
        </section>
        <section className="ppEvidenceReportSectionCard ppOrderVelocityCard">
          <h4>Order velocity</h4>
          <p>By units per day</p>
          <strong>{formatDecimal(velocity, 3)}</strong>
          <small>Units per day (avg)</small>
          <MiniTrend tone="violet" values={activity.months.map((month) => Number(month.orderUnits || month.orders || 0))} />
        </section>
      </div>

      <div className="ppEvidenceTwoColumnGrid">
        <section className="ppEvidenceReportSectionCard">
          <h4>Sales by channel</h4>
          <p>By sold units</p>
          <EvidenceBarList rows={channelRows} tone="violet" emptyLabel="No channel data stored" />
        </section>
        <section className="ppEvidenceReportSectionCard">
          <h4>Geography</h4>
          <p>By order origin</p>
          <EvidenceBarList rows={geographyRows} tone="blue" emptyLabel="No geography data stored" />
        </section>
      </div>

      <div className="ppReturnsDetailMetricGrid">
        <EvidenceSourceStatCard icon="product" label="Vendor" value={metrics.vendor || "Not stored"} detail="Vendor" tone="blue" />
        <EvidenceSourceStatCard icon="tag" label="Product type" value={metrics.productType || "Not stored"} detail="Product type" tone="blue" />
        <EvidenceSourceStatCard icon="duplicate" label="Collections" value={formatInteger(getEvidenceList(metrics.collections).length)} detail="Collections" tone="blue" />
        <EvidenceSourceStatCard icon="note" label="Signal count" value={formatInteger(metrics.signalCount || source.points.length)} detail="Total signals" tone="blue" />
      </div>

      <div className="ppEvidenceBottomReportGrid">
        <section className="ppEvidenceReportSectionCard">
          <h4>Order insights</h4>
          <div className="ppEvidenceMiniInsightGrid">
            {insightRows.map((item, index) => (
              <EvidenceMiniInsight key={item.label} label={`Insight ${index + 1}`} value={item.value} detail={item.detail} tone={item.tone} />
            ))}
          </div>
        </section>
        <EvidenceFullReportCard href={reportHref} />
      </div>
    </div>
  );
}

function RetentionEvidencePanel({ source, product }) {
  const metrics = product.metrics || {};
  const retention = normalizeProductRetention(metrics.productRetention || product.productRetention);
  const summary = retention.summary || {};
  const hasData = hasProductRetentionData(retention);
  const cohortRows = useMemo(() => getProductRetentionMonthlyCohortRows(retention.cohortHeatmap), [retention.cohortHeatmap]);
  const repeatChart = useMemo(() => getProductRetentionRepeatChart(retention.timeToRepeatPurchase), [retention.timeToRepeatPurchase]);
  const trendChart = useMemo(() => getProductRetentionTrendChart(retention.dailyRetentionTrend), [retention.dailyRetentionTrend]);
  const outcomeRows = useMemo(() => getProductRetentionOutcomeRows(retention.nextPurchaseOutcome), [retention.nextPurchaseOutcome]);
  const rangeLabel = getProductRetentionRangeLabel(retention.run, summary) || "No window stored";
  const statusLabel = retention.run?.status ? formatProductRetentionStatus(retention.run.status) : "Unavailable";

  return (
    <div className="ppEvidenceSourcePanel ppEvidenceSourcePanel-specialized ppRetentionEvidenceReport">
      <EvidenceSourceReportHeader source={source} title="Retention" eyebrow="Retention" summary="Product cohorts, repeat purchase timing and follow-on purchase outcomes from deterministic Shopify order metrics." />

      {!hasData ? (
        <EmptyProductDetailState message={getProductRetentionEmptyMessage(summary, retention.run)} />
      ) : (
        <>
          <div className="ppEvidenceHeroMetricStrip ppEvidenceHeroMetricStrip-four">
            <EvidenceSourceStatCard icon="product-momentum" label="90-day repeat" value={formatRetentionRate(summary.repeatPurchaseRate90d)} detail="Any follow-on purchase" tone="teal" />
            <EvidenceSourceStatCard icon="shopify-product" label="Same product" value={formatRetentionRate(summary.sameProductRepurchaseRate90d)} detail="90-day repurchase" tone="blue" />
            <EvidenceSourceStatCard icon="duplicate" label="Cross-sell" value={formatRetentionRate(summary.crossSellRetentionRate90d)} detail="Other products after entry" tone="violet" />
            <EvidenceSourceStatCard icon="profile" label="Cohort customers" value={formatInteger(summary.totalCustomersAnalyzed)} detail="First bought this product in the window" tone="blue" />
          </div>

          <div className="ppEvidenceTwoColumnGrid">
            <section className="ppEvidenceReportSectionCard">
              <h4>Retention window</h4>
              <p>{rangeLabel}</p>
              <div className="ppEvidenceMiniInsightGrid">
                <EvidenceMiniInsight label="Status" value={statusLabel} detail={summary.hasEnoughData ? "Enough data for score" : "Low confidence"} tone={summary.hasEnoughData ? "teal" : "amber"} />
                <EvidenceMiniInsight label="Product orders" value={formatInteger(summary.totalProductOrdersAnalyzed)} detail="Orders containing this product" tone="blue" />
                <EvidenceMiniInsight label="Median second purchase" value={formatRetentionDays(summary.medianDaysToSecondPurchase)} detail="Customer return timing" tone="violet" />
              </div>
            </section>
            <section className="ppEvidenceReportSectionCard">
              <h4>Retention value</h4>
              <p>LTV and returning behavior for customers entering through this product.</p>
              <div className="ppEvidenceMiniInsightGrid">
                <EvidenceMiniInsight label="LTV 90" value={formatRetentionMoneyCents(summary.productLtv90Cents)} detail="Per cohort customer" tone="teal" />
                <EvidenceMiniInsight label="LTV 180" value={formatRetentionMoneyCents(summary.productLtv180Cents)} detail="Per cohort customer" tone="blue" />
                <EvidenceMiniInsight label="Health score" value={summary.retentionHealthScore == null ? "N/A" : `${formatInteger(summary.retentionHealthScore)}/100`} detail="Retention score" tone={summary.hasEnoughData ? "teal" : "amber"} />
              </div>
            </section>
          </div>

          <div className="ppRetentionEvidenceChartGrid">
            <ProductRetentionRepeatCurve chart={repeatChart} productTitle={product.title} />
            <ProductRetentionCohortHeatmap rows={cohortRows} />
            <ProductRetentionTrendChart chart={trendChart} productTitle={product.title} />
            <ProductRetentionNextOutcome rows={outcomeRows} />
          </div>
        </>
      )}
    </div>
  );
}

